INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C1','sci',6,2,'u3',1,'줄 전구 세트로 빛나는 작품 만들기 — 꾸미고 싶은 그림을 도화지에 그림 → 줄 전구 세트를 셀로판테이프로 붙여 꾸밈 → 전원을 켜 완성 → 전시하고 감상 · 줄 전구는 작품 앞면에 붙이고 도화지에 구멍을 뚫어 뒤에서 붙이는 방법은 피함 · 평면 그림뿐 아니라 도화지 모양 틀에 감는 입체 작품도 됨',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C2','sci',6,2,'u3',1,'작품 활동의 안전과 감상 — 젖은 손으로 줄 전구 세트를 만지지 않고 활동 전에 책상 위 물병을 치움 · 감상할 때는 작품의 어느 부분에 줄 전구가 쓰였는지 살피고 잘된 부분을 찾아 칭찬함 · 전기로 아름다운 작품을 만들 수 있음',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C3','sci',6,2,'u3',1,'줄 전구에 불을 켜려면 — 전지가 있어야 하고 줄 전구 세트의 전원을 켜 전기가 흐르게 해야 함 · 다음 차시의 전기 회로로 이어짐',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C4','sci',6,2,'u3',2,'전기 부품이 하는 일 — 전지는 전기 에너지를 공급 · 전선을 따라 전기가 흐름 · 전구는 전기가 흐르면 불이 켜짐 · 스위치를 닫으면 모두 이어지고 열면 끊어짐 · 전지 끼우개·전구 끼우개·집게 달린 전선으로 부품을 이음 · 전기 부품을 서로 이어 전기가 흐를 수 있게 한 것이 전기 회로',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C5','sci',6,2,'u3',2,'불이 켜지는 전기 회로의 특징 — 전기 부품이 전지의 (+)극부터 (−)극까지 끊어진 곳 없이 이어져 있음 · 불이 켜지지 않는 회로는 이음이 끊어져 있거나 전지의 (+)극이나 (−)극 한쪽에만 이어져 있음',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C6','sci',6,2,'u3',2,'스위치와 손전등 — 스위치를 닫으면 끊어져 있던 곳이 이어져 전구에 불이 켜지고, 열면 다시 끊어져 꺼짐 · 손전등 스위치를 누르면 안에서 끊어져 있던 부분이 이어짐',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C7','sci',6,2,'u3',2,'전기가 흐르는 물질과 잘 흐르지 않는 물질 — 스위치 자리에 플라스틱 막대·고무 막대를 이으면 불이 켜지지 않고 금속 막대를 이으면 켜짐 · 플라스틱·고무·금속 가운데 전기가 흐르는 물질은 금속 · 비닐·종이·유리도 전기가 잘 흐르지 않음 · 새 물건의 전지 칸에 비닐을 끼워 두는 것은 전기가 흐르지 않게 해 전지가 닳지 않게 하려는 것',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C8','sci',6,2,'u3',2,'전기 부품의 금속 부분끼리 잇기 — 전구는 유리와 금속, 스위치는 플라스틱과 금속, 전지 끼우개는 플라스틱과 금속으로 되어 있음 · 회로를 만들 때는 전기가 흐르는 금속 부분끼리 닿게 이어야 함 · 전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 아랫면에서 이어져 있음',ARRAY['[6과15-01] 전지와 전구, 전선을 연결하여 전구에 불을 켜 보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C9','sci',6,2,'u3',3,'전지의 직렬연결 — 한 전지의 (+)극을 다른 전지의 (−)극에 잇는 방법 · 이 단원에서 전지는 직렬연결만 다룸',ARRAY['[6과15-02] 전지 한 개를 연결한 전기 회로와 전지 두 개를 직렬연결한 전기 회로의 특징을 비교할 수 있다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C10','sci',6,2,'u3',3,'전지 두 개를 직렬연결한 전기 회로의 특징 — 전지 한 개를 이은 회로보다 전구가 더 밝게 빛나고, 전동기 날개가 더 빠르게 돌고, 버저 소리가 더 크게 남 · 직렬로 이은 전지의 개수가 많을수록 그렇게 됨 · 견줄 때는 전지 개수만 다르게 하고 나머지 부품은 같게',ARRAY['[6과15-02] 전지 한 개를 연결한 전기 회로와 전지 두 개를 직렬연결한 전기 회로의 특징을 비교할 수 있다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C11','sci',6,2,'u3',3,'방향을 가리는 전기 부품 — 버저·발광 다이오드는 전지를 잇는 방향에 따라 작동하지 않을 수 있음 · 작동하지 않으면 잇는 방향부터 확인함',ARRAY['[6과15-02] 전지 한 개를 연결한 전기 회로와 전지 두 개를 직렬연결한 전기 회로의 특징을 비교할 수 있다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C12','sci',6,2,'u3',4,'전자석 만들기 — 둥근 머리 볼트(철 막대)에 종이를 감아 셀로판테이프로 고정 → 종이 위에 에나멜선을 한쪽 방향으로 촘촘히 감음(양 끝은 조금 남김) → 에나멜선 양 끝을 사포로 문질러 코팅을 벗긴 부분을 회로에 이음 · 날카로운 끝에 찔리지 않게, 젖은 손으로 하지 않게',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C13','sci',6,2,'u3',4,'전기가 흐를 때만 자석이 되는 전자석 — 스위치를 닫기 전에는 둥근 철 고리가 붙지 않고, 닫은 뒤에는 붙음 · 전자석은 전기가 흐를 때만 자석의 성질을 나타냄 · 스위치를 오래 닫아 두면 전자석이 뜨거워지니 필요할 때만 닫음',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C14','sci',6,2,'u3',4,'전자석의 세기 조절 — 전자석에 직렬로 이은 전지의 개수가 많을수록 세기가 세져 둥근 철 고리가 더 많이 붙음 · 영구 자석의 세기는 일정함',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C15','sci',6,2,'u3',4,'전자석의 극 바꾸기 — 전자석에 이은 전지의 방향을 반대로 바꾸면 전자석의 양쪽 극이 반대로 바뀜 · 전자석 양쪽 끝에 놓은 나침반 바늘이 가리키는 방향으로 극을 알아냄(나침반 바늘도 자석, 같은 극끼리 밀고 다른 극끼리 당김), 바늘이 완전히 멈춘 뒤에 봄 · 영구 자석의 극은 일정함',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C16','sci',6,2,'u3',5,'전자석을 사용하는 예 — 선풍기(전자석을 쓴 전동기가 돌아 바람을 일으킴), 스피커, 전자석 기중기, 전기 자동차(바퀴가 돎), 세탁기(통을 돌림), 로봇 청소기, 몸속을 찍는 자기 공명 영상 장치 · 전기가 흐를 때만 떠 있는 장난감 · 자석 낚시 놀이는 전자석이 아님',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C17','sci',6,2,'u3',5,'전자석의 성질과 쓰임새 — 세기를 조절하는 성질로 선풍기 바람의 세기·스피커 소리의 크기를 조절 · 세기를 조절하고 전기가 흐를 때만 자석이 되는 성질로 전자석 기중기가 철로 만든 무거운 물체를 들어 원하는 곳에 내려놓음 · 영구 자석으로 기중기를 만들면 물체를 내려놓기 어려움',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C18','sci',6,2,'u3',5,'조사하고 공유하기 — 스마트 기기로 검색해 공유 공간에 올림 · 검색한 자료를 쓸 때는 출처를 밝히고 다른 사람의 창작물을 허락 없이 쓰지 않음 · 댓글은 바르고 고운 말로, 잘한 점을 찾아 칭찬 · 유해 사이트에 들어가지 않음',ARRAY['[6과15-03] 전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C19','sci',6,2,'u3',6,'전기를 효율적으로 사용하는 방법 — 효율적으로 쓴다는 것은 낭비되거나 손실되는 전기를 줄이는 것 · 에너지 소비 효율 등급이 높은(1등급에 가까운) 제품, 형광등 대신 LED등, 에너지를 아끼는 기능이 있는 제품, 센서 등 · 쓰지 않을 때 전원을 끄고 플러그를 뽑음(꽂아 두기만 해도 쓰이는 대기 전력) · 냉장고 문을 자주 여닫지 않음 · 냉난방 알맞은 온도',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C20','sci',6,2,'u3',6,'전기를 안전하게 사용하는 방법 — 젖은 손으로 전기 기구를 만지지 않고 물기 있는 곳에서 쓰지 않음 · 플러그는 머리 부분을 잡고 뽑음 · 한 콘센트에 여러 플러그를 한꺼번에 꽂지 않음 · 안 쓰는 콘센트에는 안전 덮개(먼지·물) · 콘센트 주위의 타기 쉬운 물건을 치움 · 감전은 전기가 통하는 물체에 몸이 닿아 충격을 받는 것 · 역할놀이에는 실제 전기 기구 대신 모형 소품',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C21','sci',6,2,'u3',6,'효율적이고 안전하게 써야 하는 까닭과 표현 — 전기를 아껴 자원 낭비를 줄이고 환경을 지킴 · 감전 사고와 화재를 막음 · 안전하고 지속가능한 사회 · 과학 글쓰기·그림 그리기·역할놀이로 표현하고 일상생활과 이어 실천으로',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C22','sci',6,2,'u3',7,'실천 계획 세우고 점검하기 — 효율적이고 안전한 전기 사용 방법 가운데 내가 지킬 수 있는 것으로 구체적인 계획을 세움 · 실천 점검표에 날마다 기록하며 습관이 되게 꾸준히 실천',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C23','sci',6,2,'u3',7,'실천 결과 발표하고 나누기 — 실천한 결과와 느낀 점을 발표 · 친구의 발표를 비판하거나 비난하지 않고 잘한 점을 찾음 · 가족과 함께 실천하면 전기 요금도 줄어듦',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C24','sci',6,2,'u3',8,'전기 사용을 돕는 스마트 홈 기술 — 인공지능이 건물의 냉난방 온도나 조명 밝기를 알아서 조절해 전기를 효율적으로 쓰게 도움 · 센서 등처럼 필요할 때만 켜지는 기술 · 기술이 있어도 사람의 실천이 함께 필요함',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C25','sci',6,2,'u3',8,'인공지능과 전기 사용 토론 — 인공지능은 전기 사용량을 크게 늘려 정전·과부하 화재·석탄과 석유 사용 증가로 이어질 수 있다는 의견과, 전기를 효율적으로 쓰도록 돕고 기술 발전으로 문제를 줄일 수 있다는 의견이 있음 · 한 입장을 골라 타당한 근거를 들어 주장함',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u3-C26','sci',6,2,'u3',8,'전기의 이용 정리 — 불이 켜지는 전기 회로(끊어진 곳 없이 · 금속 부분끼리) · 전지의 직렬연결(더 밝게·더 빠르게·더 크게) · 전자석(전기가 흐를 때만 · 세기와 극을 바꿈)과 쓰임새 · 전기를 효율적이고 안전하게 함께 챙겨 씀',ARRAY['[6과15-04] 전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X01','sci',6,'u3',ARRAY['SC6-2-u3-C3']::text[],'전지나 전원 없이도 줄 전구가 빛난다고 여긴다','전지와 전원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X02','sci',6,'u3',ARRAY['SC6-2-u3-C1']::text[],'작품 만드는 차례를 뒤섞는다(전원부터 켜거나 감상부터 함)','그리고 → 붙이고 → 켜고 → 감상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X03','sci',6,'u3',ARRAY['SC6-2-u3-C1']::text[],'도화지에 구멍을 뚫어 뒤에서 붙이는 것이 낫다고 여기거나 줄 전구는 평면 작품에만 쓴다고 여긴다','앞면에 · 입체도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X04','sci',6,'u3',ARRAY['SC6-2-u3-C2']::text[],'젖은 손이나 책상 위 물병 같은 물기 안전을 놓친다','물기는 멀리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X05','sci',6,'u3',ARRAY['SC6-2-u3-C2']::text[],'감상할 때 전구 개수나 흠만 보고 잘된 점과 줄 전구가 쓰인 자리를 보지 않는다','잘된 점을 찾아 칭찬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X06','sci',6,'u3',ARRAY['SC6-2-u3-C5']::text[],'전지의 한쪽 극에만 부품을 이어도 불이 켜진다고 여긴다','(+)극부터 (−)극까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X07','sci',6,'u3',ARRAY['SC6-2-u3-C5']::text[],'이음이 끊어진 곳이 있어도 불이 켜진다고 여긴다','끊어진 곳 없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X08','sci',6,'u3',ARRAY['SC6-2-u3-C6']::text[],'스위치를 열면 켜지고 닫으면 꺼진다고 바꾸어 안다','닫으면 이어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X09','sci',6,'u3',ARRAY['SC6-2-u3-C7']::text[],'플라스틱·고무·비닐처럼 전기가 잘 흐르지 않는 물질로 이어도 불이 켜진다고 여긴다','금속 막대만 켜졌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X10','sci',6,'u3',ARRAY['SC6-2-u3-C8']::text[],'전기 부품의 플라스틱·유리·고무 부분끼리 닿게 이어도 전기가 흐른다고 여긴다','금속 부분끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X11','sci',6,'u3',ARRAY['SC6-2-u3-C8']::text[],'전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 끊어져 있다고 여긴다','아랫면에서 이어져 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X12','sci',6,'u3',ARRAY['SC6-2-u3-C4']::text[],'전기 부품이 하는 일을 서로 바꾸어 안다(전선이 전기를 만들고 전지가 빛을 냄)','전지는 전기를 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X13','sci',6,'u3',ARRAY['SC6-2-u3-C7']::text[],'새 물건 전지 칸에 끼운 비닐을 전기가 잘 흐르게 하려고 넣은 것으로 여긴다','막아서 아껴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X14','sci',6,'u3',ARRAY['SC6-2-u3-C9']::text[],'직렬연결을 (+)극끼리나 (−)극끼리 맞대어 잇는 것으로 여긴다','(+)극과 다른 전지 (−)극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X15','sci',6,'u3',ARRAY['SC6-2-u3-C10']::text[],'전지 두 개를 직렬연결해도 전구 밝기가 같거나 더 어두워진다고 여긴다','더 밝아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X16','sci',6,'u3',ARRAY['SC6-2-u3-C10']::text[],'전지를 직렬로 더 이어도 전동기·버저는 그대로이거나 약해진다고 여긴다','더 빠르게 · 더 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X17','sci',6,'u3',ARRAY['SC6-2-u3-C11']::text[],'버저·발광 다이오드는 전지를 어느 방향으로 이어도 늘 작동한다고 여긴다','방향을 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X18','sci',6,'u3',ARRAY['SC6-2-u3-C10']::text[],'전지 개수 말고 다른 부품까지 바꾸어 놓고 견준다','전지 개수만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X19','sci',6,'u3',ARRAY['SC6-2-u3-C13']::text[],'전자석은 전기가 흐르지 않아도 늘 자석의 성질을 띤다고 여긴다','전기가 흐를 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X20','sci',6,'u3',ARRAY['SC6-2-u3-C14']::text[],'전자석의 세기는 바꿀 수 없거나 전지를 더 이으면 약해진다고 여긴다','전지가 많을수록 세게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X21','sci',6,'u3',ARRAY['SC6-2-u3-C15']::text[],'전지의 방향을 바꾸어도 전자석의 극은 그대로라고 여긴다','방향을 바꾸면 극도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X22','sci',6,'u3',ARRAY['SC6-2-u3-C14','SC6-2-u3-C15']::text[],'영구 자석도 세기와 극을 마음대로 바꿀 수 있다고 여긴다','영구 자석은 일정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X23','sci',6,'u3',ARRAY['SC6-2-u3-C12']::text[],'에나멜선 끝을 문지르지 않아 코팅이 남은 채로 이어도 된다고 여긴다','사포로 문질러요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X24','sci',6,'u3',ARRAY['SC6-2-u3-C12']::text[],'에나멜선을 방향을 바꿔 가며 성글게 감아도 된다고 여긴다','한쪽 방향 · 촘촘히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X25','sci',6,'u3',ARRAY['SC6-2-u3-C15']::text[],'나침반 바늘이 움직이는 동안 극을 읽거나 나침반으로는 극을 알 수 없다고 여긴다','멈춘 뒤 · 바늘도 자석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X26','sci',6,'u3',ARRAY['SC6-2-u3-C13']::text[],'스위치를 오래 닫아 두어도 괜찮다고 여긴다','필요할 때만 닫기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X27','sci',6,'u3',ARRAY['SC6-2-u3-C16']::text[],'영구 자석만 쓰는 물건(자석 낚시 놀이)을 전자석의 예로 고른다','전기가 흐르나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X28','sci',6,'u3',ARRAY['SC6-2-u3-C17']::text[],'전자석이 쓰인 물건과 쓰임새를 바꾸어 짝짓는다','무엇을 조절하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X29','sci',6,'u3',ARRAY['SC6-2-u3-C17']::text[],'영구 자석으로 기중기를 만들어도 물체를 쉽게 내려놓을 수 있다고 여긴다','끄면 떨어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X30','sci',6,'u3',ARRAY['SC6-2-u3-C18']::text[],'조사한 자료를 출처 없이 그대로 옮기거나 댓글을 함부로 쓴다','출처 · 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X31','sci',6,'u3',ARRAY['SC6-2-u3-C19']::text[],'전원을 끄면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않는다고 여긴다','대기 전력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X32','sci',6,'u3',ARRAY['SC6-2-u3-C19']::text[],'에너지 소비 효율 등급 숫자가 클수록 효율이 높다고 여긴다','1등급에 가까울수록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X33','sci',6,'u3',ARRAY['SC6-2-u3-C19']::text[],'효율적으로 쓰는 것을 전기를 많이·세게 쓰는 것으로 여기거나 낭비하는 행동을 고른다','낭비·손실 줄이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X34','sci',6,'u3',ARRAY['SC6-2-u3-C20']::text[],'플러그를 뽑을 때 전선을 잡아당긴다','머리 부분을 잡고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X35','sci',6,'u3',ARRAY['SC6-2-u3-C20']::text[],'한 콘센트에 여러 플러그를 한꺼번에 꽂아도 안전하다고 여긴다','한꺼번에 꽂지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X36','sci',6,'u3',ARRAY['SC6-2-u3-C20']::text[],'젖은 손이나 물기 있는 곳에서 전기 기구를 써도 괜찮다고 여긴다','물기는 위험') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X37','sci',6,'u3',ARRAY['SC6-2-u3-C20']::text[],'안 쓰는 콘센트를 그대로 두거나 콘센트 주위에 타기 쉬운 물건을 두어도 괜찮다고 여긴다','안전 덮개 · 치우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X38','sci',6,'u3',ARRAY['SC6-2-u3-C21']::text[],'전기를 효율적이고 안전하게 써야 하는 까닭을 엉뚱하게 여긴다(전기는 끝없이 있다, 안전은 어른 몫)','절약 · 사고 예방') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X39','sci',6,'u3',ARRAY['SC6-2-u3-C22']::text[],'지킬 수 없거나 막연한 실천 계획을 세운다','내가 할 수 있는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X40','sci',6,'u3',ARRAY['SC6-2-u3-C22']::text[],'한 번 실천하면 끝이라 여기고 점검·기록하지 않는다','점검표로 꾸준히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X41','sci',6,'u3',ARRAY['SC6-2-u3-C23']::text[],'친구의 발표나 잘못된 경험을 비난한다','잘한 점 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X42','sci',6,'u3',ARRAY['SC6-2-u3-C24']::text[],'스마트 홈 기술이 전기를 효율적으로 쓰는 것과 상관없다고 여기거나 기술만 있으면 사람은 신경 쓸 필요 없다고 여긴다','알아서 조절 · 실천도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X43','sci',6,'u3',ARRAY['SC6-2-u3-C25']::text[],'인공지능 기술의 한쪽 면만 본다(전기를 전혀 쓰지 않는다거나, 쓰기만 하고 돕는 일은 없다)','늘리기도 돕기도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X44','sci',6,'u3',ARRAY['SC6-2-u3-C25']::text[],'근거 없이 주장만 하거나 상대 의견을 깎아내린다','타당한 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u3-X45','sci',6,'u3',ARRAY['SC6-2-u3-C26']::text[],'전기를 아끼는 것과 안전하게 쓰는 것 가운데 하나만 챙기면 된다고 여긴다','둘 다 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#1','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C3',1,'mc','auto','줄 전구 세트에 불을 켜려면 꼭 있어야 하는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C3","difficulty":1,"kind":"mc","stem":"줄 전구 세트에 불을 켜려면 꼭 있어야 하는 것은 어느 것인가요?","options":[{"t":"전지","correct":true},{"t":"셀로판테이프","mis":"SC6-2-u3-X01"},{"t":"도화지","mis":"SC6-2-u3-X01"},{"t":"그림 도구","mis":"SC6-2-u3-X01"}],"explanation":["불을 켜려면 전기가 필요해요.","전기를 주는 것은 전지예요.","전지가 꼭 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#2','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C2',1,'ox','auto','젖은 손으로 줄 전구 세트를 만지지 않아요.',ARRAY['SC6-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":1,"kind":"ox","stem":"젖은 손으로 줄 전구 세트를 만지지 않아요.","answer":"O","reason_options":[{"t":"물기가 있는 손으로 전기 제품을 만지면 위험하기 때문에","correct":true},{"t":"손에 물이 묻으면 줄 전구가 더 밝게 빛나기 때문에","mis":"SC6-2-u3-X04"}],"mis":"SC6-2-u3-X04","explanation":["손에 물기가 있어요.","전기 제품은 위험해요.","마른 손으로 만져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#3','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C1',1,'mc','auto','줄 전구 세트를 도화지에 붙여 그림을 꾸밀 때 쓰는 준비물은 어느 것인가요?',ARRAY['SC6-2-u3-X04','SC6-2-u3-X03','SC6-2-u3-X02']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C1","difficulty":1,"kind":"mc","stem":"줄 전구 세트를 도화지에 붙여 그림을 꾸밀 때 쓰는 준비물은 어느 것인가요?","options":[{"t":"셀로판테이프","correct":true},{"t":"물이 든 분무기","mis":"SC6-2-u3-X04"},{"t":"구멍을 뚫는 송곳","mis":"SC6-2-u3-X03"},{"t":"준비물은 필요 없다","mis":"SC6-2-u3-X02"}],"explanation":["줄 전구를 붙여요.","테이프로 고정해요.","셀로판테이프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#4','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C3',1,'sa','auto','줄 전구 세트에서 전기를 주는 부품의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C3","difficulty":1,"kind":"sa","stem":"줄 전구 세트에서 전기를 주는 부품의 이름을 두 글자로 쓰세요.","answer":["전지"],"explanation":["전기를 줘요.","두 글자예요.","전지예요."],"mis":"SC6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#5','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C1',2,'mc','auto','빛나는 작품을 만들 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SC6-2-u3-X02','SC6-2-u3-X03']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C1","difficulty":2,"kind":"mc","stem":"빛나는 작품을 만들 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"꾸미고 싶은 그림을 도화지에 그린다","correct":true},{"t":"전원을 켜 불이 들어오는지 본다","mis":"SC6-2-u3-X02"},{"t":"작품을 전시하고 감상한다","mis":"SC6-2-u3-X02"},{"t":"도화지에 구멍을 여러 개 뚫는다","mis":"SC6-2-u3-X03"}],"explanation":["먼저 그림을 그려요.","그다음 줄 전구를 붙여요.","전원은 그 뒤에 켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#6','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C1',2,'mc','auto','줄 전구 세트를 도화지에 붙이는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X03','SC6-2-u3-X04','SC6-2-u3-X02']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C1","difficulty":2,"kind":"mc","stem":"줄 전구 세트를 도화지에 붙이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품 앞면에 셀로판테이프로 붙인다","correct":true},{"t":"도화지에 구멍을 뚫고 뒷면에서 끼워 붙인다","mis":"SC6-2-u3-X03"},{"t":"물티슈로 닦아 물기가 남은 채로 붙인다","mis":"SC6-2-u3-X04"},{"t":"전원을 켠 채 붙이고 그림은 나중에 그린다","mis":"SC6-2-u3-X02"}],"explanation":["앞면에 붙여요.","구멍 뚫기는 피해요.","테이프로 고정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#7','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C2',2,'mc','auto','친구의 작품을 감상하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X05','SC6-2-u3-X04']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C2","difficulty":2,"kind":"mc","stem":"친구의 작품을 감상하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"잘된 부분을 찾아 칭찬하고, 줄 전구가 쓰인 자리를 살펴본다","correct":true},{"t":"전구를 적게 붙였으면 못한 작품이라고 말한다","mis":"SC6-2-u3-X05"},{"t":"흠을 먼저 찾아 크게 말한다","mis":"SC6-2-u3-X05"},{"t":"물병을 들고 작품 가까이 가서 본다","mis":"SC6-2-u3-X04"}],"explanation":["잘된 점을 찾아요.","줄 전구 자리를 봐요.","서로 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#8','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C3',2,'mc','auto','활동을 마치고 「전구에 불이 켜지려면 무엇이 필요할까?」를 정리했어요. 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C3","difficulty":2,"kind":"mc","stem":"활동을 마치고 「전구에 불이 켜지려면 무엇이 필요할까?」를 정리했어요. 알맞은 것은 어느 것인가요?","options":[{"t":"전지가 있어야 하고, 전원을 켜 전기가 흐르게 해야 한다","correct":true},{"t":"도화지를 크게 하면 저절로 켜진다","mis":"SC6-2-u3-X01"},{"t":"셀로판테이프를 많이 붙이면 켜진다","mis":"SC6-2-u3-X01"},{"t":"햇빛 아래 두면 전지 없이 켜진다","mis":"SC6-2-u3-X01"}],"explanation":["전지가 있어야 해요.","전원을 켜요.","전기가 흘러야 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#9','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C1',2,'ox','auto','줄 전구 세트는 작품 앞면에 붙이는 것이 좋아요.',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C1","difficulty":2,"kind":"ox","stem":"줄 전구 세트는 작품 앞면에 붙이는 것이 좋아요.","answer":"O","reason_options":[{"t":"도화지에 구멍을 뚫어 뒤에서 붙이면 다칠 수 있어 피해야 하기 때문에","correct":true},{"t":"앞면에 붙여야 전지 없이도 불이 켜지기 때문에","mis":"SC6-2-u3-X01"}],"mis":"SC6-2-u3-X01","explanation":["앞면에 붙여요.","구멍 뚫기는 위험해요.","전지는 꼭 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_basic#10','sci',6,2,'u3','L01','g6_2_sci_u3_L01_basic','lesson_basic','SC6-2-u3-C2',3,'error','auto','빛나는 작품을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X04','SC6-2-u3-X05']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C2","difficulty":3,"kind":"error","stem":"빛나는 작품을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「손에 물이 묻었지만 금방 마르니까 그냥 전원을 켜도 돼.」","correct":true,"mis_target":"SC6-2-u3-X04"},{"t":"서진 — 「가로등 자리에 줄 전구를 붙이니 진짜 불이 켜진 것 같아.」","mis":"SC6-2-u3-X05"},{"t":"유나 — 「책상 위 물병은 미리 치워 둘게.」","mis":"SC6-2-u3-X04"}],"explanation":["손에 물기가 있어요.","먼저 물기를 닦아요.","하람의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#1','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C1',2,'match','auto','작품 만들기 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C1","difficulty":2,"kind":"match","stem":"작품 만들기 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"그리기","r":"꾸미고 싶은 그림을 도화지에 그림"},{"l":"꾸미기","r":"줄 전구 세트를 셀로판테이프로 붙임"},{"l":"완성하기","r":"전원을 켜 작품을 빛나게 함"}],"mis":"SC6-2-u3-X02","explanation":["그리기가 먼저예요.","붙여서 꾸며요.","전원을 켜 완성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#2','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C2',2,'mc','auto','활동 전에 책상 위 물병을 미리 치우는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X01','SC6-2-u3-X03','SC6-2-u3-X05']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":2,"kind":"mc","stem":"활동 전에 책상 위 물병을 미리 치우는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물이 쏟아져 줄 전구 세트에 닿으면 위험하기 때문이다","correct":true},{"t":"물을 조금 뿌려야 전구가 더 밝게 빛나기 때문이다","mis":"SC6-2-u3-X01"},{"t":"물병에도 줄 전구를 감아 꾸며야 하기 때문이다","mis":"SC6-2-u3-X03"},{"t":"물병이 있으면 친구 작품을 칭찬할 수 없기 때문이다","mis":"SC6-2-u3-X05"}],"explanation":["물이 쏟아질 수 있어요.","전기 제품에 물은 위험해요.","미리 치워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#3','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C1',3,'mc','auto','빛나는 작품 만들기 메모의 ㉠~㉣을 바른 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X02']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C1","difficulty":3,"kind":"mc","stem":"빛나는 작품 만들기 메모의 ㉠~㉣을 바른 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉢ → ㉠ → ㉣ → ㉡","correct":true},{"t":"㉣ → ㉢ → ㉠ → ㉡","mis":"SC6-2-u3-X02"},{"t":"㉡ → ㉢ → ㉠ → ㉣","mis":"SC6-2-u3-X02"},{"t":"㉠ → ㉢ → ㉡ → ㉣","mis":"SC6-2-u3-X02"}],"explanation":["그림을 먼저 그려요.","붙이고 전원을 켜요.","마지막에 감상해요."],"asset":{"type":"passage","lines":["㉠ 줄 전구 세트를 셀로판테이프로 붙여 그림을 꾸민다.","㉡ 완성한 작품을 전시하고 감상한다.","㉢ 꾸미고 싶은 그림을 도화지에 그린다.","㉣ 전원을 켜 빛나는 작품을 완성한다."],"title":"빛나는 작품 만들기 메모(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#4','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C1',3,'mc','auto','우리 반 빛나는 작품 전시회에서 하린이의 작품을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X03','SC6-2-u3-X01','SC6-2-u3-X05']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C1","difficulty":3,"kind":"mc","stem":"우리 반 빛나는 작품 전시회에서 하린이의 작품을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"줄 전구로 평면 그림뿐 아니라 입체 작품도 만들 수 있다","correct":true},{"t":"줄 전구는 평평한 도화지에만 쓸 수 있다","mis":"SC6-2-u3-X03"},{"t":"입체 작품은 전지 없이 빛난다","mis":"SC6-2-u3-X01"},{"t":"입체 작품은 감상하지 않아도 된다","mis":"SC6-2-u3-X05"}],"explanation":["모양 틀에 감았어요.","입체 작품이에요.","여러 형태가 돼요."],"asset":{"type":"passage","lines":["소은 — 가로등 자리에 줄 전구를 붙인 밤거리 풍경","태오 — 밤하늘 별빛을 줄 전구로 나타낸 그림","하린 — 도화지 모양 틀에 줄 전구를 감은 입체 작품","건우 — 줄 전구를 두른 액자"],"title":"우리 반 빛나는 작품 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#5','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C2',3,'mc','auto','우리 반 빛나는 작품 전시회를 감상하며 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X05','SC6-2-u3-X04']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C2","difficulty":3,"kind":"mc","stem":"우리 반 빛나는 작품 전시회를 감상하며 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「소은이는 가로등 자리에 줄 전구를 붙여서 진짜 밤거리 같아.」","correct":true},{"t":"「건우 작품은 전구 수가 적으니 볼 것도 없어.」","mis":"SC6-2-u3-X05"},{"t":"「모두 별로야. 흠만 잔뜩 보여.」","mis":"SC6-2-u3-X05"},{"t":"「물병을 작품 옆에 두고 보자.」","mis":"SC6-2-u3-X04"}],"explanation":["줄 전구 자리를 봐요.","잘된 점을 말해요.","칭찬하며 감상해요."],"asset":{"type":"passage","lines":["소은 — 가로등 자리에 줄 전구를 붙인 밤거리 풍경","태오 — 밤하늘 별빛을 줄 전구로 나타낸 그림","하린 — 도화지 모양 틀에 줄 전구를 감은 입체 작품","건우 — 줄 전구를 두른 액자"],"title":"우리 반 빛나는 작품 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#6','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C1',3,'error','auto','작품을 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X03','SC6-2-u3-X02']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C1","difficulty":3,"kind":"error","stem":"작품을 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지후 — 「구멍을 뚫고 뒤에서 줄 전구를 끼우는 게 제일 안전해.」","correct":true,"mis_target":"SC6-2-u3-X03"},{"t":"나연 — 「먼저 그림을 그리고 줄 전구를 붙이자.」","mis":"SC6-2-u3-X02"},{"t":"민재 — 「다 붙인 뒤에 전원을 켜서 완성하자.」","mis":"SC6-2-u3-X02"}],"explanation":["앞면에 붙여요.","구멍 뚫기는 피해요.","지후의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#7','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C3',3,'ox','auto','줄 전구 세트의 전원을 끄면 전지가 들어 있어도 불이 켜지지 않아요.',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C3","difficulty":3,"kind":"ox","stem":"줄 전구 세트의 전원을 끄면 전지가 들어 있어도 불이 켜지지 않아요.","answer":"O","reason_options":[{"t":"전원을 켜야 전기가 흘러 불이 켜지기 때문에","correct":true},{"t":"전구는 전기 없이도 혼자 빛을 내기 때문에","mis":"SC6-2-u3-X01"}],"mis":"SC6-2-u3-X01","explanation":["전원을 껐어요.","전기가 흐르지 않아요.","불이 꺼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#8','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C3',4,'mc','auto','어떤 줄 전구 세트는 전원을 켜도 불이 들어오지 않았어요. 가장 먼저 확인할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X01','SC6-2-u3-X04']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C3","difficulty":4,"kind":"mc","stem":"어떤 줄 전구 세트는 전원을 켜도 불이 들어오지 않았어요. 가장 먼저 확인할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"전지가 들어 있는지, 다 닳지 않았는지 살펴본다","correct":true},{"t":"도화지를 더 큰 것으로 바꾼다","mis":"SC6-2-u3-X01"},{"t":"셀로판테이프를 더 많이 감는다","mis":"SC6-2-u3-X01"},{"t":"손에 물을 묻혀 다시 만져 본다","mis":"SC6-2-u3-X04"}],"explanation":["전기가 필요해요.","전지를 살펴요.","물기는 위험해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#9','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C2',4,'mc','auto','감상을 마친 뒤 친구에게 남기는 글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X05','SC6-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C2","difficulty":4,"kind":"mc","stem":"감상을 마친 뒤 친구에게 남기는 글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「별빛을 줄 전구로 나타낸 생각이 멋져. 나도 다음엔 별자리를 꾸며 보고 싶어.」","correct":true},{"t":"「전구를 더 많이 붙였어야지.」","mis":"SC6-2-u3-X05"},{"t":"「네 작품은 내 것보다 못해.」","mis":"SC6-2-u3-X05"},{"t":"「다음엔 물을 뿌려서 더 반짝이게 해 봐.」","mis":"SC6-2-u3-X04"}],"explanation":["잘된 점을 말해요.","배울 점을 찾아요.","서로 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L01_challenge#10','sci',6,2,'u3','L01','g6_2_sci_u3_L01_challenge','lesson_challenge','SC6-2-u3-C3',4,'essay','teacher','빛나는 작품 만들기를 하며 알게 된 점을 바탕으로, 전구에 불이 켜지려면 무엇이 필요한지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C3","difficulty":4,"kind":"essay","stem":"빛나는 작품 만들기를 하며 알게 된 점을 바탕으로, 전구에 불이 켜지려면 무엇이 필요한지 두 가지 쓰세요.","answer_guide":{"answer":"예: 전기를 주는 전지가 있어야 한다. 전원을 켜서 전기가 흐르게 해야 한다.","scoring_points":["전지가 필요하다고 썼는가","전원을 켜 전기가 흐르게 해야 한다고 썼는가"]},"explanation":["전지가 있어야 해요.","전원을 켜요.","전기가 흘러야 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#1','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C4',1,'mc','auto','전기 회로에서 전기 에너지를 공급하는 부품은 어느 것인가요?',ARRAY['SC6-2-u3-X12']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C4","difficulty":1,"kind":"mc","stem":"전기 회로에서 전기 에너지를 공급하는 부품은 어느 것인가요?","options":[{"t":"전지","correct":true},{"t":"전선","mis":"SC6-2-u3-X12"},{"t":"스위치","mis":"SC6-2-u3-X12"},{"t":"전구 끼우개","mis":"SC6-2-u3-X12"}],"explanation":["전기를 주는 부품이에요.","전지예요.","전선은 전기가 흐르는 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#2','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C6',1,'ox','auto','스위치를 닫으면 전구에 불이 켜지는 회로에서, 스위치를 열면 불이 꺼져요.',ARRAY['SC6-2-u3-X08']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C6","difficulty":1,"kind":"ox","stem":"스위치를 닫으면 전구에 불이 켜지는 회로에서, 스위치를 열면 불이 꺼져요.","answer":"O","reason_options":[{"t":"스위치를 열면 회로가 끊어져 전기가 흐르지 않기 때문에","correct":true},{"t":"스위치를 열어야 전기가 더 잘 흐르기 때문에","mis":"SC6-2-u3-X08"}],"mis":"SC6-2-u3-X08","explanation":["스위치를 열어요.","회로가 끊어져요.","불이 꺼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#3','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C7',1,'mc','auto','스위치 자리에 막대를 이어 보았어요. 전구에 불이 켜지는 막대는 어느 것인가요?',ARRAY['SC6-2-u3-X09']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C7","difficulty":1,"kind":"mc","stem":"스위치 자리에 막대를 이어 보았어요. 전구에 불이 켜지는 막대는 어느 것인가요?","options":[{"t":"금속 막대","correct":true},{"t":"플라스틱 막대","mis":"SC6-2-u3-X09"},{"t":"고무 막대","mis":"SC6-2-u3-X09"},{"t":"나무젓가락","mis":"SC6-2-u3-X09"}],"explanation":["금속 막대만 켜졌어요.","금속은 전기가 흘러요.","금속 막대예요."],"asset":{"type":"passage","lines":["플라스틱 막대를 이었을 때 — 전구 꺼짐","고무 막대를 이었을 때 — 전구 꺼짐","금속 막대를 이었을 때 — 전구 켜짐"],"title":"스위치 자리에 막대를 이어 본 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#4','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C4',1,'sa','auto','전지·전구·전선 같은 전기 부품을 서로 이어 전기가 흐를 수 있게 한 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C4","difficulty":1,"kind":"sa","stem":"전지·전구·전선 같은 전기 부품을 서로 이어 전기가 흐를 수 있게 한 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["전기회로","전기 회로"],"explanation":["부품을 이었어요.","전기가 흘러요.","전기 회로예요."],"mis":"SC6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#5','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C5',2,'mc','auto','전기 회로 카드 (가)~(라) 가운데 전구에 불이 켜지는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X07','SC6-2-u3-X06','SC6-2-u3-X09']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C5","difficulty":2,"kind":"mc","stem":"전기 회로 카드 (가)~(라) 가운데 전구에 불이 켜지는 것은 어느 것인가요?","options":[{"t":"(나)","correct":true},{"t":"(가)","mis":"SC6-2-u3-X07"},{"t":"(다)","mis":"SC6-2-u3-X06"},{"t":"(라)","mis":"SC6-2-u3-X09"}],"explanation":["(나)만 모두 이어졌어요.","(+)극부터 (−)극까지예요.","(나)에 불이 켜져요."],"asset":{"type":"passage","lines":["(가) 전지 (+)극 — 전구 — 스위치, 스위치에서 (−)극으로 가는 전선이 없다.","(나) 전지 (+)극 — 전구 — 스위치 — 전지 (−)극으로 모두 이었다.","(다) 전구에서 나온 전선 두 가닥을 모두 전지 (+)극에 이었다.","(라) (나)와 같되 스위치 자리에 플라스틱 막대를 이었다."],"title":"전기 회로 카드 (가)~(라) — 스위치는 모두 닫음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#6','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C5',2,'mc','auto','전기 회로 카드 (가)에 불이 켜지지 않는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X06','SC6-2-u3-X08','SC6-2-u3-X10']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C5","difficulty":2,"kind":"mc","stem":"전기 회로 카드 (가)에 불이 켜지지 않는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"스위치에서 전지 (−)극으로 가는 이음이 끊어져 있어서","correct":true},{"t":"전구가 전지 (+)극에 이어져 있어서","mis":"SC6-2-u3-X06"},{"t":"스위치를 닫았기 때문이라서","mis":"SC6-2-u3-X08"},{"t":"전선이 금속으로 되어 있어서","mis":"SC6-2-u3-X10"}],"explanation":["(−)극 쪽이 빠졌어요.","이음이 끊어졌어요.","그래서 꺼져요."],"asset":{"type":"passage","lines":["(가) 전지 (+)극 — 전구 — 스위치, 스위치에서 (−)극으로 가는 전선이 없다.","(나) 전지 (+)극 — 전구 — 스위치 — 전지 (−)극으로 모두 이었다.","(다) 전구에서 나온 전선 두 가닥을 모두 전지 (+)극에 이었다.","(라) (나)와 같되 스위치 자리에 플라스틱 막대를 이었다."],"title":"전기 회로 카드 (가)~(라) — 스위치는 모두 닫음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#7','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C8',2,'mc','auto','전기 회로를 만들 때 전기 부품의 어느 부분끼리 이어야 하나요?',ARRAY['SC6-2-u3-X10']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C8","difficulty":2,"kind":"mc","stem":"전기 회로를 만들 때 전기 부품의 어느 부분끼리 이어야 하나요?","options":[{"t":"전기가 흐르는 금속 부분끼리","correct":true},{"t":"플라스틱 부분끼리","mis":"SC6-2-u3-X10"},{"t":"유리 부분끼리","mis":"SC6-2-u3-X10"},{"t":"고무 덮개 부분끼리","mis":"SC6-2-u3-X10"}],"explanation":["금속은 전기가 흘러요.","금속끼리 닿게 해요.","그래야 불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#8','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C6',2,'mc','auto','손전등의 스위치를 누르면 불이 켜지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X08','SC6-2-u3-X12','SC6-2-u3-X09']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C6","difficulty":2,"kind":"mc","stem":"손전등의 스위치를 누르면 불이 켜지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"손전등 안에서 끊어져 있던 부분이 이어지기 때문이다","correct":true},{"t":"스위치를 누르면 회로가 끊어지기 때문이다","mis":"SC6-2-u3-X08"},{"t":"손전등 전구가 스스로 전기를 만들기 때문이다","mis":"SC6-2-u3-X12"},{"t":"손잡이의 플라스틱으로 전기가 흐르기 때문이다","mis":"SC6-2-u3-X09"}],"explanation":["스위치를 눌러요.","끊어진 곳이 이어져요.","불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#9','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C8',2,'ox','auto','전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 서로 끊어져 있어요.',ARRAY['SC6-2-u3-X11']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C8","difficulty":2,"kind":"ox","stem":"전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 서로 끊어져 있어요.","answer":"X","reason_options":[{"t":"전구 끼우개 아랫면에서 두 부분이 전선으로 이어져 있기 때문에","correct":true},{"t":"전구 끼우개 속은 아무것도 이어져 있지 않기 때문에","mis":"SC6-2-u3-X11"}],"mis":"SC6-2-u3-X11","explanation":["아랫면을 봐요.","전선으로 이어져 있어요.","끊어져 있지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_basic#10','sci',6,2,'u3','L02','g6_2_sci_u3_L02_basic','lesson_basic','SC6-2-u3-C5',3,'error','auto','전기 회로 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X06','SC6-2-u3-X07','SC6-2-u3-X09']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C5","difficulty":3,"kind":"error","stem":"전기 회로 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「(다)는 전선 두 가닥이 다 전지에 닿았으니 켜질 거야.」","correct":true,"mis_target":"SC6-2-u3-X06"},{"t":"준서 — 「(나)는 (+)극부터 (−)극까지 다 이어졌어.」","mis":"SC6-2-u3-X07"},{"t":"예린 — 「(라)는 플라스틱 막대 때문에 안 켜질 거야.」","mis":"SC6-2-u3-X09"}],"explanation":["(다)는 (+)극에만 이었어요.","(−)극까지 가야 해요.","수아의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["(가) 전지 (+)극 — 전구 — 스위치, 스위치에서 (−)극으로 가는 전선이 없다.","(나) 전지 (+)극 — 전구 — 스위치 — 전지 (−)극으로 모두 이었다.","(다) 전구에서 나온 전선 두 가닥을 모두 전지 (+)극에 이었다.","(라) (나)와 같되 스위치 자리에 플라스틱 막대를 이었다."],"title":"전기 회로 카드 (가)~(라) — 스위치는 모두 닫음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#1','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C4',2,'match','auto','전기 부품과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C4","difficulty":2,"kind":"match","stem":"전기 부품과 하는 일을 알맞게 이으세요.","pairs":[{"l":"전지","r":"전기 에너지를 공급함"},{"l":"전구","r":"전기가 흐르면 불이 켜짐"},{"l":"스위치","r":"닫으면 이어지고 열면 끊어짐"}],"mis":"SC6-2-u3-X12","explanation":["전지는 전기를 줘요.","전구는 빛을 내요.","스위치는 잇고 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#2','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C7',2,'mc','auto','스위치 자리에 막대를 이어 본 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X09']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C7","difficulty":2,"kind":"mc","stem":"스위치 자리에 막대를 이어 본 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"플라스틱·고무·금속 가운데 전기가 흐르는 물질은 금속이다","correct":true},{"t":"플라스틱·고무·금속 모두 전기가 잘 흐른다","mis":"SC6-2-u3-X09"},{"t":"고무는 금속보다 전기가 더 잘 흐른다","mis":"SC6-2-u3-X09"},{"t":"막대의 굵기만 같으면 무엇이든 불이 켜진다","mis":"SC6-2-u3-X09"}],"explanation":["금속 막대만 켜졌어요.","금속은 전기가 흘러요.","나머지는 잘 흐르지 않아요."],"asset":{"type":"passage","lines":["플라스틱 막대를 이었을 때 — 전구 꺼짐","고무 막대를 이었을 때 — 전구 꺼짐","금속 막대를 이었을 때 — 전구 켜짐"],"title":"스위치 자리에 막대를 이어 본 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#3','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C8',3,'mc','auto','전기 부품을 이루는 물질 관찰을 보고, 전구에 불이 켜지도록 이은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X10']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C8","difficulty":3,"kind":"mc","stem":"전기 부품을 이루는 물질 관찰을 보고, 전구에 불이 켜지도록 이은 것은 어느 것인가요?","options":[{"t":"전선의 금속 집게를 전구의 금속 몸체에 물렸다","correct":true},{"t":"전선의 금속 집게를 전구의 유리 부분에 대었다","mis":"SC6-2-u3-X10"},{"t":"전선의 고무 덮개를 스위치의 금속 부분에 대었다","mis":"SC6-2-u3-X10"},{"t":"전선을 전지 끼우개의 플라스틱 틀에 물렸다","mis":"SC6-2-u3-X10"}],"explanation":["금속끼리 닿아야 해요.","유리·고무·플라스틱은 막아요.","금속 몸체에 물려요."],"asset":{"type":"passage","lines":["전구 — 유리로 된 둥근 부분, 금속으로 된 몸체","스위치 — 플라스틱 몸체, 금속으로 된 이음 부분","전지 끼우개 — 플라스틱 틀, 금속 판","집게 달린 전선 — 고무 덮개, 금속 집게"],"title":"전기 부품을 이루는 물질 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#4','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C7',3,'mc','auto','새로 산 마우스의 전지 칸에 비닐이 끼워져 있었어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X13','SC6-2-u3-X12','SC6-2-u3-X09']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C7","difficulty":3,"kind":"mc","stem":"새로 산 마우스의 전지 칸에 비닐이 끼워져 있었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"전기가 잘 흐르지 않는 비닐로 막아 쓰기 전까지 전지가 닳지 않게 하려고","correct":true},{"t":"비닐이 전기를 더 잘 흐르게 해 주어서","mis":"SC6-2-u3-X13"},{"t":"비닐이 전지를 대신해 전기를 주어서","mis":"SC6-2-u3-X12"},{"t":"비닐이 있어도 전기는 똑같이 흘러서","mis":"SC6-2-u3-X09"}],"explanation":["비닐은 전기를 막아요.","쓰기 전엔 흐르지 않게 해요.","전지가 닳지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#5','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C5',3,'mc','auto','불이 켜지는 전기 회로와 켜지지 않는 전기 회로를 견준 말로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X07','SC6-2-u3-X06','SC6-2-u3-X10']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C5","difficulty":3,"kind":"mc","stem":"불이 켜지는 전기 회로와 켜지지 않는 전기 회로를 견준 말로 알맞은 것은 어느 것인가요?","options":[{"t":"켜지는 회로는 (+)극부터 (−)극까지 끊어진 곳 없이 이어졌고, 켜지지 않는 회로는 끊어졌거나 한쪽 극에만 이어졌다","correct":true},{"t":"두 회로 모두 끊어진 곳 없이 이어졌다","mis":"SC6-2-u3-X07"},{"t":"켜지지 않는 회로도 (+)극에만 이으면 켜진다","mis":"SC6-2-u3-X06"},{"t":"켜지는 회로는 플라스틱 부분끼리 이어졌다","mis":"SC6-2-u3-X10"}],"explanation":["끊어진 곳이 없어요.","두 극까지 이어요.","그래야 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#6','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C6',3,'error','auto','스위치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X08','SC6-2-u3-X07','SC6-2-u3-X10']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C6","difficulty":3,"kind":"error","stem":"스위치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「스위치를 열어 두어야 전기가 흘러서 불이 켜져.」","correct":true,"mis_target":"SC6-2-u3-X08"},{"t":"다은 — 「스위치를 닫으면 끊어진 곳이 이어져.」","mis":"SC6-2-u3-X07"},{"t":"시우 — 「스위치 몸체는 플라스틱, 이음 부분은 금속이야.」","mis":"SC6-2-u3-X10"}],"explanation":["스위치를 닫아야 해요.","닫으면 이어져요.","태윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#7','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C5',3,'ox','auto','전구에서 나온 전선 두 가닥을 모두 전지의 (−)극에만 이어도 불이 켜져요.',ARRAY['SC6-2-u3-X06']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C5","difficulty":3,"kind":"ox","stem":"전구에서 나온 전선 두 가닥을 모두 전지의 (−)극에만 이어도 불이 켜져요.","answer":"X","reason_options":[{"t":"전지의 (+)극부터 (−)극까지 이어져야 전기가 흐르기 때문에","correct":true},{"t":"전지는 한쪽 극에만 이어도 전기를 주기 때문에","mis":"SC6-2-u3-X06"}],"mis":"SC6-2-u3-X06","explanation":["(−)극에만 이었어요.","두 극까지 이어야 해요.","불이 켜지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#8','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C8',4,'mc','auto','불이 켜지던 회로의 전구 끼우개를 바꿔 끼웠더니 불이 꺼졌어요. 원인으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X11','SC6-2-u3-X08','SC6-2-u3-X10']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C8","difficulty":4,"kind":"mc","stem":"불이 켜지던 회로의 전구 끼우개를 바꿔 끼웠더니 불이 꺼졌어요. 원인으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"집게가 전구 끼우개의 금속 막대가 아닌 플라스틱 부분에 물려 있다","correct":true},{"t":"전구 끼우개 속은 원래 끊어져 있어서 바꿀 때마다 꺼진다","mis":"SC6-2-u3-X11"},{"t":"스위치를 닫아 두어서 꺼졌다","mis":"SC6-2-u3-X08"},{"t":"집게를 금속 막대에 물렸기 때문이다","mis":"SC6-2-u3-X10"}],"explanation":["어디에 물렸나요?","플라스틱은 전기를 막아요.","금속 막대에 물려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#9','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C7',4,'mc','auto','스위치를 잃어버렸을 때 대신 이어서 불을 켰다 껐다 하기에 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X09']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C7","difficulty":4,"kind":"mc","stem":"스위치를 잃어버렸을 때 대신 이어서 불을 켰다 껐다 하기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"금속 클립을 대었다 떼었다 한다","correct":true},{"t":"고무지우개를 대었다 떼었다 한다","mis":"SC6-2-u3-X09"},{"t":"플라스틱 자를 대었다 떼었다 한다","mis":"SC6-2-u3-X09"},{"t":"종이를 접어 대었다 떼었다 한다","mis":"SC6-2-u3-X09"}],"explanation":["전기가 흘러야 해요.","금속은 흘러요.","금속 클립이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L02_challenge#10','sci',6,2,'u3','L02','g6_2_sci_u3_L02_challenge','lesson_challenge','SC6-2-u3-C6',4,'essay','teacher','전구에 불이 켜지는 전기 회로를 만든 뒤 스위치를 닫았을 때와 열었을 때 일어나는 일과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C6","difficulty":4,"kind":"essay","stem":"전구에 불이 켜지는 전기 회로를 만든 뒤 스위치를 닫았을 때와 열었을 때 일어나는 일과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 스위치를 닫으면 전구에 불이 켜지고 열면 꺼진다. 스위치를 닫아야 회로가 끊어진 곳 없이 모두 이어져 전기가 흐르기 때문이다.","scoring_points":["닫으면 켜지고 열면 꺼진다고 썼는가","닫으면 끊어진 곳 없이 이어진다는 까닭을 썼는가","전기가 흐른다는 말을 썼는가"]},"explanation":["닫으면 켜져요.","열면 꺼져요.","이어져야 전기가 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#1','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C9',1,'mc','auto','전지 두 개를 직렬연결하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X14']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C9","difficulty":1,"kind":"mc","stem":"전지 두 개를 직렬연결하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 전지의 (+)극을 다른 전지의 (−)극에 잇는다","correct":true},{"t":"두 전지의 (+)극끼리 잇는다","mis":"SC6-2-u3-X14"},{"t":"두 전지의 (−)극끼리 잇는다","mis":"SC6-2-u3-X14"},{"t":"두 전지를 잇지 않고 따로 둔다","mis":"SC6-2-u3-X14"}],"explanation":["(+)극과 (−)극이에요.","서로 다른 극을 이어요.","그것이 직렬연결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#2','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C10',1,'ox','auto','전지 두 개를 직렬연결한 회로의 전구는 전지 한 개를 이은 회로의 전구보다 더 밝아요.',ARRAY['SC6-2-u3-X15']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C10","difficulty":1,"kind":"ox","stem":"전지 두 개를 직렬연결한 회로의 전구는 전지 한 개를 이은 회로의 전구보다 더 밝아요.","answer":"O","reason_options":[{"t":"직렬로 이은 전지가 많아지면 전구가 더 밝게 빛나기 때문에","correct":true},{"t":"전지를 더 이으면 전구가 오히려 어두워지기 때문에","mis":"SC6-2-u3-X15"}],"mis":"SC6-2-u3-X15","explanation":["전지가 두 개예요.","직렬로 이었어요.","전구가 더 밝아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#3','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C10',1,'mc','auto','전지 한 개와 두 개 견주기 기록에서 전동기 날개는 어느 회로에서 더 빠르게 돌았나요?',ARRAY['SC6-2-u3-X16']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C10","difficulty":1,"kind":"mc","stem":"전지 한 개와 두 개 견주기 기록에서 전동기 날개는 어느 회로에서 더 빠르게 돌았나요?","options":[{"t":"전지 두 개를 직렬연결한 회로 ㉯","correct":true},{"t":"전지 한 개를 이은 회로 ㉮","mis":"SC6-2-u3-X16"},{"t":"두 회로에서 똑같다","mis":"SC6-2-u3-X16"},{"t":"두 회로 모두 돌지 않았다","mis":"SC6-2-u3-X16"}],"explanation":["㉯는 전지가 두 개예요.","날개가 더 빨라요.","회로 ㉯예요."],"asset":{"type":"passage","lines":["회로 ㉮ — 전지 한 개 + 전구 · 전동기 · 버저 따로따로","회로 ㉯ — 전지 두 개를 직렬연결 + 같은 전구 · 전동기 · 버저","전구 — ㉮보다 ㉯에서 더 밝다.","전동기 날개 — ㉮보다 ㉯에서 더 빠르게 돈다.","버저 — ㉮보다 ㉯에서 소리가 더 크다."],"title":"전지 한 개와 두 개 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#4','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C9',1,'sa','auto','한 전지의 (+)극을 다른 전지의 (−)극에 잇는 방법을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C9","difficulty":1,"kind":"sa","stem":"한 전지의 (+)극을 다른 전지의 (−)극에 잇는 방법을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["직렬연결","직렬 연결"],"explanation":["(+)극과 (−)극을 이어요.","네 글자예요.","직렬연결이에요."],"mis":"SC6-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#5','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C10',2,'mc','auto','전지 두 개를 직렬연결한 회로에서 버저 소리는 전지 한 개를 이었을 때와 견주어 어떤가요?',ARRAY['SC6-2-u3-X16']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"mc","stem":"전지 두 개를 직렬연결한 회로에서 버저 소리는 전지 한 개를 이었을 때와 견주어 어떤가요?","options":[{"t":"더 크게 난다","correct":true},{"t":"더 작게 난다","mis":"SC6-2-u3-X16"},{"t":"똑같다","mis":"SC6-2-u3-X16"},{"t":"아예 나지 않는다","mis":"SC6-2-u3-X16"}],"explanation":["전지가 늘었어요.","직렬로 이었어요.","소리가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#6','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C9',2,'mc','auto','전지 두 개를 잇는 세 가지 모습 가운데 직렬연결은 어느 것인가요?',ARRAY['SC6-2-u3-X14']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C9","difficulty":2,"kind":"mc","stem":"전지 두 개를 잇는 세 가지 모습 가운데 직렬연결은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SC6-2-u3-X14"},{"t":"㉢","mis":"SC6-2-u3-X14"},{"t":"㉡과 ㉢ 모두","mis":"SC6-2-u3-X14"}],"explanation":["(+)극과 (−)극을 이었나요?","㉠만 그래요.","㉠이 직렬연결이에요."],"asset":{"type":"passage","lines":["㉠ 첫째 전지 (+)극에 둘째 전지 (−)극을 이었다.","㉡ 첫째 전지 (+)극에 둘째 전지 (+)극을 이었다.","㉢ 첫째 전지 (−)극에 둘째 전지 (−)극을 이었다."],"title":"전지 두 개를 잇는 세 가지 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#7','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C11',2,'mc','auto','전지 두 개를 직렬연결했는데 버저가 울리지 않았어요. 가장 먼저 확인할 것은 어느 것인가요?',ARRAY['SC6-2-u3-X17','SC6-2-u3-X14','SC6-2-u3-X16']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C11","difficulty":2,"kind":"mc","stem":"전지 두 개를 직렬연결했는데 버저가 울리지 않았어요. 가장 먼저 확인할 것은 어느 것인가요?","options":[{"t":"버저를 잇는 방향이 맞는지","correct":true},{"t":"버저는 방향과 상관없으니 버저를 버린다","mis":"SC6-2-u3-X17"},{"t":"전지를 (+)극끼리 다시 잇는다","mis":"SC6-2-u3-X14"},{"t":"전지를 한 개 빼면 소리가 더 커진다","mis":"SC6-2-u3-X16"}],"explanation":["버저는 방향을 가려요.","잇는 방향을 확인해요.","그다음 다시 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#8','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C10',2,'mc','auto','전지 한 개와 두 개를 이은 회로를 견줄 때 다르게 해야 할 것은 어느 것인가요?',ARRAY['SC6-2-u3-X18']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"mc","stem":"전지 한 개와 두 개를 이은 회로를 견줄 때 다르게 해야 할 것은 어느 것인가요?","options":[{"t":"이은 전지의 개수","correct":true},{"t":"전구의 종류","mis":"SC6-2-u3-X18"},{"t":"전동기의 종류","mis":"SC6-2-u3-X18"},{"t":"버저의 종류","mis":"SC6-2-u3-X18"}],"explanation":["전지 개수만 달라요.","나머지는 같게 해요.","그래야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#9','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C11',2,'ox','auto','발광 다이오드는 전지를 어느 방향으로 이어도 언제나 불이 켜져요.',ARRAY['SC6-2-u3-X17']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C11","difficulty":2,"kind":"ox","stem":"발광 다이오드는 전지를 어느 방향으로 이어도 언제나 불이 켜져요.","answer":"X","reason_options":[{"t":"발광 다이오드는 잇는 방향에 따라 켜지지 않을 수 있기 때문에","correct":true},{"t":"발광 다이오드는 방향을 가리지 않고 늘 켜지기 때문에","mis":"SC6-2-u3-X17"}],"mis":"SC6-2-u3-X17","explanation":["방향을 가리는 부품이에요.","거꾸로 이으면 안 켜질 수 있어요.","방향을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_basic#10','sci',6,2,'u3','L03','g6_2_sci_u3_L03_basic','lesson_basic','SC6-2-u3-C10',3,'error','auto','전지 한 개와 두 개 견주기를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X15','SC6-2-u3-X16','SC6-2-u3-X14']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"error","stem":"전지 한 개와 두 개 견주기를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「전지를 하나 더 이었더니 전구가 더 어두워졌어.」","correct":true,"mis_target":"SC6-2-u3-X15"},{"t":"로운 — 「전지 두 개일 때 전동기가 더 빨리 돌았어.」","mis":"SC6-2-u3-X16"},{"t":"채아 — 「한 전지 (+)극을 다른 전지 (−)극에 이었어.」","mis":"SC6-2-u3-X14"}],"explanation":["전지가 늘었어요.","전구는 더 밝아져요.","지민의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["회로 ㉮ — 전지 한 개 + 전구 · 전동기 · 버저 따로따로","회로 ㉯ — 전지 두 개를 직렬연결 + 같은 전구 · 전동기 · 버저","전구 — ㉮보다 ㉯에서 더 밝다.","전동기 날개 — ㉮보다 ㉯에서 더 빠르게 돈다.","버저 — ㉮보다 ㉯에서 소리가 더 크다."],"title":"전지 한 개와 두 개 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#1','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',2,'match','auto','전지 두 개를 직렬연결했을 때 부품마다 달라지는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"match","stem":"전지 두 개를 직렬연결했을 때 부품마다 달라지는 모습을 알맞게 이으세요.","pairs":[{"l":"전구","r":"더 밝게 빛남"},{"l":"전동기","r":"날개가 더 빠르게 돎"},{"l":"버저","r":"소리가 더 크게 남"}],"mis":"SC6-2-u3-X16","explanation":["전구는 밝기를 봐요.","전동기는 빠르기예요.","버저는 소리 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#2','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C9',2,'mc','auto','전지 끼우개 두 개에 전지를 끼워 직렬연결하려고 해요. 집게 달린 전선을 바르게 이은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X10']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C9","difficulty":2,"kind":"mc","stem":"전지 끼우개 두 개에 전지를 끼워 직렬연결하려고 해요. 집게 달린 전선을 바르게 이은 것은 어느 것인가요?","options":[{"t":"첫째 전지의 (+)극 쪽 금속 판과 둘째 전지의 (−)극 쪽 금속 판을 이었다","correct":true},{"t":"두 전지의 (+)극 쪽 금속 판끼리 이었다","mis":"SC6-2-u3-X14"},{"t":"두 전지의 (−)극 쪽 금속 판끼리 이었다","mis":"SC6-2-u3-X14"},{"t":"전지 끼우개의 플라스틱 틀끼리 이었다","mis":"SC6-2-u3-X10"}],"explanation":["다른 극끼리 이어요.","금속 판에 물려요.","그래야 직렬연결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#3','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',3,'mc','auto','전지 한 개와 두 개 견주기 기록을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X16','SC6-2-u3-X15']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"mc","stem":"전지 한 개와 두 개 견주기 기록을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"직렬로 이은 전지가 많을수록 전구는 더 밝고, 전동기는 더 빠르고, 버저는 더 크다","correct":true},{"t":"전지 개수와 상관없이 세 부품은 똑같이 작동한다","mis":"SC6-2-u3-X16"},{"t":"전지를 더 이으면 세 부품 모두 약해진다","mis":"SC6-2-u3-X15"},{"t":"전구만 달라지고 전동기·버저는 그대로다","mis":"SC6-2-u3-X16"}],"explanation":["세 부품을 봐요.","모두 더 세졌어요.","전지가 많을수록 그래요."],"asset":{"type":"passage","lines":["회로 ㉮ — 전지 한 개 + 전구 · 전동기 · 버저 따로따로","회로 ㉯ — 전지 두 개를 직렬연결 + 같은 전구 · 전동기 · 버저","전구 — ㉮보다 ㉯에서 더 밝다.","전동기 날개 — ㉮보다 ㉯에서 더 빠르게 돈다.","버저 — ㉮보다 ㉯에서 소리가 더 크다."],"title":"전지 한 개와 두 개 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#4','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',3,'mc','auto','하은이는 회로 ㉮에는 작은 전구를, 회로 ㉯에는 큰 전구를 끼워 밝기를 견주었어요. 무엇이 잘못되었나요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X15','SC6-2-u3-X17']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"mc","stem":"하은이는 회로 ㉮에는 작은 전구를, 회로 ㉯에는 큰 전구를 끼워 밝기를 견주었어요. 무엇이 잘못되었나요?","options":[{"t":"전지 개수 말고 전구까지 바꾸어서 무엇 때문에 밝기가 달라졌는지 알 수 없다","correct":true},{"t":"전지 두 개는 (+)극끼리 이어야 하는데 그러지 않았다","mis":"SC6-2-u3-X14"},{"t":"전구는 크기와 상관없이 늘 같은 밝기라서 견줄 까닭이 없다","mis":"SC6-2-u3-X15"},{"t":"전구 대신 버저는 방향을 가리지 않아 더 좋다","mis":"SC6-2-u3-X17"}],"explanation":["바꾼 것이 둘이에요.","전지 개수만 달라야 해요.","전구는 같게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#5','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C9',3,'ox','auto','두 전지의 (+)극끼리 맞대어 이어도 직렬연결이에요.',ARRAY['SC6-2-u3-X14']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C9","difficulty":3,"kind":"ox","stem":"두 전지의 (+)극끼리 맞대어 이어도 직렬연결이에요.","answer":"X","reason_options":[{"t":"직렬연결은 한 전지의 (+)극을 다른 전지의 (−)극에 잇는 것이기 때문에","correct":true},{"t":"극이 같기만 하면 어떻게 이어도 직렬연결이기 때문에","mis":"SC6-2-u3-X14"}],"mis":"SC6-2-u3-X14","explanation":["같은 극끼리예요.","직렬연결이 아니에요.","(+)극과 (−)극을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#6','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C11',3,'error','auto','버저와 발광 다이오드를 이어 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X17','SC6-2-u3-X16','SC6-2-u3-X14']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C11","difficulty":3,"kind":"error","stem":"버저와 발광 다이오드를 이어 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「발광 다이오드가 안 켜지면 망가진 거니까 바로 버리자.」","correct":true,"mis_target":"SC6-2-u3-X17"},{"t":"서아 — 「전지를 직렬로 하나 더 이으니 버저 소리가 커졌어.」","mis":"SC6-2-u3-X16"},{"t":"윤재 — 「한 전지 (+)극을 다른 전지 (−)극에 이었지.」","mis":"SC6-2-u3-X14"}],"explanation":["방향부터 확인해요.","거꾸로면 안 켜질 수 있어요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#7','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',3,'mc','auto','손전등 하나는 전지 한 개, 다른 하나는 같은 전지 두 개를 직렬연결해 쓴다고 해요. 전구와 다른 부품이 같다면 어느 손전등이 더 밝을까요?',ARRAY['SC6-2-u3-X15']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"mc","stem":"손전등 하나는 전지 한 개, 다른 하나는 같은 전지 두 개를 직렬연결해 쓴다고 해요. 전구와 다른 부품이 같다면 어느 손전등이 더 밝을까요?","options":[{"t":"전지 두 개를 직렬연결한 손전등","correct":true},{"t":"전지 한 개를 쓴 손전등","mis":"SC6-2-u3-X15"},{"t":"두 손전등의 밝기는 같다","mis":"SC6-2-u3-X15"},{"t":"전지가 많으면 불이 켜지지 않는다","mis":"SC6-2-u3-X15"}],"explanation":["전지가 두 개예요.","직렬로 이었어요.","더 밝아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#8','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',4,'mc','auto','전동기에 단 바람개비를 더 빠르게 돌리고 싶어요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u3-X16','SC6-2-u3-X14','SC6-2-u3-X18']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C10","difficulty":4,"kind":"mc","stem":"전동기에 단 바람개비를 더 빠르게 돌리고 싶어요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"같은 전지를 하나 더 직렬연결한다","correct":true},{"t":"전지를 하나 빼고 전동기만 남긴다","mis":"SC6-2-u3-X16"},{"t":"전지 두 개를 (−)극끼리 잇는다","mis":"SC6-2-u3-X14"},{"t":"전동기를 다른 종류로 바꾸고 전지도 바꾸어 견준다","mis":"SC6-2-u3-X18"}],"explanation":["전지를 더 이어요.","직렬로 이어요.","더 빨리 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#9','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C11',4,'mc','auto','전지 두 개를 바르게 직렬연결했는데 버저만 울리지 않고 전구는 켜졌어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['SC6-2-u3-X16','SC6-2-u3-X14','SC6-2-u3-X17']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C11","difficulty":4,"kind":"mc","stem":"전지 두 개를 바르게 직렬연결했는데 버저만 울리지 않고 전구는 켜졌어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"버저를 잇는 방향이 거꾸로일 수 있으니 버저의 두 전선을 바꾸어 이어 본다","correct":true},{"t":"직렬연결하면 버저는 원래 울리지 않는다","mis":"SC6-2-u3-X16"},{"t":"전지를 (+)극끼리 다시 이어야 한다","mis":"SC6-2-u3-X14"},{"t":"버저는 방향을 가리지 않으니 이유를 알 수 없다","mis":"SC6-2-u3-X17"}],"explanation":["전구는 켜졌어요.","회로는 이어졌어요.","버저 방향을 바꿔 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L03_challenge#10','sci',6,2,'u3','L03','g6_2_sci_u3_L03_challenge','lesson_challenge','SC6-2-u3-C10',4,'essay','teacher','전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로에서 전동기 날개의 빠르기와 버저 소리의 크기가 어떻게 다른지 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C10","difficulty":4,"kind":"essay","stem":"전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로에서 전동기 날개의 빠르기와 버저 소리의 크기가 어떻게 다른지 견주어 쓰세요.","answer_guide":{"answer":"예: 전지 한 개를 이은 회로보다 전지 두 개를 직렬연결한 회로에서 전동기 날개가 더 빠르게 돌고, 버저 소리가 더 크게 난다.","scoring_points":["전동기 날개가 더 빠르다고 썼는가","버저 소리가 더 크다고 썼는가","어느 회로에서 그런지 밝혀 견주었는가"]},"explanation":["두 회로를 견줘요.","전동기는 더 빨라요.","버저는 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#1','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C13',1,'mc','auto','전자석에 둥근 철 고리가 붙는 때는 언제인가요?',ARRAY['SC6-2-u3-X19']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C13","difficulty":1,"kind":"mc","stem":"전자석에 둥근 철 고리가 붙는 때는 언제인가요?","options":[{"t":"스위치를 닫아 전기가 흐를 때","correct":true},{"t":"스위치를 열어 두었을 때","mis":"SC6-2-u3-X19"},{"t":"전지를 빼 두었을 때","mis":"SC6-2-u3-X19"},{"t":"언제나 붙는다","mis":"SC6-2-u3-X19"}],"explanation":["스위치를 닫아요.","전기가 흘러요.","그때만 자석이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#2','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C14',1,'ox','auto','전자석에 직렬로 이은 전지가 많을수록 전자석의 세기가 세져요.',ARRAY['SC6-2-u3-X20']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C14","difficulty":1,"kind":"ox","stem":"전자석에 직렬로 이은 전지가 많을수록 전자석의 세기가 세져요.","answer":"O","reason_options":[{"t":"전지 두 개를 직렬연결했을 때 둥근 철 고리가 더 많이 붙기 때문에","correct":true},{"t":"전지를 더 이으면 둥근 철 고리가 더 적게 붙기 때문에","mis":"SC6-2-u3-X20"}],"mis":"SC6-2-u3-X20","explanation":["전지가 많아요.","철 고리가 더 붙어요.","세기가 세져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#3','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C12',1,'mc','auto','전자석을 만들 때 둥근 머리 볼트에 감는 선은 어느 것인가요?',ARRAY['SC6-2-u3-X23']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C12","difficulty":1,"kind":"mc","stem":"전자석을 만들 때 둥근 머리 볼트에 감는 선은 어느 것인가요?","options":[{"t":"에나멜선","correct":true},{"t":"고무줄","mis":"SC6-2-u3-X23"},{"t":"털실","mis":"SC6-2-u3-X23"},{"t":"비닐 끈","mis":"SC6-2-u3-X23"}],"explanation":["전기가 흐르는 선이에요.","코팅된 구리선이에요.","에나멜선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#4','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C13',1,'sa','auto','전기가 흐를 때만 자석의 성질을 나타내는 자석을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C13","difficulty":1,"kind":"sa","stem":"전기가 흐를 때만 자석의 성질을 나타내는 자석을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["전자석"],"explanation":["전기로 만든 자석이에요.","세 글자예요.","전자석이에요."],"mis":"SC6-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#5','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C12',2,'mc','auto','에나멜선 양쪽 끝부분을 사포로 문지르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X24','SC6-2-u3-X23']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C12","difficulty":2,"kind":"mc","stem":"에나멜선 양쪽 끝부분을 사포로 문지르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"코팅을 벗겨 그 부분을 전기 회로에 이으려고","correct":true},{"t":"에나멜선을 더 길게 늘이려고","mis":"SC6-2-u3-X24"},{"t":"코팅을 더 두껍게 입히려고","mis":"SC6-2-u3-X23"},{"t":"끝을 뾰족하게 만들어 찌르려고","mis":"SC6-2-u3-X23"}],"explanation":["코팅은 전기를 막아요.","사포로 벗겨요.","벗긴 부분을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#6','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C15',2,'mc','auto','전자석의 극을 반대로 바꾸는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X21']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C15","difficulty":2,"kind":"mc","stem":"전자석의 극을 반대로 바꾸는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"전자석에 이은 전지의 방향을 반대로 바꾼다","correct":true},{"t":"스위치를 한 번 더 닫는다","mis":"SC6-2-u3-X21"},{"t":"둥근 철 고리를 더 가까이 한다","mis":"SC6-2-u3-X21"},{"t":"극은 바꿀 수 없으니 그대로 둔다","mis":"SC6-2-u3-X21"}],"explanation":["전지 방향을 바꿔요.","극도 바뀌어요.","양쪽 극이 반대가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#7','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C14',2,'mc','auto','전자석 끝에 붙은 둥근 철 고리 기록을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X19']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C14","difficulty":2,"kind":"mc","stem":"전자석 끝에 붙은 둥근 철 고리 기록을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"직렬로 이은 전지가 많을수록 전자석이 세진다","correct":true},{"t":"전지 개수와 상관없이 세기가 같다","mis":"SC6-2-u3-X20"},{"t":"스위치를 닫기 전에도 자석이다","mis":"SC6-2-u3-X19"},{"t":"전지를 더 이으면 약해진다","mis":"SC6-2-u3-X20"}],"explanation":["철 고리가 늘었어요.","전지가 두 개일 때예요.","세기가 세져요."],"asset":{"type":"passage","lines":["스위치를 닫기 전 — 붙은 둥근 철 고리 없음","전지 한 개를 이고 스위치를 닫음 — 둥근 철 고리 4개","전지 두 개를 직렬연결하고 스위치를 닫음 — 둥근 철 고리 9개"],"title":"전자석 끝에 붙은 둥근 철 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#8','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C15',2,'mc','auto','전자석 양쪽 끝에 나침반을 두는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X19','SC6-2-u3-X25']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C15","difficulty":2,"kind":"mc","stem":"전자석 양쪽 끝에 나침반을 두는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나침반 바늘이 가리키는 방향으로 전자석의 극을 알아내려고","correct":true},{"t":"나침반 바늘로 전자석의 세기를 재려고","mis":"SC6-2-u3-X20"},{"t":"나침반이 전지를 대신하게 하려고","mis":"SC6-2-u3-X19"},{"t":"나침반은 자석과 상관없어 장식으로","mis":"SC6-2-u3-X25"}],"explanation":["나침반 바늘도 자석이에요.","극을 가리켜요.","극을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#9','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C13',2,'ox','auto','전자석 실험을 할 때 스위치는 필요할 때만 닫아요.',ARRAY['SC6-2-u3-X26']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C13","difficulty":2,"kind":"ox","stem":"전자석 실험을 할 때 스위치는 필요할 때만 닫아요.","answer":"O","reason_options":[{"t":"스위치를 오래 닫아 두면 전자석이 뜨거워지기 때문에","correct":true},{"t":"스위치를 오래 닫을수록 전자석이 더 차가워지기 때문에","mis":"SC6-2-u3-X26"}],"mis":"SC6-2-u3-X26","explanation":["오래 닫으면 뜨거워져요.","데일 수 있어요.","필요할 때만 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_basic#10','sci',6,2,'u3','L04','g6_2_sci_u3_L04_basic','lesson_basic','SC6-2-u3-C14',3,'error','auto','전자석과 영구 자석을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X22','SC6-2-u3-X20','SC6-2-u3-X19']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C14","difficulty":3,"kind":"error","stem":"전자석과 영구 자석을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「영구 자석도 전지를 붙이면 세기가 세져.」","correct":true,"mis_target":"SC6-2-u3-X22"},{"t":"소윤 — 「전자석은 전지를 더 이으면 세져.」","mis":"SC6-2-u3-X20"},{"t":"도하 — 「전자석은 스위치를 닫아야 철 고리가 붙어.」","mis":"SC6-2-u3-X19"}],"explanation":["영구 자석은 일정해요.","세기를 바꿀 수 없어요.","이안의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#1','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C12',2,'match','auto','전자석 만들기 차례와 하는 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C12","difficulty":2,"kind":"match","stem":"전자석 만들기 차례와 하는 까닭을 알맞게 이으세요.","pairs":[{"l":"종이를 감고 테이프로 고정","r":"에나멜선을 감을 바탕을 만듦"},{"l":"에나멜선을 한쪽 방향으로 촘촘히 감기","r":"전자석을 고르게 잘 만듦"},{"l":"끝부분을 사포로 문지르기","r":"코팅을 벗겨 회로에 이음"}],"mis":"SC6-2-u3-X24","explanation":["바탕을 만들어요.","한쪽 방향으로 감아요.","끝을 문질러 이어요."],"asset":{"type":"passage","lines":["① 둥근 머리 볼트에 종이를 감고 셀로판테이프로 고정한다.","② 종이 위에 에나멜선을 한쪽 방향으로 촘촘히 감는다.","③ 에나멜선 양쪽 끝부분을 사포로 문지른다.","④ 전지·스위치와 이어 전기 회로를 만든다."],"title":"전자석 만들기 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#2','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C13',2,'mc','auto','전자석이 영구 자석과 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X19','SC6-2-u3-X21','SC6-2-u3-X20']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C13","difficulty":2,"kind":"mc","stem":"전자석이 영구 자석과 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"전기가 흐를 때만 자석의 성질을 나타낸다","correct":true},{"t":"언제나 철로 만든 물체를 끌어당긴다","mis":"SC6-2-u3-X19"},{"t":"극을 바꿀 수 없다","mis":"SC6-2-u3-X21"},{"t":"세기를 바꿀 수 없다","mis":"SC6-2-u3-X20"}],"explanation":["전기가 흘러야 해요.","그때만 자석이에요.","영구 자석과 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#3','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C15',3,'mc','auto','전자석 양쪽 끝 나침반으로 찾은 극을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X21','SC6-2-u3-X25','SC6-2-u3-X22']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C15","difficulty":3,"kind":"mc","stem":"전자석 양쪽 끝 나침반으로 찾은 극을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"전지의 방향을 반대로 바꾸면 전자석의 양쪽 극도 반대로 바뀐다","correct":true},{"t":"전지 방향을 바꾸어도 극은 그대로다","mis":"SC6-2-u3-X21"},{"t":"나침반 바늘이 움직이는 동안 읽은 극이 더 정확하다","mis":"SC6-2-u3-X25"},{"t":"영구 자석도 이렇게 극이 바뀐다","mis":"SC6-2-u3-X22"}],"explanation":["전지 방향을 바꿨어요.","왼쪽 N극이 S극으로요.","극이 바뀌었어요."],"asset":{"type":"passage","lines":["전지 방향을 바꾸기 전 — 왼쪽 끝 N극, 오른쪽 끝 S극","전지 방향을 바꾼 뒤 — 왼쪽 끝 S극, 오른쪽 끝 N극","나침반 바늘은 완전히 멈춘 뒤에 읽었다."],"title":"전자석 양쪽 끝 나침반으로 찾은 극"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#4','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C13',3,'mc','auto','전자석 끝을 둥근 철 고리에 대고 스위치를 닫았다가 다시 열었어요. 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X19','SC6-2-u3-X23']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C13","difficulty":3,"kind":"mc","stem":"전자석 끝을 둥근 철 고리에 대고 스위치를 닫았다가 다시 열었어요. 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"닫으면 철 고리가 붙고, 열면 떨어진다","correct":true},{"t":"닫든 열든 철 고리가 계속 붙어 있다","mis":"SC6-2-u3-X19"},{"t":"닫으면 떨어지고, 열면 붙는다","mis":"SC6-2-u3-X19"},{"t":"스위치와 상관없이 철 고리가 붙지 않는다","mis":"SC6-2-u3-X23"}],"explanation":["닫으면 전기가 흘러요.","열면 끊어져요.","그때만 붙어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#5','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C12',3,'error','auto','전자석을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X24','SC6-2-u3-X23']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C12","difficulty":3,"kind":"error","stem":"전자석을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「에나멜선은 감다가 방향을 바꿔 가며 듬성듬성 감아도 돼.」","correct":true,"mis_target":"SC6-2-u3-X24"},{"t":"하윤 — 「에나멜선 끝을 사포로 문질러 이어야 해.」","mis":"SC6-2-u3-X23"},{"t":"세아 — 「볼트 끝에 찔리지 않게 조심하자.」","mis":"SC6-2-u3-X23"}],"explanation":["한쪽 방향으로 감아요.","촘촘히 감아요.","주원의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#6','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C12',3,'ox','auto','에나멜선 끝을 문지르지 않고 코팅된 채로 이어도 전자석이 잘 작동해요.',ARRAY['SC6-2-u3-X23']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C12","difficulty":3,"kind":"ox","stem":"에나멜선 끝을 문지르지 않고 코팅된 채로 이어도 전자석이 잘 작동해요.","answer":"X","reason_options":[{"t":"코팅된 부분은 전기가 잘 흐르지 않아 회로가 이어지지 않기 때문에","correct":true},{"t":"코팅이 있어야 전기가 더 잘 흐르기 때문에","mis":"SC6-2-u3-X23"}],"mis":"SC6-2-u3-X23","explanation":["코팅은 전기를 막아요.","문질러 벗겨야 해요.","그래야 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#7','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C14',3,'mc','auto','전자석에 붙는 둥근 철 고리를 더 많게 하려면 어떻게 해야 하나요?',ARRAY['SC6-2-u3-X19','SC6-2-u3-X14','SC6-2-u3-X20']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C14","difficulty":3,"kind":"mc","stem":"전자석에 붙는 둥근 철 고리를 더 많게 하려면 어떻게 해야 하나요?","options":[{"t":"같은 전지를 하나 더 직렬연결한다","correct":true},{"t":"전지를 빼고 스위치만 닫는다","mis":"SC6-2-u3-X19"},{"t":"전지 두 개를 (+)극끼리 잇는다","mis":"SC6-2-u3-X14"},{"t":"전자석의 세기는 바꿀 수 없으니 그대로 둔다","mis":"SC6-2-u3-X20"}],"explanation":["전지를 더 이어요.","직렬로 이어요.","세기가 세져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#8','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C15',4,'mc','auto','나침반 바늘이 흔들리는 동안 극을 써 넣었더니 짝과 결과가 달랐어요. 어떻게 해야 하나요?',ARRAY['SC6-2-u3-X25','SC6-2-u3-X21']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C15","difficulty":4,"kind":"mc","stem":"나침반 바늘이 흔들리는 동안 극을 써 넣었더니 짝과 결과가 달랐어요. 어떻게 해야 하나요?","options":[{"t":"나침반 바늘의 움직임이 완전히 멈춘 뒤에 다시 읽는다","correct":true},{"t":"흔들리는 바늘이 처음 가리킨 쪽을 그대로 쓴다","mis":"SC6-2-u3-X25"},{"t":"나침반으로는 극을 알 수 없으니 그만둔다","mis":"SC6-2-u3-X25"},{"t":"전지 방향은 극과 상관없으니 아무렇게나 쓴다","mis":"SC6-2-u3-X21"}],"explanation":["바늘이 흔들렸어요.","멈출 때까지 기다려요.","그다음 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#9','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C22',4,'mc','auto','영구 자석과 전자석을 견준 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X22','SC6-2-u3-X21','SC6-2-u3-X19']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C22","difficulty":4,"kind":"mc","stem":"영구 자석과 전자석을 견준 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"영구 자석은 세기와 극이 일정하지만, 전자석은 전지의 개수와 방향으로 세기와 극을 바꿀 수 있다","correct":true},{"t":"둘 다 세기와 극을 마음대로 바꿀 수 있다","mis":"SC6-2-u3-X22"},{"t":"전자석은 세기는 바꾸지만 극은 바꿀 수 없다","mis":"SC6-2-u3-X21"},{"t":"전자석은 전기가 없어도 영구 자석과 똑같다","mis":"SC6-2-u3-X19"}],"explanation":["영구 자석은 일정해요.","전자석은 바꿀 수 있어요.","세기와 극 둘 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L04_challenge#10','sci',6,2,'u3','L04','g6_2_sci_u3_L04_challenge','lesson_challenge','SC6-2-u3-C14',4,'essay','teacher','전자석에 전지 한 개를 이었을 때와 두 개를 직렬연결했을 때 붙는 둥근 철 고리의 개수를 견주고, 이로 알 수 있는 전자석의 성질을 영구 자석과 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C14","difficulty":4,"kind":"essay","stem":"전자석에 전지 한 개를 이었을 때와 두 개를 직렬연결했을 때 붙는 둥근 철 고리의 개수를 견주고, 이로 알 수 있는 전자석의 성질을 영구 자석과 견주어 쓰세요.","answer_guide":{"answer":"예: 전지 두 개를 직렬연결했을 때 철 고리가 더 많이 붙는다. 영구 자석은 세기가 일정하지만 전자석은 직렬로 이은 전지가 많을수록 세기가 세진다.","scoring_points":["두 개일 때 더 많이 붙는다고 썼는가","영구 자석은 세기가 일정하다고 썼는가","전자석은 전지가 많을수록 세진다고 썼는가"]},"explanation":["철 고리 수를 견줘요.","전자석은 세기를 바꿔요.","영구 자석은 일정해요."],"asset":{"type":"passage","lines":["스위치를 닫기 전 — 붙은 둥근 철 고리 없음","전지 한 개를 이고 스위치를 닫음 — 둥근 철 고리 4개","전지 두 개를 직렬연결하고 스위치를 닫음 — 둥근 철 고리 9개"],"title":"전자석 끝에 붙은 둥근 철 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#1','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C16',1,'mc','auto','선풍기 안에서 날개를 돌리는 데 쓰이는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X27']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"mc","stem":"선풍기 안에서 날개를 돌리는 데 쓰이는 것은 어느 것인가요?","options":[{"t":"전자석","correct":true},{"t":"고무줄","mis":"SC6-2-u3-X27"},{"t":"영구 자석만 붙인 판","mis":"SC6-2-u3-X27"},{"t":"셀로판테이프","mis":"SC6-2-u3-X27"}],"explanation":["날개가 돌아요.","전동기가 돌려요.","전자석이 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#2','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C17',1,'ox','auto','전자석 기중기는 전자석을 이용해 철로 만든 무거운 물체를 들어 옮겨요.',ARRAY['SC6-2-u3-X29']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C17","difficulty":1,"kind":"ox","stem":"전자석 기중기는 전자석을 이용해 철로 만든 무거운 물체를 들어 옮겨요.","answer":"O","reason_options":[{"t":"전기가 흐를 때 자석이 되어 철 물체를 붙였다가 뗄 수 있기 때문에","correct":true},{"t":"전자석은 철이 아닌 물체만 끌어당기기 때문에","mis":"SC6-2-u3-X29"}],"mis":"SC6-2-u3-X29","explanation":["철 물체를 붙여요.","옮긴 뒤 떼어요.","전자석 기중기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#3','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C16',1,'mc','auto','모둠 조사 게시판에서 전자석을 사용하는 예가 아닌 것은 어느 것인가요?',ARRAY['SC6-2-u3-X27']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"mc","stem":"모둠 조사 게시판에서 전자석을 사용하는 예가 아닌 것은 어느 것인가요?","options":[{"t":"㉲ 자석 낚시 놀이","correct":true},{"t":"㉮ 선풍기","mis":"SC6-2-u3-X27"},{"t":"㉯ 스피커","mis":"SC6-2-u3-X27"},{"t":"㉱ 세탁기","mis":"SC6-2-u3-X27"}],"explanation":["자석 낚시 놀이를 봐요.","전기가 흐르지 않아요.","영구 자석을 써요."],"asset":{"type":"passage","lines":["㉮ 선풍기 — 날개를 돌리고 바람 세기를 바꾼다.","㉯ 스피커 — 소리의 크기를 바꾼다.","㉰ 전자석 기중기 — 무거운 철 덩어리를 들어 옮긴다.","㉱ 세탁기 — 빨래 통을 돌린다.","㉲ 자석 낚시 놀이 — 자석 달린 낚싯대로 물고기 장난감을 낚는다."],"title":"모둠 조사 게시판 — 전자석을 찾아라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#4','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C16',1,'sa','auto','선풍기에는 「ㅈㅈㅅ」이 들어 있어요. 이 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"sa","stem":"선풍기에는 「ㅈㅈㅅ」이 들어 있어요. 이 말을 세 글자로 쓰세요.","answer":["전자석"],"explanation":["선풍기 날개가 돌아요.","세 글자예요.","전자석이에요."],"mis":"SC6-2-u3-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#5','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C17',2,'mc','auto','스피커에 쓰인 전자석으로 조절할 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X28']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"mc","stem":"스피커에 쓰인 전자석으로 조절할 수 있는 것은 어느 것인가요?","options":[{"t":"소리의 크기","correct":true},{"t":"바람의 세기","mis":"SC6-2-u3-X28"},{"t":"통이 도는 빠르기","mis":"SC6-2-u3-X28"},{"t":"무거운 철을 드는 높이","mis":"SC6-2-u3-X28"}],"explanation":["스피커는 소리를 내요.","전자석 세기를 조절해요.","소리 크기가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#6','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C17',2,'mc','auto','선풍기의 바람 세기를 바꿀 수 있는 것은 전자석의 어떤 성질 덕분인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X19','SC6-2-u3-X28']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"mc","stem":"선풍기의 바람 세기를 바꿀 수 있는 것은 전자석의 어떤 성질 덕분인가요?","options":[{"t":"전자석의 세기를 조절할 수 있는 성질","correct":true},{"t":"전자석은 늘 같은 세기를 내는 성질","mis":"SC6-2-u3-X20"},{"t":"전자석은 전기가 없어도 자석인 성질","mis":"SC6-2-u3-X19"},{"t":"전자석은 철을 밀어 내기만 하는 성질","mis":"SC6-2-u3-X28"}],"explanation":["세기를 조절해요.","날개 빠르기가 달라져요.","바람 세기가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#7','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C18',2,'mc','auto','전자석을 사용하는 예를 조사해 공유할 때 알맞은 태도는 어느 것인가요?',ARRAY['SC6-2-u3-X30']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C18","difficulty":2,"kind":"mc","stem":"전자석을 사용하는 예를 조사해 공유할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"검색한 자료의 출처를 밝히고, 다른 사람의 창작물은 허락 없이 쓰지 않는다","correct":true},{"t":"찾은 글을 출처 없이 그대로 붙여 넣는다","mis":"SC6-2-u3-X30"},{"t":"친구 게시물에 거친 말로 댓글을 단다","mis":"SC6-2-u3-X30"},{"t":"재미있어 보이는 아무 사이트나 들어간다","mis":"SC6-2-u3-X30"}],"explanation":["출처를 밝혀요.","허락을 지켜요.","고운 말로 댓글을 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#8','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C16',2,'mc','auto','전기 자동차에서 전자석이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X27','SC6-2-u3-X28']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C16","difficulty":2,"kind":"mc","stem":"전기 자동차에서 전자석이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"바퀴를 돌린다","correct":true},{"t":"창문을 투명하게 한다","mis":"SC6-2-u3-X27"},{"t":"의자를 푹신하게 한다","mis":"SC6-2-u3-X27"},{"t":"바퀴를 멈추지 못하게 한다","mis":"SC6-2-u3-X28"}],"explanation":["전기 자동차예요.","바퀴가 돌아요.","전자석을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#9','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C17',2,'ox','auto','영구 자석으로 기중기를 만들면 옮긴 철 물체를 원하는 곳에 쉽게 내려놓을 수 있어요.',ARRAY['SC6-2-u3-X29']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"ox","stem":"영구 자석으로 기중기를 만들면 옮긴 철 물체를 원하는 곳에 쉽게 내려놓을 수 있어요.","answer":"X","reason_options":[{"t":"영구 자석은 늘 자석이라 붙은 물체를 떼어 내기 어렵기 때문에","correct":true},{"t":"영구 자석은 전기를 끄면 바로 물체를 놓기 때문에","mis":"SC6-2-u3-X29"}],"mis":"SC6-2-u3-X29","explanation":["영구 자석은 늘 자석이에요.","떼기 어려워요.","전자석이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_basic#10','sci',6,2,'u3','L05','g6_2_sci_u3_L05_basic','lesson_basic','SC6-2-u3-C17',3,'error','auto','모둠 조사 게시판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X28','SC6-2-u3-X27']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"error","stem":"모둠 조사 게시판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「스피커의 전자석으로 바람 세기를 바꿔.」","correct":true,"mis_target":"SC6-2-u3-X28"},{"t":"지율 — 「세탁기는 전자석으로 빨래 통을 돌려.」","mis":"SC6-2-u3-X27"},{"t":"민하 — 「자석 낚시 놀이에는 전자석이 없어.」","mis":"SC6-2-u3-X27"}],"explanation":["스피커는 소리예요.","바람 세기는 선풍기예요.","라온의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉮ 선풍기 — 날개를 돌리고 바람 세기를 바꾼다.","㉯ 스피커 — 소리의 크기를 바꾼다.","㉰ 전자석 기중기 — 무거운 철 덩어리를 들어 옮긴다.","㉱ 세탁기 — 빨래 통을 돌린다.","㉲ 자석 낚시 놀이 — 자석 달린 낚싯대로 물고기 장난감을 낚는다."],"title":"모둠 조사 게시판 — 전자석을 찾아라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#1','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C17',2,'match','auto','전자석이 쓰인 물건과 쓰임새를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"match","stem":"전자석이 쓰인 물건과 쓰임새를 알맞게 이으세요.","pairs":[{"l":"선풍기","r":"바람의 세기를 조절함"},{"l":"스피커","r":"소리의 크기를 조절함"},{"l":"전자석 기중기","r":"무거운 철 물체를 원하는 곳으로 옮김"}],"mis":"SC6-2-u3-X28","explanation":["선풍기는 바람이에요.","스피커는 소리예요.","기중기는 철 물체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#2','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C16',2,'mc','auto','전기가 흐를 때만 공중에 떠 있는 장난감에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X19','SC6-2-u3-X27']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C16","difficulty":2,"kind":"mc","stem":"전기가 흐를 때만 공중에 떠 있는 장난감에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전기가 흐를 때만 자석이 되는 전자석을 쓴 것 같다","correct":true},{"t":"전기와 상관없이 늘 떠 있는 영구 자석만 쓴 것 같다","mis":"SC6-2-u3-X19"},{"t":"고무줄로 매달아 놓은 것 같다","mis":"SC6-2-u3-X27"},{"t":"전기가 끊기면 더 높이 뜰 것 같다","mis":"SC6-2-u3-X19"}],"explanation":["전기가 흐를 때만 떠요.","전자석의 성질이에요.","전자석을 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#3','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C17',3,'mc','auto','전자석 기중기가 철 덩어리를 들어 옮긴 뒤 내려놓는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X29','SC6-2-u3-X19']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"mc","stem":"전자석 기중기가 철 덩어리를 들어 옮긴 뒤 내려놓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"원하는 곳에서 전기를 끊어 전자석이 자석의 성질을 잃게 한다","correct":true},{"t":"전기를 더 세게 흘려 철 덩어리를 놓게 한다","mis":"SC6-2-u3-X20"},{"t":"영구 자석으로 바꾸어 철 덩어리를 놓게 한다","mis":"SC6-2-u3-X29"},{"t":"전자석은 한번 붙으면 놓을 수 없다","mis":"SC6-2-u3-X19"}],"explanation":["전기를 끊어요.","자석의 성질이 사라져요.","철 덩어리가 떨어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#4','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C17',3,'mc','auto','전자석 기중기가 전자석의 성질 가운데 이용하는 것을 모두 바르게 고른 것은 어느 것인가요?',ARRAY['SC6-2-u3-X22','SC6-2-u3-X19','SC6-2-u3-X28']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"mc","stem":"전자석 기중기가 전자석의 성질 가운데 이용하는 것을 모두 바르게 고른 것은 어느 것인가요?","options":[{"t":"세기를 조절할 수 있는 성질과 전기가 흐를 때만 자석이 되는 성질","correct":true},{"t":"극이 늘 일정한 성질과 세기가 늘 같은 성질","mis":"SC6-2-u3-X22"},{"t":"전기가 없어도 자석이 되는 성질","mis":"SC6-2-u3-X19"},{"t":"철이 아닌 물체를 끌어당기는 성질","mis":"SC6-2-u3-X28"}],"explanation":["세기를 조절해요.","전기가 흐를 때만이에요.","두 성질을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#5','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C16',3,'error','auto','교실에서 전자석을 사용하는 예를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X27','SC6-2-u3-X28']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C16","difficulty":3,"kind":"error","stem":"교실에서 전자석을 사용하는 예를 찾으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「냉장고에 붙은 자석 메모꽂이도 전자석이야.」","correct":true,"mis_target":"SC6-2-u3-X27"},{"t":"하늘 — 「선풍기 속 전동기에 전자석이 들어 있어.」","mis":"SC6-2-u3-X28"},{"t":"정우 — 「스피커에도 전자석을 써.」","mis":"SC6-2-u3-X28"}],"explanation":["메모꽂이는 전기가 없어요.","영구 자석이에요.","은재의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#6','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C18',3,'mc','auto','친구가 공유 공간에 올린 조사 글에 다는 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X30']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C18","difficulty":3,"kind":"mc","stem":"친구가 공유 공간에 올린 조사 글에 다는 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「세탁기 통도 전자석으로 돈다니 새롭게 알았어. 사진이 있어서 알기 쉬웠어.」","correct":true},{"t":"「그것도 몰랐어? 다 아는 거잖아.」","mis":"SC6-2-u3-X30"},{"t":"「내 글이 더 나으니 내 글만 봐.」","mis":"SC6-2-u3-X30"},{"t":"「사진 어디서 가져왔는지 안 밝혀도 돼.」","mis":"SC6-2-u3-X30"}],"explanation":["새로 안 점을 써요.","잘한 점을 칭찬해요.","고운 말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#7','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C16',3,'ox','auto','로봇 청소기가 움직일 때에도 전자석이 쓰여요.',ARRAY['SC6-2-u3-X27']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C16","difficulty":3,"kind":"ox","stem":"로봇 청소기가 움직일 때에도 전자석이 쓰여요.","answer":"O","reason_options":[{"t":"로봇 청소기 안의 전자석이 쓰인 장치가 바퀴와 솔을 움직이기 때문에","correct":true},{"t":"로봇 청소기는 전기 없이 영구 자석의 힘만으로 움직이기 때문에","mis":"SC6-2-u3-X27"}],"mis":"SC6-2-u3-X27","explanation":["로봇 청소기가 움직여요.","전기가 흘러요.","전자석이 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#8','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C17',4,'mc','auto','「만약 영구 자석으로 기중기를 만든다면?」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X29','SC6-2-u3-X22','SC6-2-u3-X19']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C17","difficulty":4,"kind":"mc","stem":"「만약 영구 자석으로 기중기를 만든다면?」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"철 물체를 붙이는 세기를 조절하거나 원하는 곳에 내려놓기 어려워 불편할 것이다","correct":true},{"t":"전기가 들지 않아 언제나 더 편리할 것이다","mis":"SC6-2-u3-X29"},{"t":"영구 자석도 전기를 끊으면 물체를 놓아 똑같을 것이다","mis":"SC6-2-u3-X22"},{"t":"영구 자석은 철을 끌어당기지 못해 아예 쓸 수 없다","mis":"SC6-2-u3-X19"}],"explanation":["영구 자석은 늘 자석이에요.","세기도 일정해요.","내려놓기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#9','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C18',4,'mc','auto','조사한 자료를 공유 공간에 올리려고 해요. 가장 알맞게 준비한 것은 어느 것인가요?',ARRAY['SC6-2-u3-X30']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C18","difficulty":4,"kind":"mc","stem":"조사한 자료를 공유 공간에 올리려고 해요. 가장 알맞게 준비한 것은 어느 것인가요?","options":[{"t":"대표 사진과 함께 쉬운 설명을 쓰고, 사진과 글을 가져온 곳을 밝힌다","correct":true},{"t":"다른 사람이 만든 영상을 허락 없이 통째로 올린다","mis":"SC6-2-u3-X30"},{"t":"친구 이름을 넣어 놀리는 글을 함께 올린다","mis":"SC6-2-u3-X30"},{"t":"검색 결과를 그대로 길게 붙여 넣는다","mis":"SC6-2-u3-X30"}],"explanation":["알기 쉽게 써요.","출처를 밝혀요.","창작물을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L05_challenge#10','sci',6,2,'u3','L05','g6_2_sci_u3_L05_challenge','lesson_challenge','SC6-2-u3-C17',4,'essay','teacher','전자석을 사용하는 예를 하나 골라, 그 물건이 전자석의 어떤 성질을 이용하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C17","difficulty":4,"kind":"essay","stem":"전자석을 사용하는 예를 하나 골라, 그 물건이 전자석의 어떤 성질을 이용하는지 쓰세요.","answer_guide":{"answer":"예: 선풍기 — 전자석의 세기를 조절할 수 있는 성질을 이용해 바람의 세기를 바꾼다. / 전자석 기중기 — 전기가 흐를 때만 자석이 되는 성질로 철 물체를 들었다가 내려놓는다.","scoring_points":["전자석을 쓰는 물건을 바르게 골랐는가","세기 조절이나 전기가 흐를 때만 자석이 되는 성질을 썼는가","물건의 쓰임새와 성질을 이어 썼는가"]},"explanation":["물건을 골라요.","어떤 성질인지 써요.","쓰임새와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#1','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C20',1,'mc','auto','플러그를 콘센트에서 뽑는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X34','SC6-2-u3-X36']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C20","difficulty":1,"kind":"mc","stem":"플러그를 콘센트에서 뽑는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"플러그의 머리 부분을 잡고 뽑는다","correct":true},{"t":"전선을 잡고 힘껏 당긴다","mis":"SC6-2-u3-X34"},{"t":"젖은 손으로 재빨리 뽑는다","mis":"SC6-2-u3-X36"},{"t":"발로 전선을 걸어 당긴다","mis":"SC6-2-u3-X34"}],"explanation":["머리 부분을 잡아요.","전선은 당기지 않아요.","마른 손으로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#2','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C19',1,'ox','auto','에너지 소비 효율 등급은 1등급에 가까울수록 효율이 높아요.',ARRAY['SC6-2-u3-X32']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C19","difficulty":1,"kind":"ox","stem":"에너지 소비 효율 등급은 1등급에 가까울수록 효율이 높아요.","answer":"O","reason_options":[{"t":"1등급에 가까운 제품일수록 같은 일을 하며 전기를 덜 쓰기 때문에","correct":true},{"t":"등급 숫자가 클수록 전기를 덜 쓰기 때문에","mis":"SC6-2-u3-X32"}],"mis":"SC6-2-u3-X32","explanation":["1등급을 봐요.","1등급에 가까울수록 좋아요.","전기를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#3','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C20',1,'mc','auto','전기를 안전하게 사용하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X35','SC6-2-u3-X37']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C20","difficulty":1,"kind":"mc","stem":"전기를 안전하게 사용하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"젖은 손으로 전기 기구를 만지지 않는다","correct":true},{"t":"한 콘센트에 플러그를 여러 개 한꺼번에 꽂는다","mis":"SC6-2-u3-X35"},{"t":"안 쓰는 콘센트는 덮개 없이 그대로 둔다","mis":"SC6-2-u3-X37"},{"t":"콘센트 옆에 종이 상자를 쌓아 둔다","mis":"SC6-2-u3-X37"}],"explanation":["물기는 위험해요.","마른 손으로 만져요.","감전을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#4','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C20',1,'sa','auto','전기가 통하고 있는 물체에 몸이 닿아 충격을 받는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C20","difficulty":1,"kind":"sa","stem":"전기가 통하고 있는 물체에 몸이 닿아 충격을 받는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["감전"],"explanation":["몸이 충격을 받아요.","두 글자예요.","감전이에요."],"mis":"SC6-2-u3-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#5','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C19',2,'mc','auto','우리 집 전기 사용 살펴보기에서 전기를 효율적으로 사용하는 모습은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X31']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"mc","stem":"우리 집 전기 사용 살펴보기에서 전기를 효율적으로 사용하는 모습은 어느 것인가요?","options":[{"t":"⑥","correct":true},{"t":"①","mis":"SC6-2-u3-X33"},{"t":"②","mis":"SC6-2-u3-X31"},{"t":"⑤","mis":"SC6-2-u3-X33"}],"explanation":["LED등으로 바꿨어요.","전기를 덜 써요.","⑥이에요."],"asset":{"type":"passage","lines":["① 아무도 없는 방에 전등이 켜져 있다.","② 꺼 둔 컴퓨터의 플러그가 그대로 꽂혀 있다.","③ 콘센트 하나에 플러그 다섯 개가 꽂혀 있다.","④ 손을 씻고 물기를 닦지 않은 채 머리 말리개 플러그를 꽂는다.","⑤ 냉장고 문을 자주 열었다 닫았다 한다.","⑥ 거실 전등을 LED등으로 바꾸었다."],"title":"우리 집 전기 사용 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#6','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C20',2,'mc','auto','우리 집 전기 사용 살펴보기에서 감전이나 화재가 일어날 수 있어 위험한 모습끼리 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X31']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C20","difficulty":2,"kind":"mc","stem":"우리 집 전기 사용 살펴보기에서 감전이나 화재가 일어날 수 있어 위험한 모습끼리 짝지은 것은 어느 것인가요?","options":[{"t":"③, ④","correct":true},{"t":"①, ⑥","mis":"SC6-2-u3-X33"},{"t":"②, ⑤","mis":"SC6-2-u3-X31"},{"t":"⑤, ⑥","mis":"SC6-2-u3-X33"}],"explanation":["콘센트 하나에 다섯 개예요.","물기 있는 손이에요.","③과 ④가 위험해요."],"asset":{"type":"passage","lines":["① 아무도 없는 방에 전등이 켜져 있다.","② 꺼 둔 컴퓨터의 플러그가 그대로 꽂혀 있다.","③ 콘센트 하나에 플러그 다섯 개가 꽂혀 있다.","④ 손을 씻고 물기를 닦지 않은 채 머리 말리개 플러그를 꽂는다.","⑤ 냉장고 문을 자주 열었다 닫았다 한다.","⑥ 거실 전등을 LED등으로 바꾸었다."],"title":"우리 집 전기 사용 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#7','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C19',2,'mc','auto','냉장고 문을 자주 여닫으면 생기는 문제로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X32','SC6-2-u3-X31']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"mc","stem":"냉장고 문을 자주 여닫으면 생기는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"전기가 낭비된다","correct":true},{"t":"전기가 저절로 아껴진다","mis":"SC6-2-u3-X33"},{"t":"냉장고 효율 등급이 1등급이 된다","mis":"SC6-2-u3-X32"},{"t":"플러그를 뽑은 것과 같아진다","mis":"SC6-2-u3-X31"}],"explanation":["문을 자주 열어요.","전기를 더 써요.","낭비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#8','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C21',2,'mc','auto','전기를 효율적이고 안전하게 사용해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X38','SC6-2-u3-X33']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C21","difficulty":2,"kind":"mc","stem":"전기를 효율적이고 안전하게 사용해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"전기를 아껴 자원 낭비를 줄이고, 감전 사고와 화재를 막기 위해서","correct":true},{"t":"전기는 끝없이 있으니 아낄 까닭은 없고 안전만 지키면 되어서","mis":"SC6-2-u3-X38"},{"t":"안전 수칙은 어른만 지키면 되어서","mis":"SC6-2-u3-X38"},{"t":"전기를 많이 써야 환경이 보호되어서","mis":"SC6-2-u3-X33"}],"explanation":["전기를 아껴요.","사고를 막아요.","둘 다 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#9','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C19',2,'ox','auto','전기 기구의 전원을 꺼 두면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않아요.',ARRAY['SC6-2-u3-X31']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"ox","stem":"전기 기구의 전원을 꺼 두면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않아요.","answer":"X","reason_options":[{"t":"플러그를 꽂아 두기만 해도 쓰이는 대기 전력이 있는 제품이 많기 때문에","correct":true},{"t":"전원 버튼만 끄면 콘센트와 이어져 있어도 전기가 끊기기 때문에","mis":"SC6-2-u3-X31"}],"mis":"SC6-2-u3-X31","explanation":["대기 전력이 있어요.","꽂아 두기만 해도 써요.","플러그를 뽑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_basic#10','sci',6,2,'u3','L06','g6_2_sci_u3_L06_basic','lesson_basic','SC6-2-u3-C20',3,'error','auto','전기 안전에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X35','SC6-2-u3-X37','SC6-2-u3-X34']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"error","stem":"전기 안전에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「멀티탭 하나에 난방기랑 전기 주전자를 다 꽂아도 괜찮아.」","correct":true,"mis_target":"SC6-2-u3-X35"},{"t":"하린 — 「안 쓰는 콘센트에는 안전 덮개를 꽂아 둬.」","mis":"SC6-2-u3-X37"},{"t":"준우 — 「플러그는 머리 부분을 잡고 뽑아.」","mis":"SC6-2-u3-X34"}],"explanation":["한꺼번에 많이 꽂았어요.","불이 날 수 있어요.","도윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#1','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',2,'match','auto','전기 사용 모습과 알맞은 쪽을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"match","stem":"전기 사용 모습과 알맞은 쪽을 이으세요.","pairs":[{"l":"형광등 대신 LED등 쓰기","r":"효율적으로 사용함"},{"l":"플러그 머리 부분 잡고 뽑기","r":"안전하게 사용함"},{"l":"빈방 전등 켜 두기","r":"낭비함"}],"mis":"SC6-2-u3-X33","explanation":["LED등은 전기를 덜 써요.","머리 부분을 잡아요.","빈방 전등은 낭비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#2','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',2,'mc','auto','두 선풍기의 등급 표시를 보고, 전기를 효율적으로 쓰려면 어느 것을 고르는 것이 알맞은가요?',ARRAY['SC6-2-u3-X32']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"mc","stem":"두 선풍기의 등급 표시를 보고, 전기를 효율적으로 쓰려면 어느 것을 고르는 것이 알맞은가요?","options":[{"t":"1등급인 선풍기 ㉮","correct":true},{"t":"4등급인 선풍기 ㉯","mis":"SC6-2-u3-X32"},{"t":"둘 다 같으니 아무것이나","mis":"SC6-2-u3-X32"},{"t":"등급 숫자가 큰 것","mis":"SC6-2-u3-X32"}],"explanation":["1등급을 봐요.","1등급에 가까울수록 좋아요.","㉮를 골라요."],"asset":{"type":"passage","lines":["선풍기 ㉮ — 에너지 소비 효율 1등급","선풍기 ㉯ — 에너지 소비 효율 4등급","두 선풍기는 크기와 기능이 같다."],"title":"두 선풍기의 등급 표시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#3','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',3,'mc','auto','콘센트마다 전기를 끊는 버튼이 따로 있는 멀티탭을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X31','SC6-2-u3-X35']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C19","difficulty":3,"kind":"mc","stem":"콘센트마다 전기를 끊는 버튼이 따로 있는 멀티탭을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 기구만 골라 전기를 끊어 대기 전력을 줄일 수 있다","correct":true},{"t":"버튼을 끄면 오히려 전기를 더 쓴다","mis":"SC6-2-u3-X33"},{"t":"플러그를 꽂아 두면 원래 전기를 안 쓰니 쓸모없다","mis":"SC6-2-u3-X31"},{"t":"여러 플러그를 한꺼번에 많이 꽂아도 안전해진다","mis":"SC6-2-u3-X35"}],"explanation":["하나씩 끌 수 있어요.","대기 전력을 줄여요.","효율적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#4','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',3,'mc','auto','우리 집 전기 사용 살펴보기의 ②를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X31','SC6-2-u3-X33','SC6-2-u3-X34']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C19","difficulty":3,"kind":"mc","stem":"우리 집 전기 사용 살펴보기의 ②를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않을 때는 컴퓨터 플러그를 뽑아 둔다","correct":true},{"t":"전원만 꺼 두었으니 그대로 둔다","mis":"SC6-2-u3-X31"},{"t":"컴퓨터를 계속 켜 둔다","mis":"SC6-2-u3-X33"},{"t":"전선을 잡아당겨 플러그를 뺀다","mis":"SC6-2-u3-X34"}],"explanation":["플러그가 꽂혀 있어요.","대기 전력이 쓰여요.","플러그를 뽑아요."],"asset":{"type":"passage","lines":["① 아무도 없는 방에 전등이 켜져 있다.","② 꺼 둔 컴퓨터의 플러그가 그대로 꽂혀 있다.","③ 콘센트 하나에 플러그 다섯 개가 꽂혀 있다.","④ 손을 씻고 물기를 닦지 않은 채 머리 말리개 플러그를 꽂는다.","⑤ 냉장고 문을 자주 열었다 닫았다 한다.","⑥ 거실 전등을 LED등으로 바꾸었다."],"title":"우리 집 전기 사용 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#5','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',3,'error','auto','전기를 효율적으로 쓰는 방법을 조사하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X32','SC6-2-u3-X33','SC6-2-u3-X31']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C19","difficulty":3,"kind":"error","stem":"전기를 효율적으로 쓰는 방법을 조사하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「에너지 소비 효율 등급은 숫자가 클수록 전기를 덜 써.」","correct":true,"mis_target":"SC6-2-u3-X32"},{"t":"서우 — 「사람이 지나갈 때만 켜지는 센서 등을 쓰면 전기를 아껴.」","mis":"SC6-2-u3-X33"},{"t":"하율 — 「쓰지 않는 기구는 플러그를 뽑아 둬.」","mis":"SC6-2-u3-X31"}],"explanation":["1등급에 가까울수록 좋아요.","숫자가 클수록이 아니에요.","지아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#6','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C20',3,'ox','auto','전기 안전을 알리는 역할놀이를 할 때에는 실제 전기 기구보다 모형 소품을 쓰는 것이 좋아요.',ARRAY['SC6-2-u3-X36']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"ox","stem":"전기 안전을 알리는 역할놀이를 할 때에는 실제 전기 기구보다 모형 소품을 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"실제 전기 기구를 쓰면 놀이하다가 다칠 수 있기 때문에","correct":true},{"t":"모형 소품에도 전기가 흘러 더 실감 나기 때문에","mis":"SC6-2-u3-X36"}],"mis":"SC6-2-u3-X36","explanation":["역할놀이를 해요.","실제 기구는 위험해요.","모형 소품을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#7','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C20',3,'mc','auto','안 쓰는 콘센트에 안전 덮개를 꽂아 두는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X37','SC6-2-u3-X35','SC6-2-u3-X38']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"mc","stem":"안 쓰는 콘센트에 안전 덮개를 꽂아 두는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"먼지가 쌓이거나 물이 닿아 불이 나는 것을 막으려고","correct":true},{"t":"콘센트에서 전기가 더 잘 나오게 하려고","mis":"SC6-2-u3-X37"},{"t":"덮개를 꽂으면 플러그를 여러 개 꽂을 수 있어서","mis":"SC6-2-u3-X35"},{"t":"덮개를 꽂아야 전기 요금이 늘어나서","mis":"SC6-2-u3-X38"}],"explanation":["먼지와 물을 막아요.","불을 막아요.","안전 덮개를 꽂아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#8','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C21',4,'mc','auto','「전기를 안전하게 사용해요!」라는 과학 글쓰기를 하려고 해요. 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X38','SC6-2-u3-X35']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C21","difficulty":4,"kind":"mc","stem":"「전기를 안전하게 사용해요!」라는 과학 글쓰기를 하려고 해요. 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물기 있는 곳에서 전기 기구를 쓰지 말고 플러그는 머리 부분을 잡고 뽑자고, 생활 속 장면과 함께 쓴다","correct":true},{"t":"무서운 사고 장면을 자세히 묘사해 겁을 준다","mis":"SC6-2-u3-X38"},{"t":"전기는 끝없이 있으니 마음껏 쓰자고 쓴다","mis":"SC6-2-u3-X38"},{"t":"콘센트 하나에 여러 플러그를 꽂는 요령을 쓴다","mis":"SC6-2-u3-X35"}],"explanation":["생활 속 장면이에요.","지킬 수 있는 방법이에요.","실천으로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#9','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',4,'mc','auto','여름에 교실 냉방을 하며 전기를 효율적으로 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X31']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C19","difficulty":4,"kind":"mc","stem":"여름에 교실 냉방을 하며 전기를 효율적으로 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"알맞은 온도를 지키고 에어컨과 선풍기를 함께 쓰며, 문을 닫아 둔다","correct":true},{"t":"온도를 아주 낮게 하고 문을 열어 둔다","mis":"SC6-2-u3-X33"},{"t":"아무도 없는 쉬는 시간에도 그대로 켜 둔다","mis":"SC6-2-u3-X33"},{"t":"냉방기를 끈 뒤 플러그는 꽂아 둬도 전기가 안 든다고 여긴다","mis":"SC6-2-u3-X31"}],"explanation":["알맞은 온도예요.","선풍기와 함께 써요.","문을 닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L06_challenge#10','sci',6,2,'u3','L06','g6_2_sci_u3_L06_challenge','lesson_challenge','SC6-2-u3-C19',4,'essay','teacher','전기를 효율적으로 사용하는 방법을 두 가지 쓰고, 효율적으로 써야 하는 까닭을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C19","difficulty":4,"kind":"essay","stem":"전기를 효율적으로 사용하는 방법을 두 가지 쓰고, 효율적으로 써야 하는 까닭을 함께 쓰세요.","answer_guide":{"answer":"예: 에너지 소비 효율 등급이 1등급에 가까운 제품을 쓴다. 쓰지 않는 전기 기구의 플러그를 뽑는다. 전기를 아껴 자원 낭비를 줄이고 환경을 지킬 수 있기 때문이다.","scoring_points":["효율적인 방법을 두 가지 썼는가","방법이 바른가","아껴야 하는 까닭을 썼는가"]},"explanation":["방법 두 가지예요.","등급과 플러그를 봐요.","자원과 환경을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#1','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',1,'mc','auto','전기 사용 실천 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X40']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C22","difficulty":1,"kind":"mc","stem":"전기 사용 실천 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 전기 기구의 플러그를 날마다 뽑는다","correct":true},{"t":"일주일 동안 전기를 하나도 쓰지 않는다","mis":"SC6-2-u3-X39"},{"t":"전기를 아끼는 척만 한다","mis":"SC6-2-u3-X39"},{"t":"실천은 한 번만 하고 끝낸다","mis":"SC6-2-u3-X40"}],"explanation":["내가 할 수 있어요.","날마다 해요.","알맞은 계획이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#2','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',1,'ox','auto','실천 점검표에 날마다 기록하면 실천을 꾸준히 이어 가는 데 도움이 돼요.',ARRAY['SC6-2-u3-X40']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C22","difficulty":1,"kind":"ox","stem":"실천 점검표에 날마다 기록하면 실천을 꾸준히 이어 가는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"한 날과 놓친 날을 보며 습관이 되도록 고칠 수 있기 때문에","correct":true},{"t":"한 번 기록하면 다시 실천하지 않아도 되기 때문에","mis":"SC6-2-u3-X40"}],"mis":"SC6-2-u3-X40","explanation":["날마다 기록해요.","놓친 날을 알아요.","꾸준히 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#3','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C23',1,'mc','auto','친구의 실천 결과 발표를 들을 때 알맞은 태도는 어느 것인가요?',ARRAY['SC6-2-u3-X41']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C23","difficulty":1,"kind":"mc","stem":"친구의 실천 결과 발표를 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"잘한 점을 찾아 칭찬한다","correct":true},{"t":"실천을 놓친 날을 찾아 놀린다","mis":"SC6-2-u3-X41"},{"t":"발표 중에 끼어들어 틀렸다고 외친다","mis":"SC6-2-u3-X41"},{"t":"내 발표가 더 낫다고 깎아내린다","mis":"SC6-2-u3-X41"}],"explanation":["끝까지 들어요.","잘한 점을 찾아요.","칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#4','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',1,'sa','auto','날마다 실천했는지 ○, ×로 적어 보는 표를 「실천 ○○표」라고 해요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C22","difficulty":1,"kind":"sa","stem":"날마다 실천했는지 ○, ×로 적어 보는 표를 「실천 ○○표」라고 해요. ○○에 들어갈 두 글자를 쓰세요.","answer":["점검"],"explanation":["실천을 살펴요.","두 글자예요.","점검이에요."],"mis":"SC6-2-u3-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#5','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',2,'mc','auto','도윤이의 전기 사용 실천 점검표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X31']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"mc","stem":"도윤이의 전기 사용 실천 점검표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"수요일 하루를 놓쳤고, 다음 주에는 잊지 않을 방법을 정했다","correct":true},{"t":"하루 놓쳤으니 실천을 그만두기로 했다","mis":"SC6-2-u3-X40"},{"t":"한 번도 실천하지 않았다","mis":"SC6-2-u3-X40"},{"t":"플러그는 꽂아 둬도 전기가 안 든다고 적었다","mis":"SC6-2-u3-X31"}],"explanation":["수요일에 ×예요.","쪽지를 붙이기로 했어요.","계속 실천해요."],"asset":{"type":"passage","lines":["나의 실천 — 쓰지 않는 전기 기구의 플러그 뽑기","월 ○ · 화 ○ · 수 × · 목 ○ · 금 ○","수요일에 놓친 까닭 — 서둘러 나가다 잊음","다음 주 다짐 — 현관에 「플러그!」 쪽지 붙이기"],"title":"도윤이의 전기 사용 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#6','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',2,'mc','auto','실천 계획을 세울 때 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X40']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"mc","stem":"실천 계획을 세울 때 알맞은 방법은 어느 것인가요?","options":[{"t":"배운 방법 가운데 내가 생활에서 지킬 수 있는 것을 구체적으로 정한다","correct":true},{"t":"되도록 많은 일을 한꺼번에 정해 두고 지키지 않는다","mis":"SC6-2-u3-X39"},{"t":"「전기를 아끼자」처럼 막연하게만 쓴다","mis":"SC6-2-u3-X39"},{"t":"실천은 하지 않고 계획만 세운다","mis":"SC6-2-u3-X40"}],"explanation":["지킬 수 있어야 해요.","구체적으로 정해요.","그래야 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#7','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C23',2,'mc','auto','가족 대화 「이번 달 전기 요금이 적게 나왔네!」에 이어질 말로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X41']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C23","difficulty":2,"kind":"mc","stem":"가족 대화 「이번 달 전기 요금이 적게 나왔네!」에 이어질 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「컴퓨터를 하지 않을 때 전원을 끄고 플러그를 뽑았기 때문이에요.」","correct":true},{"t":"「냉장고 문을 자주 열어 두었기 때문이에요.」","mis":"SC6-2-u3-X33"},{"t":"「빈방 전등을 켜 두었기 때문이에요.」","mis":"SC6-2-u3-X33"},{"t":"「누나는 실천 안 했으니 누나 탓이에요.」","mis":"SC6-2-u3-X41"}],"explanation":["전기를 아꼈어요.","전원과 플러그를 챙겼어요.","요금이 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#8','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',2,'mc','auto','효율과 안전을 함께 챙긴 실천 계획은 어느 것인가요?',ARRAY['SC6-2-u3-X34','SC6-2-u3-X36','SC6-2-u3-X45']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"mc","stem":"효율과 안전을 함께 챙긴 실천 계획은 어느 것인가요?","options":[{"t":"쓰지 않는 기구의 플러그를 뽑되, 마른 손으로 머리 부분을 잡고 뽑는다","correct":true},{"t":"플러그를 뽑을 때 전선을 잡아당긴다","mis":"SC6-2-u3-X34"},{"t":"젖은 손으로라도 서둘러 플러그를 뽑는다","mis":"SC6-2-u3-X36"},{"t":"안전은 생각하지 않고 아끼기만 한다","mis":"SC6-2-u3-X45"}],"explanation":["아끼기도 해요.","안전하게 해요.","둘 다 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#9','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C23',2,'ox','auto','실천하지 못한 친구의 경험을 발표할 때는 비난하지 않고 어떻게 고칠지 함께 생각해요.',ARRAY['SC6-2-u3-X41']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C23","difficulty":2,"kind":"ox","stem":"실천하지 못한 친구의 경험을 발표할 때는 비난하지 않고 어떻게 고칠지 함께 생각해요.","answer":"O","reason_options":[{"t":"서로 존중해야 모두가 실천을 이어 갈 수 있기 때문에","correct":true},{"t":"놓친 친구를 꾸짖어야 실천이 빨리 늘기 때문에","mis":"SC6-2-u3-X41"}],"mis":"SC6-2-u3-X41","explanation":["서로 존중해요.","고칠 방법을 찾아요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_basic#10','sci',6,2,'u3','L07','g6_2_sci_u3_L07_basic','lesson_basic','SC6-2-u3-C22',3,'error','auto','실천 계획을 발표하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X40']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"error","stem":"실천 계획을 발표하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「나는 내일부터 한 달 동안 전기를 하나도 안 쓸 거야.」","correct":true,"mis_target":"SC6-2-u3-X39"},{"t":"윤아 — 「나는 방에서 나올 때 전등을 끌게.」","mis":"SC6-2-u3-X40"},{"t":"규민 — 「나는 점검표에 날마다 표시할게.」","mis":"SC6-2-u3-X40"}],"explanation":["지킬 수 없는 계획이에요.","할 수 있는 것을 골라요.","태린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#1','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',2,'match','auto','실천 과정과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"match","stem":"실천 과정과 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획 세우기","r":"내가 지킬 수 있는 방법을 정함"},{"l":"실천하기","r":"점검표에 날마다 기록함"},{"l":"발표하기","r":"결과와 느낀 점을 나눔"}],"mis":"SC6-2-u3-X40","explanation":["먼저 계획해요.","기록하며 실천해요.","결과를 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#2','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C23',2,'mc','auto','실천 결과를 발표할 때 들어가면 좋은 내용은 어느 것인가요?',ARRAY['SC6-2-u3-X41','SC6-2-u3-X40','SC6-2-u3-X39']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C23","difficulty":2,"kind":"mc","stem":"실천 결과를 발표할 때 들어가면 좋은 내용은 어느 것인가요?","options":[{"t":"실천한 내용, 잘된 점과 어려웠던 점, 느낀 점","correct":true},{"t":"다른 친구가 실천하지 못한 일만","mis":"SC6-2-u3-X41"},{"t":"실천하지 않은 날을 숨긴 결과만","mis":"SC6-2-u3-X40"},{"t":"실천과 상관없는 이야기만","mis":"SC6-2-u3-X39"}],"explanation":["한 일을 말해요.","어려운 점도 말해요.","느낀 점을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#3','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',3,'mc','auto','도윤이의 전기 사용 실천 점검표에서 「다음 주 다짐」이 알맞은 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X39','SC6-2-u3-X41']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"mc","stem":"도윤이의 전기 사용 실천 점검표에서 「다음 주 다짐」이 알맞은 까닭은 어느 것인가요?","options":[{"t":"놓친 까닭을 찾아 다시 놓치지 않을 방법을 정했기 때문이다","correct":true},{"t":"한 번 놓쳤으니 실천을 멈추기로 했기 때문이다","mis":"SC6-2-u3-X40"},{"t":"지킬 수 없는 큰 계획으로 바꾸었기 때문이다","mis":"SC6-2-u3-X39"},{"t":"잊은 날을 친구 탓으로 돌렸기 때문이다","mis":"SC6-2-u3-X41"}],"explanation":["놓친 까닭을 찾았어요.","쪽지를 붙여요.","꾸준히 이어 가요."],"asset":{"type":"passage","lines":["나의 실천 — 쓰지 않는 전기 기구의 플러그 뽑기","월 ○ · 화 ○ · 수 × · 목 ○ · 금 ○","수요일에 놓친 까닭 — 서둘러 나가다 잊음","다음 주 다짐 — 현관에 「플러그!」 쪽지 붙이기"],"title":"도윤이의 전기 사용 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#4','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',3,'mc','auto','다음 실천 계획 가운데 고쳐야 할 것은 어느 것인가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X34']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"mc","stem":"다음 실천 계획 가운데 고쳐야 할 것은 어느 것인가요?","options":[{"t":"「전기를 열심히 아끼자.」","correct":true},{"t":"「쓰지 않는 충전기는 플러그를 뽑자.」","mis":"SC6-2-u3-X40"},{"t":"「방을 나올 때 전등을 끄자.」","mis":"SC6-2-u3-X40"},{"t":"「플러그는 머리 부분을 잡고 뽑자.」","mis":"SC6-2-u3-X34"}],"explanation":["막연한 계획이에요.","무엇을 할지 정해요.","구체적으로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#5','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C23',3,'error','auto','실천 결과 발표를 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X41','SC6-2-u3-X40']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C23","difficulty":3,"kind":"error","stem":"실천 결과 발표를 듣고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「사흘이나 놓쳤으면 실천했다고 말하지 마.」","correct":true,"mis_target":"SC6-2-u3-X41"},{"t":"나은 — 「다음 주에 쪽지를 붙인다는 생각이 좋아.」","mis":"SC6-2-u3-X40"},{"t":"도겸 — 「가족과 함께해서 전기 요금이 줄었구나.」","mis":"SC6-2-u3-X41"}],"explanation":["놓친 친구를 깎아내렸어요.","잘한 점을 찾아요.","시후의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#6','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',3,'ox','auto','실천 계획은 한 번 해 보고 잘되면 더 이상 점검하지 않아도 돼요.',ARRAY['SC6-2-u3-X40']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"ox","stem":"실천 계획은 한 번 해 보고 잘되면 더 이상 점검하지 않아도 돼요.","answer":"X","reason_options":[{"t":"습관이 될 때까지 꾸준히 점검하며 실천해야 하기 때문에","correct":true},{"t":"한 번 잘하면 저절로 평생 습관이 되기 때문에","mis":"SC6-2-u3-X40"}],"mis":"SC6-2-u3-X40","explanation":["한 번은 시작이에요.","꾸준히 점검해요.","습관이 되게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#7','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C23',3,'mc','auto','가족과 함께 실천하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X33','SC6-2-u3-X41']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C23","difficulty":3,"kind":"mc","stem":"가족과 함께 실천하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"집 전체에서 낭비되는 전기가 줄어 전기 요금도 줄고, 서로 안전을 챙길 수 있다","correct":true},{"t":"가족이 하면 나는 하지 않아도 된다","mis":"SC6-2-u3-X39"},{"t":"가족이 함께하면 전기를 더 써도 된다","mis":"SC6-2-u3-X33"},{"t":"가족이 실천을 놓치면 혼내야 한다","mis":"SC6-2-u3-X41"}],"explanation":["함께 실천해요.","전기 요금이 줄어요.","안전도 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#8','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',4,'mc','auto','사흘 동안 계속 「쓰지 않는 기구 플러그 뽑기」를 잊었어요. 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X39','SC6-2-u3-X31']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C22","difficulty":4,"kind":"mc","stem":"사흘 동안 계속 「쓰지 않는 기구 플러그 뽑기」를 잊었어요. 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"플러그를 뽑을 자리 옆에 알림 쪽지를 붙이고, 저녁마다 점검표에 표시한다","correct":true},{"t":"어차피 잊으니 계획을 없앤다","mis":"SC6-2-u3-X40"},{"t":"한 달 동안 집 전기를 모두 끄겠다고 바꾼다","mis":"SC6-2-u3-X39"},{"t":"플러그는 그대로 두고 전원만 끄면 같다고 여긴다","mis":"SC6-2-u3-X31"}],"explanation":["잊은 까닭을 찾아요.","알림을 붙여요.","점검표로 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#9','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',4,'mc','auto','친구의 실천 계획 「빨리 끄려고 젖은 손으로도 플러그를 바로 뽑기」에 해 줄 조언으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X45','SC6-2-u3-X34','SC6-2-u3-X40']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C22","difficulty":4,"kind":"mc","stem":"친구의 실천 계획 「빨리 끄려고 젖은 손으로도 플러그를 바로 뽑기」에 해 줄 조언으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「아끼는 건 좋지만 손의 물기를 닦고 머리 부분을 잡아 뽑자.」","correct":true},{"t":"「전기를 아끼니까 그대로 하면 돼.」","mis":"SC6-2-u3-X45"},{"t":"「전선을 잡고 당기면 더 빨라.」","mis":"SC6-2-u3-X34"},{"t":"「계획은 말로만 해도 충분해.」","mis":"SC6-2-u3-X40"}],"explanation":["아끼기는 좋아요.","안전도 챙겨요.","둘 다 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L07_challenge#10','sci',6,2,'u3','L07','g6_2_sci_u3_L07_challenge','lesson_challenge','SC6-2-u3-C22',4,'essay','teacher','내가 일주일 동안 지킬 효율적이고 안전한 전기 사용 실천 계획을 두 가지 세우고, 꾸준히 실천하기 위해 점검표를 어떻게 쓸지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C22","difficulty":4,"kind":"essay","stem":"내가 일주일 동안 지킬 효율적이고 안전한 전기 사용 실천 계획을 두 가지 세우고, 꾸준히 실천하기 위해 점검표를 어떻게 쓸지 쓰세요.","answer_guide":{"answer":"예: 방을 나올 때 전등 끄기, 플러그는 마른 손으로 머리 부분을 잡고 뽑기. 저녁마다 점검표에 ○, ×를 적고 놓친 날은 까닭을 적어 다음 날 고친다.","scoring_points":["효율적인 실천을 썼는가","안전한 실천을 썼는가","점검표를 날마다 쓰는 방법을 썼는가"]},"explanation":["지킬 수 있는 계획이에요.","효율과 안전을 챙겨요.","점검표로 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#1','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C24',1,'mc','auto','스마트 홈 소개 글의 ㉠처럼 사람이 없으면 조명이 알아서 꺼지면 좋은 점은 어느 것인가요?',ARRAY['SC6-2-u3-X42']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C24","difficulty":1,"kind":"mc","stem":"스마트 홈 소개 글의 ㉠처럼 사람이 없으면 조명이 알아서 꺼지면 좋은 점은 어느 것인가요?","options":[{"t":"빈방 전등으로 낭비되는 전기를 줄인다","correct":true},{"t":"전기를 더 많이 쓰게 된다","mis":"SC6-2-u3-X42"},{"t":"조명이 더 밝아진다","mis":"SC6-2-u3-X42"},{"t":"감전을 일으킨다","mis":"SC6-2-u3-X42"}],"explanation":["사람이 없어요.","조명이 꺼져요.","전기를 아껴요."],"asset":{"type":"passage","lines":["㉠ 사람이 없으면 거실 조명이 알아서 꺼진다.","㉡ 바깥 날씨에 맞춰 냉난방 온도가 알아서 바뀐다.","㉢ 밤이 되면 조명 밝기가 알아서 낮아진다.","㉣ 집 밖에서 휴대 전화로 켜 둔 전기 기구를 끈다."],"title":"스마트 홈 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#2','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C24',1,'ox','auto','인공지능은 건물의 냉난방 온도나 조명 밝기를 알아서 조절해 전기를 효율적으로 쓰도록 도울 수 있어요.',ARRAY['SC6-2-u3-X43']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C24","difficulty":1,"kind":"ox","stem":"인공지능은 건물의 냉난방 온도나 조명 밝기를 알아서 조절해 전기를 효율적으로 쓰도록 도울 수 있어요.","answer":"O","reason_options":[{"t":"필요한 만큼만 쓰도록 맞춰 낭비를 줄이기 때문에","correct":true},{"t":"인공지능이 있으면 전기가 하나도 들지 않기 때문에","mis":"SC6-2-u3-X43"}],"mis":"SC6-2-u3-X43","explanation":["알아서 조절해요.","필요한 만큼 써요.","낭비가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#3','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C25',1,'mc','auto','인공지능 발전 속도에 대한 두 의견에서 ㉮가 걱정하는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X43','SC6-2-u3-X44']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C25","difficulty":1,"kind":"mc","stem":"인공지능 발전 속도에 대한 두 의견에서 ㉮가 걱정하는 것은 어느 것인가요?","options":[{"t":"전기 사용량이 크게 늘어 정전·화재가 나거나 기후 위기가 빨라지는 것","correct":true},{"t":"조명이 알아서 꺼지는 것","mis":"SC6-2-u3-X43"},{"t":"냉난방 온도가 알맞게 맞춰지는 것","mis":"SC6-2-u3-X43"},{"t":"기술 발전으로 문제가 줄어드는 것","mis":"SC6-2-u3-X44"}],"explanation":["㉮를 읽어요.","전기를 많이 써요.","정전과 화재를 걱정해요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#4','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C24',1,'sa','auto','인공지능 같은 기술로 집 안의 전기 기구를 알아서 조절하는 집을 「스마트 ○」이라고 해요. ○에 들어갈 영어 낱말을 한글 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u3-C24","difficulty":1,"kind":"sa","stem":"인공지능 같은 기술로 집 안의 전기 기구를 알아서 조절하는 집을 「스마트 ○」이라고 해요. ○에 들어갈 영어 낱말을 한글 한 글자로 쓰세요.","answer":["홈"],"explanation":["집을 뜻해요.","한 글자예요.","스마트 홈이에요."],"mis":"SC6-2-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#5','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C24',2,'mc','auto','사람이 지나갈 때만 켜지는 센서 등과 같은 기술이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X01','SC6-2-u3-X09']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C24","difficulty":2,"kind":"mc","stem":"사람이 지나갈 때만 켜지는 센서 등과 같은 기술이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"필요할 때만 켜져 전기를 아낀다","correct":true},{"t":"하루 종일 켜져 전기를 더 쓴다","mis":"SC6-2-u3-X42"},{"t":"플러그를 꽂지 않아도 저절로 빛난다","mis":"SC6-2-u3-X01"},{"t":"전기가 흐르지 않는 물질로 만든다","mis":"SC6-2-u3-X09"}],"explanation":["사람이 지나가요.","그때만 켜져요.","전기를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#6','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C25',2,'mc','auto','인공지능 발전 속도에 대한 두 의견에서 ㉯의 근거로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X43','SC6-2-u3-X44']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C25","difficulty":2,"kind":"mc","stem":"인공지능 발전 속도에 대한 두 의견에서 ㉯의 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"인공지능이 냉난방 온도와 조명 밝기를 맞춰 전기를 아껴 준다","correct":true},{"t":"인공지능은 전기를 전혀 쓰지 않는다","mis":"SC6-2-u3-X43"},{"t":"정전이 나도 아무 상관이 없다","mis":"SC6-2-u3-X44"},{"t":"㉮의 말은 들을 필요도 없다","mis":"SC6-2-u3-X44"}],"explanation":["㉯를 읽어요.","효율을 돕는다고 해요.","그것이 근거예요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#7','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C24',2,'mc','auto','스마트 홈 기술이 있어도 우리가 계속 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X36','SC6-2-u3-X33']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C24","difficulty":2,"kind":"mc","stem":"스마트 홈 기술이 있어도 우리가 계속 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 기구를 끄고 전기를 안전하게 쓰는 습관을 지킨다","correct":true},{"t":"기술이 다 해 주니 아무것도 하지 않는다","mis":"SC6-2-u3-X42"},{"t":"젖은 손으로 기구를 만져도 기술이 막아 준다","mis":"SC6-2-u3-X36"},{"t":"전기를 마음껏 써도 된다","mis":"SC6-2-u3-X33"}],"explanation":["기술이 도와요.","실천도 함께해요.","습관을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#8','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C26',2,'mc','auto','스마트 홈 소개 글의 ㉣처럼 집 밖에서 켜 둔 전기 기구를 끌 수 있으면 좋은 점은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X45','SC6-2-u3-X31']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C26","difficulty":2,"kind":"mc","stem":"스마트 홈 소개 글의 ㉣처럼 집 밖에서 켜 둔 전기 기구를 끌 수 있으면 좋은 점은 어느 것인가요?","options":[{"t":"깜빡 잊고 켜 둔 기구로 낭비되는 전기를 줄이고 사고 걱정도 덜 수 있다","correct":true},{"t":"집에 있는 기구를 더 오래 켜 둘 수 있다","mis":"SC6-2-u3-X42"},{"t":"안전은 신경 쓰지 않아도 된다","mis":"SC6-2-u3-X45"},{"t":"플러그를 꽂아 둔 기구는 원래 전기를 안 쓴다","mis":"SC6-2-u3-X31"}],"explanation":["켜 둔 것을 꺼요.","낭비가 줄어요.","안전에도 도움이 돼요."],"asset":{"type":"passage","lines":["㉠ 사람이 없으면 거실 조명이 알아서 꺼진다.","㉡ 바깥 날씨에 맞춰 냉난방 온도가 알아서 바뀐다.","㉢ 밤이 되면 조명 밝기가 알아서 낮아진다.","㉣ 집 밖에서 휴대 전화로 켜 둔 전기 기구를 끈다."],"title":"스마트 홈 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#9','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C25',2,'ox','auto','토론할 때는 내 입장에 맞는 타당한 근거를 들어 주장해요.',ARRAY['SC6-2-u3-X44']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C25","difficulty":2,"kind":"ox","stem":"토론할 때는 내 입장에 맞는 타당한 근거를 들어 주장해요.","answer":"O","reason_options":[{"t":"근거가 있어야 듣는 사람이 주장을 믿고 따져 볼 수 있기 때문에","correct":true},{"t":"목소리를 크게 하면 근거는 없어도 되기 때문에","mis":"SC6-2-u3-X44"}],"mis":"SC6-2-u3-X44","explanation":["입장을 정해요.","근거를 들어요.","설득할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_basic#10','sci',6,2,'u3','L08','g6_2_sci_u3_L08_basic','lesson_basic','SC6-2-u3-C25',3,'error','auto','인공지능 발전 속도에 대한 두 의견을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X43','SC6-2-u3-X44']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"error","stem":"인공지능 발전 속도에 대한 두 의견을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「인공지능은 전기를 하나도 안 쓰니까 걱정할 게 없어.」","correct":true,"mis_target":"SC6-2-u3-X43"},{"t":"재희 — 「㉮는 전기 사용량이 늘어 정전이 날까 걱정해.」","mis":"SC6-2-u3-X44"},{"t":"온유 — 「㉯는 전기를 효율적으로 쓰게 돕는다고 해.」","mis":"SC6-2-u3-X44"}],"explanation":["인공지능도 전기를 써요.","두 면이 있어요.","서윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#1','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C24',2,'match','auto','스마트 홈 기술과 돕는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C24","difficulty":2,"kind":"match","stem":"스마트 홈 기술과 돕는 일을 알맞게 이으세요.","pairs":[{"l":"사람이 없으면 꺼지는 조명","r":"빈방에서 낭비되는 전기를 줄임"},{"l":"날씨에 맞춰 바뀌는 냉난방","r":"알맞은 온도로 전기를 아낌"},{"l":"밖에서 끄는 전기 기구","r":"깜빡 켜 둔 기구를 끔"}],"mis":"SC6-2-u3-X42","explanation":["조명을 꺼요.","온도를 맞춰요.","밖에서도 꺼요."],"asset":{"type":"passage","lines":["㉠ 사람이 없으면 거실 조명이 알아서 꺼진다.","㉡ 바깥 날씨에 맞춰 냉난방 온도가 알아서 바뀐다.","㉢ 밤이 되면 조명 밝기가 알아서 낮아진다.","㉣ 집 밖에서 휴대 전화로 켜 둔 전기 기구를 끈다."],"title":"스마트 홈 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#2','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',2,'mc','auto','인공지능 발전 속도에 대한 두 의견을 읽고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X43','SC6-2-u3-X44']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C25","difficulty":2,"kind":"mc","stem":"인공지능 발전 속도에 대한 두 의견을 읽고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인공지능은 전기 사용을 늘리기도 하고, 전기를 효율적으로 쓰도록 돕기도 한다","correct":true},{"t":"인공지능은 전기와 아무 상관이 없다","mis":"SC6-2-u3-X43"},{"t":"두 의견 가운데 하나는 근거가 하나도 없다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기를 늘리기만 한다","mis":"SC6-2-u3-X43"}],"explanation":["두 의견을 읽어요.","늘리기도 해요.","돕기도 해요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#3','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',3,'mc','auto','「인공지능의 발전 속도를 조절해야 한다」에 찬성하는 근거로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"mc","stem":"「인공지능의 발전 속도를 조절해야 한다」에 찬성하는 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"전기 사용량이 크게 늘면 정전이나 전력망에 무리가 가 화재가 날 수 있다","correct":true},{"t":"인공지능은 냉난방 온도를 알맞게 맞춰 준다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기를 전혀 쓰지 않는다","mis":"SC6-2-u3-X43"},{"t":"반대하는 사람들은 생각이 짧다","mis":"SC6-2-u3-X44"}],"explanation":["찬성 입장이에요.","걱정되는 점을 들어요.","정전과 화재예요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#4','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',3,'mc','auto','「인공지능의 발전 속도를 조절해야 한다」에 반대하는 근거로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"mc","stem":"「인공지능의 발전 속도를 조절해야 한다」에 반대하는 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"인공지능이 건물의 냉난방과 조명을 알맞게 맞춰 전기를 효율적으로 쓰게 돕는다","correct":true},{"t":"전기를 만들려고 석탄을 더 태우게 된다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기를 늘리기만 한다","mis":"SC6-2-u3-X43"},{"t":"찬성하는 사람의 말은 들을 필요가 없다","mis":"SC6-2-u3-X44"}],"explanation":["반대 입장이에요.","좋은 점을 들어요.","효율을 돕는다는 근거예요."],"asset":{"type":"passage","lines":["㉮ 「인공지능이 전기를 너무 많이 써 정전이나 화재가 날 수 있어요.","   전기를 만들려고 석탄과 석유를 더 태우면 기후 위기도 빨라져요.」","㉯ 「인공지능은 냉난방 온도와 조명 밝기를 알아서 맞춰 전기를 아껴 줘요.","   기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있어요.」"],"title":"인공지능 발전 속도에 대한 두 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#5','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C24',3,'error','auto','스마트 홈 소개 글을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X42']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C24","difficulty":3,"kind":"error","stem":"스마트 홈 소개 글을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「집이 알아서 다 하니까 우리는 전기 아끼는 습관이 필요 없어.」","correct":true,"mis_target":"SC6-2-u3-X42"},{"t":"지안 — 「㉡처럼 온도를 알맞게 맞추면 전기를 아껴.」","mis":"SC6-2-u3-X42"},{"t":"리아 — 「㉠은 빈방 전등 문제를 줄여 줘.」","mis":"SC6-2-u3-X42"}],"explanation":["기술은 도와줄 뿐이에요.","습관도 필요해요.","하온의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 사람이 없으면 거실 조명이 알아서 꺼진다.","㉡ 바깥 날씨에 맞춰 냉난방 온도가 알아서 바뀐다.","㉢ 밤이 되면 조명 밝기가 알아서 낮아진다.","㉣ 집 밖에서 휴대 전화로 켜 둔 전기 기구를 끈다."],"title":"스마트 홈 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#6','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',3,'ox','auto','토론에서 상대 의견이 나와 달라도 그 근거를 듣고 따져 보는 것이 좋아요.',ARRAY['SC6-2-u3-X44']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"ox","stem":"토론에서 상대 의견이 나와 달라도 그 근거를 듣고 따져 보는 것이 좋아요.","answer":"O","reason_options":[{"t":"상대의 근거를 알아야 내 주장을 더 탄탄하게 다듬을 수 있기 때문에","correct":true},{"t":"상대 의견은 틀렸으니 들을 필요가 없기 때문에","mis":"SC6-2-u3-X44"}],"mis":"SC6-2-u3-X44","explanation":["상대 근거를 들어요.","따져 봐요.","내 주장을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#7','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C24',3,'mc','auto','스마트 홈 소개 글의 ㉢처럼 밤에 조명 밝기가 알아서 낮아지면 좋은 점은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X01','SC6-2-u3-X31']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C24","difficulty":3,"kind":"mc","stem":"스마트 홈 소개 글의 ㉢처럼 밤에 조명 밝기가 알아서 낮아지면 좋은 점은 어느 것인가요?","options":[{"t":"필요한 만큼만 밝혀 전기를 덜 쓴다","correct":true},{"t":"밤새 가장 밝게 켜 두어 전기를 더 쓴다","mis":"SC6-2-u3-X42"},{"t":"전구가 전지 없이도 빛나게 된다","mis":"SC6-2-u3-X01"},{"t":"플러그를 뽑지 않아도 대기 전력이 사라진다","mis":"SC6-2-u3-X31"}],"explanation":["밝기를 낮춰요.","필요한 만큼이에요.","전기를 아껴요."],"asset":{"type":"passage","lines":["㉠ 사람이 없으면 거실 조명이 알아서 꺼진다.","㉡ 바깥 날씨에 맞춰 냉난방 온도가 알아서 바뀐다.","㉢ 밤이 되면 조명 밝기가 알아서 낮아진다.","㉣ 집 밖에서 휴대 전화로 켜 둔 전기 기구를 끈다."],"title":"스마트 홈 소개 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#8','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C26',4,'mc','auto','스마트 홈을 꾸민다면 효율과 안전을 함께 생각한 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X35','SC6-2-u3-X45']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"mc","stem":"스마트 홈을 꾸민다면 효율과 안전을 함께 생각한 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빈방 조명은 알아서 꺼지게 하고, 오래 켜 둔 기구는 알려 주게 하며, 콘센트에 플러그를 한꺼번에 몰아 꽂지 않는다","correct":true},{"t":"모든 기구를 하루 종일 켜 두고 기술에 맡긴다","mis":"SC6-2-u3-X42"},{"t":"콘센트 하나에 모든 기구를 꽂아 한꺼번에 조절한다","mis":"SC6-2-u3-X35"},{"t":"전기를 아끼는 기능만 넣고 안전은 생각하지 않는다","mis":"SC6-2-u3-X45"}],"explanation":["낭비를 줄여요.","안전도 챙겨요.","둘 다 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#9','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',4,'mc','auto','토론에서 주장하는 글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C25","difficulty":4,"kind":"mc","stem":"토론에서 주장하는 글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 반대한다. 인공지능이 냉난방과 조명을 알맞게 맞춰 전기를 아껴 주고, 기술이 발전하면 늘어나는 사용량 문제도 줄일 수 있기 때문이다.」","correct":true},{"t":"「나는 반대한다. 그냥 그렇게 생각하기 때문이다.」","mis":"SC6-2-u3-X44"},{"t":"「찬성하는 사람들은 아무것도 모른다.」","mis":"SC6-2-u3-X44"},{"t":"「인공지능은 전기를 안 쓰니 토론할 것도 없다.」","mis":"SC6-2-u3-X43"}],"explanation":["입장을 밝혀요.","근거가 둘이에요.","설득력이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_L08_challenge#10','sci',6,2,'u3','L08','g6_2_sci_u3_L08_challenge','lesson_challenge','SC6-2-u3-C25',4,'essay','teacher','「전기 사용량을 늘리는 인공지능의 발전 속도를 조절해야 한다」는 주장에 찬성과 반대 가운데 하나를 골라, 타당한 근거를 들어 주장하는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u3-C25","difficulty":4,"kind":"essay","stem":"「전기 사용량을 늘리는 인공지능의 발전 속도를 조절해야 한다」는 주장에 찬성과 반대 가운데 하나를 골라, 타당한 근거를 들어 주장하는 글을 쓰세요.","answer_guide":{"answer":"예(찬성): 인공지능은 전기 사용량을 크게 늘려 정전이나 화재를 일으킬 수 있고, 전기를 만들려고 석탄과 석유를 더 태우면 기후 위기가 빨라지므로 속도를 조절해야 한다. / 예(반대): 인공지능은 냉난방과 조명을 알맞게 맞춰 전기를 효율적으로 쓰게 돕고 기술 발전으로 사용량 문제도 줄일 수 있으므로 발전을 이어 가야 한다.","scoring_points":["찬성이나 반대 입장을 밝혔는가","입장에 맞는 타당한 근거를 들었는가","전기 사용이나 효율과 이어 썼는가"]},"explanation":["입장을 골라요.","근거를 들어요.","전기와 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#1','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C3',1,'mc','auto','반딧불반 탐구 일지 ①에서 해솔이 작품에 불이 켜지게 한 것은 어느 것인가요?',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C3","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ①에서 해솔이 작품에 불이 켜지게 한 것은 어느 것인가요?","options":[{"t":"전지를 넣은 것","correct":true},{"t":"그림을 더 크게 그린 것","mis":"SC6-2-u3-X01"},{"t":"셀로판테이프를 더 붙인 것","mis":"SC6-2-u3-X01"},{"t":"작품을 햇빛에 둔 것","mis":"SC6-2-u3-X01"}],"explanation":["전지가 없었어요.","전지를 넣었어요.","불이 켜졌어요."],"asset":{"type":"passage","lines":["우리 반은 줄 전구 세트로 「반딧불 숲」 작품을 만들었다.","먼저 숲 그림을 그리고, 줄 전구를 앞면에 셀로판테이프로 붙였다.","해솔이 작품은 전원을 켜도 꺼져 있었는데, 전지를 넣으니 켜졌다.","감상할 때 반딧불이 자리에 줄 전구를 쓴 점을 서로 칭찬했다."],"title":"① 빛나는 작품 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#2','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C2',1,'mc','auto','반딧불반 탐구 일지 ①에서 감상할 때 한 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X05','SC6-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ①에서 감상할 때 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"줄 전구가 쓰인 자리를 보고 잘된 점을 칭찬했다","correct":true},{"t":"전구 개수가 적은 작품을 골라 놀렸다","mis":"SC6-2-u3-X05"},{"t":"흠만 찾아 적었다","mis":"SC6-2-u3-X05"},{"t":"물병을 들고 가까이 가서 보았다","mis":"SC6-2-u3-X04"}],"explanation":["반딧불이 자리를 봤어요.","잘된 점을 찾았어요.","서로 칭찬했어요."],"asset":{"type":"passage","lines":["우리 반은 줄 전구 세트로 「반딧불 숲」 작품을 만들었다.","먼저 숲 그림을 그리고, 줄 전구를 앞면에 셀로판테이프로 붙였다.","해솔이 작품은 전원을 켜도 꺼져 있었는데, 전지를 넣으니 켜졌다.","감상할 때 반딧불이 자리에 줄 전구를 쓴 점을 서로 칭찬했다."],"title":"① 빛나는 작품 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#3','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C5',1,'mc','auto','반딧불반 탐구 일지 ②에서 전구에 불이 켜진 모둠끼리 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X07','SC6-2-u3-X10']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C5","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ②에서 전구에 불이 켜진 모둠끼리 짝지은 것은 어느 것인가요?","options":[{"t":"가람 모둠, 라희 모둠","correct":true},{"t":"나래 모둠, 다온 모둠","mis":"SC6-2-u3-X07"},{"t":"가람 모둠, 나래 모둠","mis":"SC6-2-u3-X07"},{"t":"다온 모둠, 라희 모둠","mis":"SC6-2-u3-X10"}],"explanation":["켜짐을 찾아요.","가람과 라희예요.","끊어진 곳이 없어요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#4','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C8',1,'mc','auto','반딧불반 탐구 일지 ②에서 다온 모둠의 전구에 불이 켜지지 않은 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X10','SC6-2-u3-X08','SC6-2-u3-X11']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C8","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ②에서 다온 모둠의 전구에 불이 켜지지 않은 까닭은 어느 것인가요?","options":[{"t":"전기가 잘 흐르지 않는 유리 부분에 집게를 물려서","correct":true},{"t":"금속 부분에 집게를 물려서","mis":"SC6-2-u3-X10"},{"t":"스위치를 닫아서","mis":"SC6-2-u3-X08"},{"t":"전구 끼우개 속이 원래 끊어져 있어서","mis":"SC6-2-u3-X11"}],"explanation":["유리 부분이에요.","전기가 잘 안 흘러요.","금속에 물려요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#5','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C10',1,'mc','auto','반딧불반 탐구 일지 ③에서 전구가 더 밝았던 회로는 어느 것인가요?',ARRAY['SC6-2-u3-X15']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C10","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ③에서 전구가 더 밝았던 회로는 어느 것인가요?","options":[{"t":"전지 두 개를 직렬연결한 회로","correct":true},{"t":"전지 한 개를 이은 회로","mis":"SC6-2-u3-X15"},{"t":"두 회로가 똑같다","mis":"SC6-2-u3-X15"},{"t":"두 회로 모두 꺼졌다","mis":"SC6-2-u3-X15"}],"explanation":["전지 두 개 쪽이에요.","직렬로 이었어요.","더 밝아요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#6','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C13',1,'mc','auto','반딧불반 탐구 일지 ④에서 스위치를 닫기 전 전자석에 철 클립이 붙지 않은 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X19','SC6-2-u3-X22','SC6-2-u3-X20']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C13","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ④에서 스위치를 닫기 전 전자석에 철 클립이 붙지 않은 까닭은 어느 것인가요?","options":[{"t":"전기가 흐르지 않아 자석의 성질이 없어서","correct":true},{"t":"전자석은 늘 자석이라서","mis":"SC6-2-u3-X19"},{"t":"철 클립은 자석에 붙지 않는 물질이라서","mis":"SC6-2-u3-X22"},{"t":"전지를 너무 많이 이어서","mis":"SC6-2-u3-X20"}],"explanation":["스위치를 안 닫았어요.","전기가 안 흘러요.","자석이 아니에요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#7','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C17',1,'mc','auto','반딧불반 탐구 일지 ⑤의 기중기 영상에서 철 덩어리가 내려앉은 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X29','SC6-2-u3-X28']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C17","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ⑤의 기중기 영상에서 철 덩어리가 내려앉은 까닭은 어느 것인가요?","options":[{"t":"전기를 끊어 전자석이 자석의 성질을 잃었기 때문이다","correct":true},{"t":"전기를 더 세게 흘렸기 때문이다","mis":"SC6-2-u3-X20"},{"t":"기중기가 영구 자석이기 때문이다","mis":"SC6-2-u3-X29"},{"t":"전자석은 철을 들 수 없기 때문이다","mis":"SC6-2-u3-X28"}],"explanation":["전기를 끊었어요.","자석이 아니에요.","내려앉았어요."],"asset":{"type":"passage","lines":["선풍기·스피커·세탁기·전자석 기중기를 조사해 학급 게시판에 올렸다.","사진 아래에 사진을 가져온 곳을 적었다.","기중기 영상 — 전기를 끊자 매달려 있던 철 덩어리가 내려앉았다.","친구 글에는 새로 안 점을 고운 말로 댓글로 달았다."],"title":"⑤ 전자석 쓰임 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#8','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C19',1,'mc','auto','반딧불반 탐구 일지 ⑥에서 전기를 효율적으로 쓰는 모습은 어느 것인가요?',ARRAY['SC6-2-u3-X31','SC6-2-u3-X35','SC6-2-u3-X36']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C19","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥에서 전기를 효율적으로 쓰는 모습은 어느 것인가요?","options":[{"t":"㉢ 1등급 냉장고","correct":true},{"t":"㉠ 플러그를 꽂아 둔 텔레비전","mis":"SC6-2-u3-X31"},{"t":"㉡ 콘센트 하나에 여러 기구","mis":"SC6-2-u3-X35"},{"t":"㉣ 젖은 손으로 머리 말리개","mis":"SC6-2-u3-X36"}],"explanation":["1등급이에요.","전기를 덜 써요.","효율적이에요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
