INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#10','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C11',2,'mc','auto','반딧불반 탐구 일지 ③에서 버저가 처음에 울리지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X17','SC6-2-u3-X16','SC6-2-u3-X14']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C11","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ③에서 버저가 처음에 울리지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"버저를 잇는 방향이 거꾸로였기 때문이다","correct":true},{"t":"버저는 방향과 상관없이 늘 울리기 때문이다","mis":"SC6-2-u3-X17"},{"t":"전지를 직렬연결하면 버저는 울리지 않기 때문이다","mis":"SC6-2-u3-X16"},{"t":"전지를 (+)극끼리 이었기 때문이다","mis":"SC6-2-u3-X14"}],"explanation":["전선을 바꿔 이었어요.","그러자 울렸어요.","방향 때문이었어요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#11','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C15',2,'mc','auto','반딧불반 탐구 일지 ④에서 나침반 바늘이 반대쪽을 가리킨 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X21','SC6-2-u3-X25','SC6-2-u3-X20']::text[],false,'{"seq":11,"concept":"SC6-2-u3-C15","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ④에서 나침반 바늘이 반대쪽을 가리킨 까닭은 어느 것인가요?","options":[{"t":"전지 방향을 바꾸어 전자석의 극이 반대로 바뀌었기 때문이다","correct":true},{"t":"전자석의 극은 늘 그대로이기 때문이다","mis":"SC6-2-u3-X21"},{"t":"나침반이 망가졌기 때문이다","mis":"SC6-2-u3-X25"},{"t":"철 클립이 더 많이 붙었기 때문이다","mis":"SC6-2-u3-X20"}],"explanation":["전지 방향을 바꿨어요.","극이 바뀌었어요.","바늘도 반대예요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#12','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C18',2,'mc','auto','반딧불반 탐구 일지 ⑤에서 사진 아래에 가져온 곳을 적은 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X30']::text[],false,'{"seq":12,"concept":"SC6-2-u3-C18","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑤에서 사진 아래에 가져온 곳을 적은 까닭은 어느 것인가요?","options":[{"t":"다른 사람의 자료를 쓸 때는 출처를 밝혀야 하기 때문이다","correct":true},{"t":"출처를 적으면 글자 수가 늘어나기 때문이다","mis":"SC6-2-u3-X30"},{"t":"사진은 아무 데서나 가져와도 되기 때문이다","mis":"SC6-2-u3-X30"},{"t":"출처는 선생님만 밝히면 되기 때문이다","mis":"SC6-2-u3-X30"}],"explanation":["남의 자료예요.","출처를 밝혀요.","창작물을 존중해요."],"asset":{"type":"passage","lines":["선풍기·스피커·세탁기·전자석 기중기를 조사해 학급 게시판에 올렸다.","사진 아래에 사진을 가져온 곳을 적었다.","기중기 영상 — 전기를 끊자 매달려 있던 철 덩어리가 내려앉았다.","친구 글에는 새로 안 점을 고운 말로 댓글로 달았다."],"title":"⑤ 전자석 쓰임 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#13','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C19',2,'mc','auto','반딧불반 탐구 일지 ⑥의 ㉠을 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X31','SC6-2-u3-X33','SC6-2-u3-X34']::text[],false,'{"seq":13,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥의 ㉠을 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"텔레비전을 보지 않을 때는 플러그를 뽑는다","correct":true},{"t":"전원만 꺼 두었으니 그대로 둔다","mis":"SC6-2-u3-X31"},{"t":"텔레비전을 계속 켜 둔다","mis":"SC6-2-u3-X33"},{"t":"전선을 잡아당겨 플러그를 뺀다","mis":"SC6-2-u3-X34"}],"explanation":["플러그가 꽂혀 있어요.","대기 전력이 쓰여요.","플러그를 뽑아요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#14','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C20',2,'mc','auto','반딧불반 탐구 일지 ⑥의 ㉡이 위험한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X38','SC6-2-u3-X34','SC6-2-u3-X37']::text[],false,'{"seq":14,"concept":"SC6-2-u3-C20","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥의 ㉡이 위험한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 콘센트에 여러 플러그를 한꺼번에 꽂아 불이 날 수 있어서","correct":true},{"t":"전기 요금이 줄어들어서","mis":"SC6-2-u3-X38"},{"t":"플러그를 머리 부분으로 꽂아서","mis":"SC6-2-u3-X34"},{"t":"안전 덮개를 꽂아서","mis":"SC6-2-u3-X37"}],"explanation":["한꺼번에 꽂았어요.","불이 날 수 있어요.","나누어 꽂아요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#15','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C22',2,'mc','auto','반딧불반 탐구 일지 ⑦의 실천 점검표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X39']::text[],false,'{"seq":15,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑦의 실천 점검표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"목요일 하루를 잊었지만 나머지 날은 실천했다","correct":true},{"t":"한 번도 실천하지 않았다","mis":"SC6-2-u3-X40"},{"t":"하루 잊었으니 실천을 그만두었다","mis":"SC6-2-u3-X40"},{"t":"지킬 수 없는 계획이라 모두 못 했다","mis":"SC6-2-u3-X39"}],"explanation":["목요일만 ×예요.","나머지는 ○예요.","꾸준히 했어요."],"asset":{"type":"passage","lines":["나의 실천 — 방을 나올 때 전등 끄기","월 ○ · 화 ○ · 수 ○ · 목 × · 금 ○ (목요일은 급히 나가다 잊음)","가족 실천 — 쓰지 않는 기구 플러그 뽑기","이번 달 전기 요금이 줄었다고 엄마가 말씀하셨다."],"title":"⑦ 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#16','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C24',2,'mc','auto','반딧불반 탐구 일지 ⑧의 스마트 홈 체험관에서 전기를 아끼도록 돕는 기술은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X01']::text[],false,'{"seq":16,"concept":"SC6-2-u3-C24","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑧의 스마트 홈 체험관에서 전기를 아끼도록 돕는 기술은 어느 것인가요?","options":[{"t":"사람이 없으면 조명이 꺼지는 기술","correct":true},{"t":"조명을 늘 가장 밝게 켜 두는 기술","mis":"SC6-2-u3-X42"},{"t":"전기 없이 조명이 켜지는 기술","mis":"SC6-2-u3-X01"},{"t":"냉난방을 날씨와 상관없이 세게 트는 기술","mis":"SC6-2-u3-X42"}],"explanation":["사람이 없어요.","조명이 꺼져요.","전기를 아껴요."],"asset":{"type":"passage","lines":["스마트 홈 체험관 — 사람이 없으면 조명이 꺼지고, 날씨에 맞춰 냉난방이 바뀐다.","토론 주제 — 인공지능의 발전 속도를 조절해야 할까?","찬성 — 전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다.","반대 — 전기를 효율적으로 쓰게 도와 사용량 문제를 줄일 수 있다."],"title":"⑧ 스마트 홈 체험과 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#17','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C8',3,'mc','auto','반딧불반 탐구 일지 ②의 다온 모둠이 불을 켜려면 어떻게 고쳐야 하나요?',ARRAY['SC6-2-u3-X10','SC6-2-u3-X08','SC6-2-u3-X11']::text[],false,'{"seq":17,"concept":"SC6-2-u3-C8","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ②의 다온 모둠이 불을 켜려면 어떻게 고쳐야 하나요?","options":[{"t":"집게를 전구의 금속 몸체에 물린다","correct":true},{"t":"집게를 전구 유리에 더 세게 누른다","mis":"SC6-2-u3-X10"},{"t":"스위치를 열어 둔다","mis":"SC6-2-u3-X08"},{"t":"전구 끼우개는 끊어져 있으니 빼 버린다","mis":"SC6-2-u3-X11"}],"explanation":["유리는 전기가 잘 안 흘러요.","금속에 물려요.","그러면 켜져요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#18','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C10',3,'mc','auto','반딧불반 탐구 일지 ③에 이어 전지를 같은 방법으로 하나 더 직렬연결해 세 개로 하면 전구는 어떻게 될까요?',ARRAY['SC6-2-u3-X15','SC6-2-u3-X18']::text[],false,'{"seq":18,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ③에 이어 전지를 같은 방법으로 하나 더 직렬연결해 세 개로 하면 전구는 어떻게 될까요?","options":[{"t":"두 개일 때보다 더 밝아질 것이다","correct":true},{"t":"두 개일 때보다 어두워질 것이다","mis":"SC6-2-u3-X15"},{"t":"두 개일 때와 똑같을 것이다","mis":"SC6-2-u3-X15"},{"t":"전구 대신 다른 부품을 바꿔야 알 수 있다","mis":"SC6-2-u3-X18"}],"explanation":["전지가 늘어요.","많을수록 밝아요.","더 밝아져요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#19','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C14',3,'mc','auto','반딧불반 탐구 일지 ④의 결과로 전자석과 영구 자석을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X22']::text[],false,'{"seq":19,"concept":"SC6-2-u3-C14","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ④의 결과로 전자석과 영구 자석을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"영구 자석은 세기가 일정하지만, 전자석은 직렬로 이은 전지가 많을수록 세진다","correct":true},{"t":"둘 다 세기가 늘 같다","mis":"SC6-2-u3-X20"},{"t":"영구 자석도 전지를 붙이면 세진다","mis":"SC6-2-u3-X22"},{"t":"전자석은 전지가 많을수록 약해진다","mis":"SC6-2-u3-X20"}],"explanation":["철 클립이 늘었어요.","전자석은 세져요.","영구 자석은 일정해요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#20','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C17',3,'mc','auto','반딧불반 탐구 일지 ⑤의 기중기 영상에서 알 수 있는 전자석의 성질은 어느 것인가요?',ARRAY['SC6-2-u3-X22','SC6-2-u3-X19','SC6-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ⑤의 기중기 영상에서 알 수 있는 전자석의 성질은 어느 것인가요?","options":[{"t":"전기가 흐를 때만 자석이 되는 성질","correct":true},{"t":"극이 늘 일정한 성질","mis":"SC6-2-u3-X22"},{"t":"전기가 없어도 철을 붙잡는 성질","mis":"SC6-2-u3-X19"},{"t":"철이 아닌 물체만 드는 성질","mis":"SC6-2-u3-X28"}],"explanation":["전기를 끊었어요.","철이 떨어졌어요.","흐를 때만 자석이에요."],"asset":{"type":"passage","lines":["선풍기·스피커·세탁기·전자석 기중기를 조사해 학급 게시판에 올렸다.","사진 아래에 사진을 가져온 곳을 적었다.","기중기 영상 — 전기를 끊자 매달려 있던 철 덩어리가 내려앉았다.","친구 글에는 새로 안 점을 고운 말로 댓글로 달았다."],"title":"⑤ 전자석 쓰임 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#21','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C20',3,'mc','auto','반딧불반 탐구 일지 ⑥의 ㉡을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X35','SC6-2-u3-X34','SC6-2-u3-X37']::text[],false,'{"seq":21,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥의 ㉡을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기구를 여러 콘센트에 나누어 꽂고, 쓰지 않는 것은 플러그를 뽑는다","correct":true},{"t":"멀티탭을 하나 더 이어 더 많이 꽂는다","mis":"SC6-2-u3-X35"},{"t":"전선을 잡아당겨 한꺼번에 뺀다","mis":"SC6-2-u3-X34"},{"t":"그대로 두고 안전 덮개만 사 둔다","mis":"SC6-2-u3-X37"}],"explanation":["한꺼번에 꽂았어요.","나누어 꽂아요.","안 쓰면 뽑아요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#22','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C22',3,'mc','auto','반딧불반 탐구 일지 ⑦의 실천을 이어 가려면 목요일에 잊은 일을 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC6-2-u3-X40','SC6-2-u3-X39']::text[],false,'{"seq":22,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ⑦의 실천을 이어 가려면 목요일에 잊은 일을 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"잊은 까닭을 생각해 방문에 알림 쪽지를 붙이고 점검표를 계속 쓴다","correct":true},{"t":"하루 잊었으니 점검표를 그만 쓴다","mis":"SC6-2-u3-X40"},{"t":"한 달 동안 전기를 하나도 안 쓰기로 바꾼다","mis":"SC6-2-u3-X39"},{"t":"잊은 날은 ○로 고쳐 적는다","mis":"SC6-2-u3-X40"}],"explanation":["까닭을 찾아요.","알림을 붙여요.","계속 점검해요."],"asset":{"type":"passage","lines":["나의 실천 — 방을 나올 때 전등 끄기","월 ○ · 화 ○ · 수 ○ · 목 × · 금 ○ (목요일은 급히 나가다 잊음)","가족 실천 — 쓰지 않는 기구 플러그 뽑기","이번 달 전기 요금이 줄었다고 엄마가 말씀하셨다."],"title":"⑦ 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#23','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C14',4,'mc','auto','반딧불반 탐구 일지 ③과 ④를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X21']::text[],false,'{"seq":23,"concept":"SC6-2-u3-C14","difficulty":4,"kind":"mc","stem":"반딧불반 탐구 일지 ③과 ④를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"직렬로 이은 전지가 많을수록 전구는 더 밝아지고 전자석은 더 세진다","correct":true},{"t":"전지 개수는 전구와 전자석 모두에 상관없다","mis":"SC6-2-u3-X20"},{"t":"전구는 밝아지지만 전자석은 약해진다","mis":"SC6-2-u3-X20"},{"t":"전자석은 전지 방향만 바꾸면 세진다","mis":"SC6-2-u3-X21"}],"explanation":["③은 전구예요.","④는 전자석이에요.","전지가 많을수록 세져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#24','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C26',4,'mc','auto','반딧불반 탐구 일지 ⑥을 바탕으로 우리 집 전기 사용 규칙을 만든다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X45','SC6-2-u3-X31','SC6-2-u3-X36']::text[],false,'{"seq":24,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥을 바탕으로 우리 집 전기 사용 규칙을 만든다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쓰지 않는 기구는 플러그를 뽑고, 콘센트는 나누어 쓰며, 마른 손으로 머리 부분을 잡아 뽑는다","correct":true},{"t":"전기를 아끼기만 하면 콘센트 하나에 몰아 꽂아도 된다","mis":"SC6-2-u3-X45"},{"t":"안전만 지키면 플러그는 꽂아 둬도 된다","mis":"SC6-2-u3-X31"},{"t":"젖은 손이라도 빨리 뽑으면 된다","mis":"SC6-2-u3-X36"}],"explanation":["아끼기도 해요.","안전도 챙겨요.","둘 다 규칙이에요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_a#25','sci',6,2,'u3','','g6_2_sci_u3_review_a','unit_review','SC6-2-u3-C25',4,'essay','teacher','반딧불반 탐구 일지 ⑧의 토론 주제에 찬성과 반대 가운데 하나를 골라, 타당한 근거 두 가지를 들어 주장하는 글을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u3-C25","difficulty":4,"kind":"essay","stem":"반딧불반 탐구 일지 ⑧의 토론 주제에 찬성과 반대 가운데 하나를 골라, 타당한 근거 두 가지를 들어 주장하는 글을 쓰세요.","answer_guide":{"answer":"예(반대): 인공지능은 냉난방 온도와 조명 밝기를 알맞게 맞춰 전기를 효율적으로 쓰게 돕는다. 또 기술이 발전하면 늘어나는 전기 사용량 문제도 줄일 수 있다. 그러므로 발전을 이어 가야 한다.","scoring_points":["입장을 밝혔는가","타당한 근거를 두 가지 들었는가","전기 사용·효율과 이어 썼는가"]},"explanation":["입장을 골라요.","근거를 두 가지 들어요.","전기와 이어 써요."],"asset":{"type":"passage","lines":["스마트 홈 체험관 — 사람이 없으면 조명이 꺼지고, 날씨에 맞춰 냉난방이 바뀐다.","토론 주제 — 인공지능의 발전 속도를 조절해야 할까?","찬성 — 전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다.","반대 — 전기를 효율적으로 쓰게 도와 사용량 문제를 줄일 수 있다."],"title":"⑧ 스마트 홈 체험과 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#1','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C1',1,'mc','auto','반딧불반 탐구 일지 ①에서 줄 전구를 붙인 곳은 어디인가요?',ARRAY['SC6-2-u3-X03','SC6-2-u3-X04','SC6-2-u3-X02']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C1","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ①에서 줄 전구를 붙인 곳은 어디인가요?","options":[{"t":"작품 앞면","correct":true},{"t":"구멍을 뚫은 작품 뒷면","mis":"SC6-2-u3-X03"},{"t":"물병 옆 책상","mis":"SC6-2-u3-X04"},{"t":"그림을 그리기 전의 빈 도화지 뒤","mis":"SC6-2-u3-X02"}],"explanation":["앞면에 붙였어요.","셀로판테이프로요.","구멍은 뚫지 않아요."],"asset":{"type":"passage","lines":["우리 반은 줄 전구 세트로 「반딧불 숲」 작품을 만들었다.","먼저 숲 그림을 그리고, 줄 전구를 앞면에 셀로판테이프로 붙였다.","해솔이 작품은 전원을 켜도 꺼져 있었는데, 전지를 넣으니 켜졌다.","감상할 때 반딧불이 자리에 줄 전구를 쓴 점을 서로 칭찬했다."],"title":"① 빛나는 작품 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#2','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C2',1,'ox','auto','줄 전구 작품 활동 전에 책상 위 물병을 치워요.',ARRAY['SC6-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":1,"kind":"ox","stem":"줄 전구 작품 활동 전에 책상 위 물병을 치워요.","answer":"O","reason_options":[{"t":"물이 쏟아져 전기 제품에 닿으면 위험하기 때문에","correct":true},{"t":"물병이 있으면 그림 색이 흐려지기 때문에","mis":"SC6-2-u3-X04"}],"mis":"SC6-2-u3-X04","explanation":["물병을 치워요.","물기는 위험해요.","안전하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#3','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C4',1,'mc','auto','전선이 전기 회로에서 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X12']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C4","difficulty":1,"kind":"mc","stem":"전선이 전기 회로에서 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"전기가 흐르는 길이 된다","correct":true},{"t":"전기 에너지를 만들어 준다","mis":"SC6-2-u3-X12"},{"t":"전기가 흐르면 빛을 낸다","mis":"SC6-2-u3-X12"},{"t":"회로를 끊었다 이었다 한다","mis":"SC6-2-u3-X12"}],"explanation":["전선을 따라 흘러요.","길이 돼요.","전지가 전기를 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#4','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C7',1,'mc','auto','반딧불반 탐구 일지 ②에서 라희 모둠이 스위치 대신 쓴 금속 클립으로 불이 켜진 까닭은 어느 것인가요?',ARRAY['SC6-2-u3-X09','SC6-2-u3-X12','SC6-2-u3-X10']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C7","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ②에서 라희 모둠이 스위치 대신 쓴 금속 클립으로 불이 켜진 까닭은 어느 것인가요?","options":[{"t":"금속은 전기가 흐르는 물질이라서","correct":true},{"t":"클립은 전기를 막는 물질이라서","mis":"SC6-2-u3-X09"},{"t":"클립이 전기를 만들어서","mis":"SC6-2-u3-X12"},{"t":"클립이 플라스틱으로 싸여 있어서","mis":"SC6-2-u3-X10"}],"explanation":["금속 클립이에요.","전기가 흘러요.","불이 켜져요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#5','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C10',1,'mc','auto','반딧불반 탐구 일지 ③에서 전동기 바람개비가 더 빨리 돈 회로는 어느 것인가요?',ARRAY['SC6-2-u3-X16']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C10","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ③에서 전동기 바람개비가 더 빨리 돈 회로는 어느 것인가요?","options":[{"t":"전지 두 개를 직렬연결한 회로","correct":true},{"t":"전지 한 개를 이은 회로","mis":"SC6-2-u3-X16"},{"t":"두 회로가 똑같다","mis":"SC6-2-u3-X16"},{"t":"어느 회로도 돌지 않았다","mis":"SC6-2-u3-X16"}],"explanation":["전지 두 개 쪽이에요.","바람개비가 빨라요.","직렬연결이에요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#6','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C14',1,'mc','auto','반딧불반 탐구 일지 ④에서 철 클립이 더 많이 붙은 것은 어느 때인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X19']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C14","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ④에서 철 클립이 더 많이 붙은 것은 어느 때인가요?","options":[{"t":"전지 두 개를 직렬연결했을 때","correct":true},{"t":"전지 한 개를 이었을 때","mis":"SC6-2-u3-X20"},{"t":"스위치를 닫기 전","mis":"SC6-2-u3-X19"},{"t":"두 때가 똑같다","mis":"SC6-2-u3-X20"}],"explanation":["7개가 붙었어요.","전지 두 개예요.","더 세요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#7','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C16',1,'mc','auto','반딧불반이 조사한 물건 가운데 소리의 크기를 조절하는 데 전자석을 쓰는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X28']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"mc","stem":"반딧불반이 조사한 물건 가운데 소리의 크기를 조절하는 데 전자석을 쓰는 것은 어느 것인가요?","options":[{"t":"스피커","correct":true},{"t":"선풍기","mis":"SC6-2-u3-X28"},{"t":"세탁기","mis":"SC6-2-u3-X28"},{"t":"전자석 기중기","mis":"SC6-2-u3-X28"}],"explanation":["소리를 내요.","크기를 조절해요.","스피커예요."],"asset":{"type":"passage","lines":["선풍기·스피커·세탁기·전자석 기중기를 조사해 학급 게시판에 올렸다.","사진 아래에 사진을 가져온 곳을 적었다.","기중기 영상 — 전기를 끊자 매달려 있던 철 덩어리가 내려앉았다.","친구 글에는 새로 안 점을 고운 말로 댓글로 달았다."],"title":"⑤ 전자석 쓰임 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#8','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C20',1,'mc','auto','반딧불반 탐구 일지 ⑥에서 전기를 안전하게 쓰는 모습은 어느 것인가요?',ARRAY['SC6-2-u3-X35','SC6-2-u3-X31','SC6-2-u3-X34']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C20","difficulty":1,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥에서 전기를 안전하게 쓰는 모습은 어느 것인가요?","options":[{"t":"㉤ 안 쓰는 콘센트에 안전 덮개 꽂기","correct":true},{"t":"㉡ 콘센트 하나에 여러 기구 꽂기","mis":"SC6-2-u3-X35"},{"t":"㉠ 전원만 끄고 플러그 꽂아 두기","mis":"SC6-2-u3-X31"},{"t":"플러그를 전선째 잡아당기기","mis":"SC6-2-u3-X34"}],"explanation":["안전 덮개를 꽂았어요.","먼지와 물을 막아요.","안전해요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#9','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C5',2,'mc','auto','반딧불반 탐구 일지 ②의 나래 모둠이 불을 켜려면 어떻게 고쳐야 하나요?',ARRAY['SC6-2-u3-X06','SC6-2-u3-X08','SC6-2-u3-X09']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C5","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ②의 나래 모둠이 불을 켜려면 어떻게 고쳐야 하나요?","options":[{"t":"스위치와 전지 (−)극을 전선으로 잇는다","correct":true},{"t":"전선을 하나 더 빼서 (+)극에만 잇는다","mis":"SC6-2-u3-X06"},{"t":"스위치를 열어 둔다","mis":"SC6-2-u3-X08"},{"t":"전선 대신 고무줄을 잇는다","mis":"SC6-2-u3-X09"}],"explanation":["(−)극 쪽이 빠졌어요.","전선으로 이어요.","끊어진 곳이 없어져요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#10','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C10',2,'mc','auto','반딧불반 탐구 일지 ③의 두 회로를 견줄 때 같게 해야 할 것은 어느 것인가요?',ARRAY['SC6-2-u3-X18','SC6-2-u3-X14']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ③의 두 회로를 견줄 때 같게 해야 할 것은 어느 것인가요?","options":[{"t":"전구·전동기·버저의 종류","correct":true},{"t":"이은 전지의 개수","mis":"SC6-2-u3-X18"},{"t":"아무것도 같게 할 필요 없다","mis":"SC6-2-u3-X18"},{"t":"전지를 잇는 방향만 다르게","mis":"SC6-2-u3-X14"}],"explanation":["전지 개수만 달라요.","나머지는 같아요.","그래야 견줄 수 있어요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#11','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C12',2,'mc','auto','전자석을 만들 때 에나멜선을 감는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X24','SC6-2-u3-X23']::text[],false,'{"seq":11,"concept":"SC6-2-u3-C12","difficulty":2,"kind":"mc","stem":"전자석을 만들 때 에나멜선을 감는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한쪽 방향으로 촘촘히 감는다","correct":true},{"t":"방향을 바꿔 가며 듬성듬성 감는다","mis":"SC6-2-u3-X24"},{"t":"감지 않고 볼트 옆에 둔다","mis":"SC6-2-u3-X23"},{"t":"코팅을 모두 벗긴 뒤 아무렇게나 감는다","mis":"SC6-2-u3-X24"}],"explanation":["한쪽 방향이에요.","촘촘히 감아요.","전자석이 잘 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#12','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C17',2,'mc','auto','선풍기에서 전자석의 성질을 이용해 조절하는 것은 어느 것인가요?',ARRAY['SC6-2-u3-X28']::text[],false,'{"seq":12,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"mc","stem":"선풍기에서 전자석의 성질을 이용해 조절하는 것은 어느 것인가요?","options":[{"t":"바람의 세기","correct":true},{"t":"소리의 크기","mis":"SC6-2-u3-X28"},{"t":"통의 무게","mis":"SC6-2-u3-X28"},{"t":"철 덩어리를 드는 높이","mis":"SC6-2-u3-X28"}],"explanation":["선풍기는 바람이에요.","세기를 조절해요.","바람 세기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#13','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C19',2,'mc','auto','「효율적으로 전기를 쓴다」는 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X32','SC6-2-u3-X31']::text[],false,'{"seq":13,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"mc","stem":"「효율적으로 전기를 쓴다」는 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"낭비되거나 손실되는 전기를 줄여 쓰는 것","correct":true},{"t":"전기를 되도록 많이 쓰는 것","mis":"SC6-2-u3-X33"},{"t":"등급 숫자가 큰 제품을 고르는 것","mis":"SC6-2-u3-X32"},{"t":"전원만 끄고 플러그는 꽂아 두는 것","mis":"SC6-2-u3-X31"}],"explanation":["낭비를 줄여요.","손실을 줄여요.","그것이 효율이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#14','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C21',2,'mc','auto','전기를 안전하게 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X38','SC6-2-u3-X33']::text[],false,'{"seq":14,"concept":"SC6-2-u3-C21","difficulty":2,"kind":"mc","stem":"전기를 안전하게 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"감전 사고와 화재를 막기 위해서","correct":true},{"t":"안전 수칙은 어른만 지키면 되어서","mis":"SC6-2-u3-X38"},{"t":"전기를 더 많이 쓰기 위해서","mis":"SC6-2-u3-X33"},{"t":"전기는 끝없이 있어서","mis":"SC6-2-u3-X38"}],"explanation":["감전을 막아요.","불을 막아요.","모두 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#15','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C23',2,'mc','auto','반딧불반 탐구 일지 ⑦에서 전기 요금이 줄어든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X33','SC6-2-u3-X31','SC6-2-u3-X41']::text[],false,'{"seq":15,"concept":"SC6-2-u3-C23","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑦에서 전기 요금이 줄어든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 가족이 전등 끄기와 플러그 뽑기를 함께 실천했기 때문이다","correct":true},{"t":"냉장고 문을 자주 열었기 때문이다","mis":"SC6-2-u3-X33"},{"t":"플러그를 모두 꽂아 두었기 때문이다","mis":"SC6-2-u3-X31"},{"t":"가족 가운데 한 사람만 실천했기 때문이다","mis":"SC6-2-u3-X41"}],"explanation":["함께 실천했어요.","낭비가 줄었어요.","요금이 줄었어요."],"asset":{"type":"passage","lines":["나의 실천 — 방을 나올 때 전등 끄기","월 ○ · 화 ○ · 수 ○ · 목 × · 금 ○ (목요일은 급히 나가다 잊음)","가족 실천 — 쓰지 않는 기구 플러그 뽑기","이번 달 전기 요금이 줄었다고 엄마가 말씀하셨다."],"title":"⑦ 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#16','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C25',2,'mc','auto','반딧불반 탐구 일지 ⑧에서 찬성 쪽이 든 근거는 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":16,"concept":"SC6-2-u3-C25","difficulty":2,"kind":"mc","stem":"반딧불반 탐구 일지 ⑧에서 찬성 쪽이 든 근거는 어느 것인가요?","options":[{"t":"전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다","correct":true},{"t":"전기를 효율적으로 쓰게 돕는다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기를 쓰지 않는다","mis":"SC6-2-u3-X43"},{"t":"반대 쪽은 말할 자격이 없다","mis":"SC6-2-u3-X44"}],"explanation":["찬성 쪽을 봐요.","걱정을 들었어요.","정전과 화재예요."],"asset":{"type":"passage","lines":["스마트 홈 체험관 — 사람이 없으면 조명이 꺼지고, 날씨에 맞춰 냉난방이 바뀐다.","토론 주제 — 인공지능의 발전 속도를 조절해야 할까?","찬성 — 전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다.","반대 — 전기를 효율적으로 쓰게 도와 사용량 문제를 줄일 수 있다."],"title":"⑧ 스마트 홈 체험과 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#17','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C5',3,'mc','auto','반딧불반 탐구 일지 ②의 네 모둠을 보고 불이 켜지는 회로의 특징을 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u3-X07','SC6-2-u3-X06','SC6-2-u3-X09']::text[],false,'{"seq":17,"concept":"SC6-2-u3-C5","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ②의 네 모둠을 보고 불이 켜지는 회로의 특징을 바르게 정리한 것은 어느 것인가요?","options":[{"t":"전지 (+)극부터 (−)극까지 끊어진 곳 없이, 전기가 흐르는 물질끼리 이어져 있다","correct":true},{"t":"전선 수가 많기만 하면 켜진다","mis":"SC6-2-u3-X07"},{"t":"한쪽 극에만 이어도 금속이면 켜진다","mis":"SC6-2-u3-X06"},{"t":"유리나 고무로 이어도 끊어진 곳만 없으면 켜진다","mis":"SC6-2-u3-X09"}],"explanation":["끊어진 곳이 없어요.","금속끼리 이어요.","두 가지를 다 지켜요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#18','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C10',3,'mc','auto','반딧불반 탐구 일지 ③의 결과를 한 문장으로 정리한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X16','SC6-2-u3-X15']::text[],false,'{"seq":18,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ③의 결과를 한 문장으로 정리한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"전지 두 개를 직렬연결하면 한 개일 때보다 전구는 더 밝고, 전동기는 더 빠르고, 버저는 더 크다","correct":true},{"t":"전지 개수는 부품의 작동과 상관없다","mis":"SC6-2-u3-X16"},{"t":"전지를 더 이으면 모든 부품이 약해진다","mis":"SC6-2-u3-X15"},{"t":"전구만 밝아지고 나머지는 그대로다","mis":"SC6-2-u3-X16"}],"explanation":["세 부품을 봐요.","모두 세졌어요.","한 문장으로 모아요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#19','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C15',3,'mc','auto','전자석의 극을 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X20','SC6-2-u3-X25','SC6-2-u3-X21']::text[],false,'{"seq":19,"concept":"SC6-2-u3-C15","difficulty":3,"kind":"mc","stem":"전자석의 극을 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전자석 양쪽 끝에 나침반을 두고, 바늘이 멈춘 뒤 가리키는 방향을 본다","correct":true},{"t":"전자석에 붙은 철 클립의 개수를 센다","mis":"SC6-2-u3-X20"},{"t":"나침반 바늘이 흔들릴 때 바로 읽는다","mis":"SC6-2-u3-X25"},{"t":"전자석의 극은 바뀌지 않으니 볼 필요가 없다","mis":"SC6-2-u3-X21"}],"explanation":["나침반을 둬요.","멈춘 뒤 봐요.","극을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#20','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C17',3,'mc','auto','기중기를 영구 자석으로 만들었다면 생길 문제로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X29','SC6-2-u3-X22']::text[],false,'{"seq":20,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"mc","stem":"기중기를 영구 자석으로 만들었다면 생길 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"든 철 덩어리를 원하는 곳에 내려놓기 어렵다","correct":true},{"t":"철 덩어리를 더 쉽게 내려놓는다","mis":"SC6-2-u3-X29"},{"t":"전기를 끊으면 철이 떨어진다","mis":"SC6-2-u3-X29"},{"t":"철을 전혀 들 수 없다","mis":"SC6-2-u3-X22"}],"explanation":["영구 자석은 늘 자석이에요.","끊을 수 없어요.","내려놓기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#21','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C19',3,'mc','auto','반딧불반 탐구 일지 ⑥의 ㉠~㉤ 가운데 고쳐야 할 것끼리 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X32','SC6-2-u3-X31','SC6-2-u3-X36']::text[],false,'{"seq":21,"concept":"SC6-2-u3-C19","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ⑥의 ㉠~㉤ 가운데 고쳐야 할 것끼리 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉢, ㉤","mis":"SC6-2-u3-X32"},{"t":"㉠, ㉢","mis":"SC6-2-u3-X31"},{"t":"㉣, ㉤","mis":"SC6-2-u3-X36"}],"explanation":["㉠은 대기 전력이에요.","㉡은 화재 위험이에요.","둘을 고쳐요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#22','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C25',3,'mc','auto','반딧불반 탐구 일지 ⑧의 두 쪽 의견을 정리한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X43','SC6-2-u3-X44']::text[],false,'{"seq":22,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"mc","stem":"반딧불반 탐구 일지 ⑧의 두 쪽 의견을 정리한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인공지능은 전기 사용을 늘릴 수도 있고, 전기를 아끼도록 도울 수도 있다","correct":true},{"t":"인공지능은 전기와 상관이 없다","mis":"SC6-2-u3-X43"},{"t":"찬성 쪽 근거만 옳고 반대 쪽은 근거가 없다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기를 아끼기만 한다","mis":"SC6-2-u3-X43"}],"explanation":["두 쪽을 봐요.","늘리기도 해요.","돕기도 해요."],"asset":{"type":"passage","lines":["스마트 홈 체험관 — 사람이 없으면 조명이 꺼지고, 날씨에 맞춰 냉난방이 바뀐다.","토론 주제 — 인공지능의 발전 속도를 조절해야 할까?","찬성 — 전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다.","반대 — 전기를 효율적으로 쓰게 도와 사용량 문제를 줄일 수 있다."],"title":"⑧ 스마트 홈 체험과 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#23','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C10',4,'mc','auto','전동기 바람개비를 더 빨리 돌리고 전자석도 더 세게 하고 싶어요. 두 가지에 함께 쓸 수 있는 방법은 어느 것인가요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X16','SC6-2-u3-X21']::text[],false,'{"seq":23,"concept":"SC6-2-u3-C10","difficulty":4,"kind":"mc","stem":"전동기 바람개비를 더 빨리 돌리고 전자석도 더 세게 하고 싶어요. 두 가지에 함께 쓸 수 있는 방법은 어느 것인가요?","options":[{"t":"같은 전지를 하나 더 직렬연결한다","correct":true},{"t":"전지를 (+)극끼리 맞대어 잇는다","mis":"SC6-2-u3-X14"},{"t":"전지를 하나 뺀다","mis":"SC6-2-u3-X16"},{"t":"전지 방향만 반대로 바꾼다","mis":"SC6-2-u3-X21"}],"explanation":["전지를 더 이어요.","직렬로 이어요.","둘 다 세져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#24','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C21',4,'mc','auto','전기를 효율적이고 안전하게 사용하는 방법을 반 친구들에게 알리는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X35','SC6-2-u3-X38']::text[],false,'{"seq":24,"concept":"SC6-2-u3-C21","difficulty":4,"kind":"mc","stem":"전기를 효율적이고 안전하게 사용하는 방법을 반 친구들에게 알리는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생활 속 장면으로 역할놀이를 꾸미되, 실제 전기 기구 대신 모형 소품을 쓴다","correct":true},{"t":"실제 콘센트에 플러그를 여러 개 꽂아 보여 준다","mis":"SC6-2-u3-X35"},{"t":"감전 사고 장면을 무섭게 보여 준다","mis":"SC6-2-u3-X38"},{"t":"전기는 끝없으니 아낄 필요 없다고 알린다","mis":"SC6-2-u3-X38"}],"explanation":["생활 장면이에요.","모형 소품을 써요.","안전하게 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_b#25','sci',6,2,'u3','','g6_2_sci_u3_review_b','unit_review','SC6-2-u3-C26',4,'mc','auto','이 단원에서 배운 내용을 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X19','SC6-2-u3-X45']::text[],false,'{"seq":25,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 내용을 바르게 정리한 것은 어느 것인가요?","options":[{"t":"끊어진 곳 없이 금속끼리 이으면 불이 켜지고, 전지를 직렬로 더 이으면 더 세지며, 전자석은 세기와 극을 바꿀 수 있고, 전기는 효율적이고 안전하게 써야 한다","correct":true},{"t":"전지를 (+)극끼리 이으면 직렬연결이 되어 전구가 더 밝아진다","mis":"SC6-2-u3-X14"},{"t":"전자석은 전기가 없어도 늘 자석이라 기중기에 쓴다","mis":"SC6-2-u3-X19"},{"t":"전기는 아끼기만 하면 안전은 신경 쓰지 않아도 된다","mis":"SC6-2-u3-X45"}],"explanation":["회로를 떠올려요.","전자석을 떠올려요.","효율과 안전도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#1','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C3',1,'ox','auto','줄 전구 세트는 전지가 없어도 전원만 켜면 빛나요.',ARRAY['SC6-2-u3-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u3-C3","difficulty":1,"kind":"ox","stem":"줄 전구 세트는 전지가 없어도 전원만 켜면 빛나요.","answer":"X","reason_options":[{"t":"전기를 주는 전지가 있어야 불이 켜지기 때문에","correct":true},{"t":"전원 버튼 안에 빛이 들어 있기 때문에","mis":"SC6-2-u3-X01"}],"mis":"SC6-2-u3-X01","explanation":["전원만 켰어요.","전지가 없어요.","켜지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#2','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C2',1,'mc','auto','빛나는 작품을 감상할 때 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u3-X05','SC6-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":1,"kind":"mc","stem":"빛나는 작품을 감상할 때 알맞은 말은 어느 것인가요?","options":[{"t":"「반딧불이 자리에 줄 전구를 붙인 생각이 멋져.」","correct":true},{"t":"「전구가 적어서 별로야.」","mis":"SC6-2-u3-X05"},{"t":"「내 작품만 잘 만들었어.」","mis":"SC6-2-u3-X05"},{"t":"「손에 물 묻혀서 만져 봐도 돼?」","mis":"SC6-2-u3-X04"}],"explanation":["잘된 점을 말해요.","줄 전구 자리를 봐요.","칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#3','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C5',1,'ox','auto','전구에 불이 켜지려면 전기 부품이 전지의 (+)극부터 (−)극까지 끊어진 곳 없이 이어져야 해요.',ARRAY['SC6-2-u3-X06']::text[],false,'{"seq":3,"concept":"SC6-2-u3-C5","difficulty":1,"kind":"ox","stem":"전구에 불이 켜지려면 전기 부품이 전지의 (+)극부터 (−)극까지 끊어진 곳 없이 이어져야 해요.","answer":"O","reason_options":[{"t":"끊어진 곳 없이 이어져야 전기가 흐르기 때문에","correct":true},{"t":"한쪽 극에만 이어도 전기가 흐르기 때문에","mis":"SC6-2-u3-X06"}],"mis":"SC6-2-u3-X06","explanation":["두 극까지 이어요.","끊어진 곳이 없어요.","불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#4','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C7',1,'ox','auto','고무 막대를 스위치 자리에 이으면 전구에 불이 켜져요.',ARRAY['SC6-2-u3-X09']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C7","difficulty":1,"kind":"ox","stem":"고무 막대를 스위치 자리에 이으면 전구에 불이 켜져요.","answer":"X","reason_options":[{"t":"고무는 전기가 잘 흐르지 않는 물질이기 때문에","correct":true},{"t":"고무는 금속보다 전기가 더 잘 흐르기 때문에","mis":"SC6-2-u3-X09"}],"mis":"SC6-2-u3-X09","explanation":["고무 막대예요.","전기가 잘 안 흘러요.","켜지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#5','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C9',1,'ox','auto','직렬연결은 한 전지의 (+)극을 다른 전지의 (−)극에 잇는 방법이에요.',ARRAY['SC6-2-u3-X14']::text[],false,'{"seq":5,"concept":"SC6-2-u3-C9","difficulty":1,"kind":"ox","stem":"직렬연결은 한 전지의 (+)극을 다른 전지의 (−)극에 잇는 방법이에요.","answer":"O","reason_options":[{"t":"서로 다른 극을 이어 전지를 한 줄로 잇기 때문에","correct":true},{"t":"같은 극끼리 맞대어 잇기 때문에","mis":"SC6-2-u3-X14"}],"mis":"SC6-2-u3-X14","explanation":["(+)극과 (−)극이에요.","서로 달라요.","직렬연결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#6','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C13',1,'ox','auto','전자석은 전기가 흐를 때만 자석의 성질을 나타내요.',ARRAY['SC6-2-u3-X19']::text[],false,'{"seq":6,"concept":"SC6-2-u3-C13","difficulty":1,"kind":"ox","stem":"전자석은 전기가 흐를 때만 자석의 성질을 나타내요.","answer":"O","reason_options":[{"t":"스위치를 닫아 전기가 흐를 때만 철을 끌어당기기 때문에","correct":true},{"t":"전기가 없어도 늘 철을 끌어당기기 때문에","mis":"SC6-2-u3-X19"}],"mis":"SC6-2-u3-X19","explanation":["전기가 흘러요.","그때만 자석이에요.","전자석의 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#7','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C16',1,'ox','auto','세탁기는 전자석을 이용해 빨래 통을 돌려요.',ARRAY['SC6-2-u3-X27']::text[],false,'{"seq":7,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"ox","stem":"세탁기는 전자석을 이용해 빨래 통을 돌려요.","answer":"O","reason_options":[{"t":"세탁기 안의 전자석을 쓴 장치가 통을 돌리기 때문에","correct":true},{"t":"세탁기는 전기 없이 영구 자석으로만 통을 돌리기 때문에","mis":"SC6-2-u3-X27"}],"mis":"SC6-2-u3-X27","explanation":["세탁기예요.","통이 돌아요.","전자석을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#8','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C20',1,'ox','auto','플러그를 뽑을 때는 전선을 잡고 당겨요.',ARRAY['SC6-2-u3-X34']::text[],false,'{"seq":8,"concept":"SC6-2-u3-C20","difficulty":1,"kind":"ox","stem":"플러그를 뽑을 때는 전선을 잡고 당겨요.","answer":"X","reason_options":[{"t":"플러그의 머리 부분을 잡고 뽑아야 안전하기 때문에","correct":true},{"t":"전선을 당겨야 플러그가 덜 상하기 때문에","mis":"SC6-2-u3-X34"}],"mis":"SC6-2-u3-X34","explanation":["전선을 당기지 않아요.","머리 부분을 잡아요.","안전하게 뽑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#9','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C6',2,'ox','auto','손전등 스위치를 누르면 안에서 끊어져 있던 곳이 이어져 불이 켜져요.',ARRAY['SC6-2-u3-X08']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C6","difficulty":2,"kind":"ox","stem":"손전등 스위치를 누르면 안에서 끊어져 있던 곳이 이어져 불이 켜져요.","answer":"O","reason_options":[{"t":"스위치가 회로를 이어 전기가 흐르게 하기 때문에","correct":true},{"t":"스위치를 누르면 회로가 끊어져야 불이 켜지기 때문에","mis":"SC6-2-u3-X08"}],"mis":"SC6-2-u3-X08","explanation":["스위치를 눌러요.","끊어진 곳이 이어져요.","불이 켜져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#10','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C10',2,'ox','auto','직렬로 이은 전지가 많을수록 전동기 날개가 더 빠르게 돌아요.',ARRAY['SC6-2-u3-X16']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"ox","stem":"직렬로 이은 전지가 많을수록 전동기 날개가 더 빠르게 돌아요.","answer":"O","reason_options":[{"t":"전지 두 개를 직렬연결하면 한 개일 때보다 날개가 더 빨리 돌기 때문에","correct":true},{"t":"전지가 많을수록 날개가 느려지기 때문에","mis":"SC6-2-u3-X16"}],"mis":"SC6-2-u3-X16","explanation":["전지가 많아요.","직렬로 이었어요.","더 빨리 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#11','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C12',2,'ox','auto','에나멜선 끝을 사포로 문질러 코팅을 벗긴 부분을 회로에 이어요.',ARRAY['SC6-2-u3-X23']::text[],false,'{"seq":11,"concept":"SC6-2-u3-C12","difficulty":2,"kind":"ox","stem":"에나멜선 끝을 사포로 문질러 코팅을 벗긴 부분을 회로에 이어요.","answer":"O","reason_options":[{"t":"코팅된 부분은 전기가 잘 흐르지 않기 때문에","correct":true},{"t":"코팅이 있어야 전기가 잘 흐르기 때문에","mis":"SC6-2-u3-X23"}],"mis":"SC6-2-u3-X23","explanation":["코팅은 막아요.","벗겨서 이어요.","전기가 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#12','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C18',2,'ox','auto','친구가 올린 조사 글에는 새로 안 점을 고운 말로 댓글로 달아요.',ARRAY['SC6-2-u3-X30']::text[],false,'{"seq":12,"concept":"SC6-2-u3-C18","difficulty":2,"kind":"ox","stem":"친구가 올린 조사 글에는 새로 안 점을 고운 말로 댓글로 달아요.","answer":"O","reason_options":[{"t":"바르고 고운 말로 나누어야 서로 존중하며 배울 수 있기 때문에","correct":true},{"t":"댓글은 짧고 거칠게 써야 잘 읽히기 때문에","mis":"SC6-2-u3-X30"}],"mis":"SC6-2-u3-X30","explanation":["새로 안 점을 써요.","고운 말로 써요.","서로 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#13','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C19',2,'ox','auto','형광등 대신 LED등을 쓰면 전기를 효율적으로 쓸 수 있어요.',ARRAY['SC6-2-u3-X33']::text[],false,'{"seq":13,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"ox","stem":"형광등 대신 LED등을 쓰면 전기를 효율적으로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"LED등은 에너지 효율이 높아 전기를 덜 쓰기 때문에","correct":true},{"t":"LED등이 전기를 더 많이 쓰기 때문에","mis":"SC6-2-u3-X33"}],"mis":"SC6-2-u3-X33","explanation":["LED등이에요.","효율이 높아요.","전기를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#14','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C20',2,'ox','auto','반딧불반 탐구 일지 ⑥의 ㉣처럼 젖은 손으로 플러그를 꽂으려다 멈춘 것은 잘한 일이에요.',ARRAY['SC6-2-u3-X36']::text[],false,'{"seq":14,"concept":"SC6-2-u3-C20","difficulty":2,"kind":"ox","stem":"반딧불반 탐구 일지 ⑥의 ㉣처럼 젖은 손으로 플러그를 꽂으려다 멈춘 것은 잘한 일이에요.","answer":"O","reason_options":[{"t":"젖은 손으로 전기 기구를 만지면 감전될 수 있기 때문에","correct":true},{"t":"젖은 손이 전기를 더 잘 막아 주기 때문에","mis":"SC6-2-u3-X36"}],"mis":"SC6-2-u3-X36","explanation":["손이 젖었어요.","감전될 수 있어요.","닦고 꽂아요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#15','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C22',2,'ox','auto','「전기를 열심히 아끼자.」는 구체적인 실천 계획이에요.',ARRAY['SC6-2-u3-X39']::text[],false,'{"seq":15,"concept":"SC6-2-u3-C22","difficulty":2,"kind":"ox","stem":"「전기를 열심히 아끼자.」는 구체적인 실천 계획이에요.","answer":"X","reason_options":[{"t":"무엇을 언제 할지 정해야 구체적인 계획이기 때문에","correct":true},{"t":"막연할수록 지키기 쉬운 계획이기 때문에","mis":"SC6-2-u3-X39"}],"mis":"SC6-2-u3-X39","explanation":["막연해요.","무엇을 할지 정해요.","구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#16','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C24',2,'ox','auto','스마트 홈 기술이 있으면 우리가 전기를 아끼는 습관은 필요 없어요.',ARRAY['SC6-2-u3-X42']::text[],false,'{"seq":16,"concept":"SC6-2-u3-C24","difficulty":2,"kind":"ox","stem":"스마트 홈 기술이 있으면 우리가 전기를 아끼는 습관은 필요 없어요.","answer":"X","reason_options":[{"t":"기술이 돕더라도 사람의 실천이 함께해야 낭비가 줄기 때문에","correct":true},{"t":"기술이 모든 낭비를 저절로 없애기 때문에","mis":"SC6-2-u3-X42"}],"mis":"SC6-2-u3-X42","explanation":["기술은 도와요.","실천도 필요해요.","함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#17','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C8',3,'ox','auto','전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 아랫면에서 이어져 있어요.',ARRAY['SC6-2-u3-X11']::text[],false,'{"seq":17,"concept":"SC6-2-u3-C8","difficulty":3,"kind":"ox","stem":"전구 끼우개는 전선을 거는 금속 막대와 전구를 끼우는 부분이 아랫면에서 이어져 있어요.","answer":"O","reason_options":[{"t":"그래서 금속 막대에 전선을 물리면 전구까지 전기가 흐르기 때문에","correct":true},{"t":"두 부분이 끊어져 있어 전구에 직접 물려야 하기 때문에","mis":"SC6-2-u3-X11"}],"mis":"SC6-2-u3-X11","explanation":["아랫면을 봐요.","전선으로 이어져 있어요.","금속 막대에 물려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#18','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C10',3,'ox','auto','전지 개수에 따른 전구 밝기를 견줄 때 회로마다 다른 전구를 써도 돼요.',ARRAY['SC6-2-u3-X18']::text[],false,'{"seq":18,"concept":"SC6-2-u3-C10","difficulty":3,"kind":"ox","stem":"전지 개수에 따른 전구 밝기를 견줄 때 회로마다 다른 전구를 써도 돼요.","answer":"X","reason_options":[{"t":"전지 개수 말고 다른 것까지 바꾸면 무엇 때문에 달라졌는지 알 수 없기 때문에","correct":true},{"t":"전구는 종류와 상관없이 늘 같은 밝기라서","mis":"SC6-2-u3-X18"}],"mis":"SC6-2-u3-X18","explanation":["전지 개수만 달라요.","전구는 같게 해요.","그래야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#19','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C13',3,'ox','auto','반딧불반 탐구 일지 ④처럼 스위치는 잴 때만 잠깐씩 닫는 것이 좋아요.',ARRAY['SC6-2-u3-X26']::text[],false,'{"seq":19,"concept":"SC6-2-u3-C13","difficulty":3,"kind":"ox","stem":"반딧불반 탐구 일지 ④처럼 스위치는 잴 때만 잠깐씩 닫는 것이 좋아요.","answer":"O","reason_options":[{"t":"오래 닫아 두면 전자석이 뜨거워지기 때문에","correct":true},{"t":"오래 닫아 둘수록 전자석이 식기 때문에","mis":"SC6-2-u3-X26"}],"mis":"SC6-2-u3-X26","explanation":["오래 닫으면 뜨거워요.","잠깐씩 닫아요.","안전해요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#20','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C17',3,'ox','auto','선풍기의 바람 세기와 스피커의 소리 크기를 바꿀 수 있는 것은 전자석의 세기를 조절할 수 있기 때문이에요.',ARRAY['SC6-2-u3-X20']::text[],false,'{"seq":20,"concept":"SC6-2-u3-C17","difficulty":3,"kind":"ox","stem":"선풍기의 바람 세기와 스피커의 소리 크기를 바꿀 수 있는 것은 전자석의 세기를 조절할 수 있기 때문이에요.","answer":"O","reason_options":[{"t":"전자석은 세기를 조절할 수 있는 성질이 있기 때문에","correct":true},{"t":"전자석은 늘 같은 세기만 내기 때문에","mis":"SC6-2-u3-X20"}],"mis":"SC6-2-u3-X20","explanation":["세기를 조절해요.","바람과 소리가 달라져요.","전자석 덕분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#21','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C19',3,'ox','auto','냉장고 문을 자주 여닫지 않는 것도 전기를 효율적으로 쓰는 방법이에요.',ARRAY['SC6-2-u3-X33']::text[],false,'{"seq":21,"concept":"SC6-2-u3-C19","difficulty":3,"kind":"ox","stem":"냉장고 문을 자주 여닫지 않는 것도 전기를 효율적으로 쓰는 방법이에요.","answer":"O","reason_options":[{"t":"문을 자주 열면 전기가 더 들어 낭비되기 때문에","correct":true},{"t":"문을 자주 열수록 전기가 덜 들기 때문에","mis":"SC6-2-u3-X33"}],"mis":"SC6-2-u3-X33","explanation":["문을 자주 열어요.","전기가 더 들어요.","덜 여닫아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#22','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C25',3,'ox','auto','토론에서 반대 쪽은 「인공지능이 전기를 효율적으로 쓰게 돕는다」를 근거로 들 수 있어요.',ARRAY['SC6-2-u3-X43']::text[],false,'{"seq":22,"concept":"SC6-2-u3-C25","difficulty":3,"kind":"ox","stem":"토론에서 반대 쪽은 「인공지능이 전기를 효율적으로 쓰게 돕는다」를 근거로 들 수 있어요.","answer":"O","reason_options":[{"t":"인공지능이 냉난방과 조명을 알맞게 맞춰 전기를 아끼게 하기 때문에","correct":true},{"t":"인공지능은 전기와 아무 상관이 없기 때문에","mis":"SC6-2-u3-X43"}],"mis":"SC6-2-u3-X43","explanation":["반대 쪽이에요.","효율을 도와요.","근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#23','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C14',4,'essay','teacher','반딧불반 탐구 일지 ④를 보고 전자석의 성질 두 가지를 영구 자석과 견주어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-2-u3-C14","difficulty":4,"kind":"essay","stem":"반딧불반 탐구 일지 ④를 보고 전자석의 성질 두 가지를 영구 자석과 견주어 쓰세요.","answer_guide":{"answer":"예: 영구 자석은 세기가 일정하지만 전자석은 직렬로 이은 전지가 많을수록 세진다. 영구 자석은 극이 일정하지만 전자석은 전지 방향을 바꾸면 극이 반대로 바뀐다.","scoring_points":["세기를 견주어 썼는가","극을 견주어 썼는가","기록(철 클립 수·나침반)과 이어 썼는가"]},"explanation":["세기를 견줘요.","극을 견줘요.","기록과 이어요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#24','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C26',4,'essay','teacher','반딧불반 탐구 일지 ⑥의 ㉠~㉤ 가운데 고쳐야 할 것 두 가지를 골라 어떻게 고칠지 쓰고, 하나는 효율과 하나는 안전과 이어 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"essay","stem":"반딧불반 탐구 일지 ⑥의 ㉠~㉤ 가운데 고쳐야 할 것 두 가지를 골라 어떻게 고칠지 쓰고, 하나는 효율과 하나는 안전과 이어 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠ — 텔레비전을 보지 않을 때 플러그를 뽑는다(대기 전력을 줄여 전기를 효율적으로 쓴다). ㉡ — 기구를 여러 콘센트에 나누어 꽂는다(한 콘센트에 몰아 꽂으면 불이 날 수 있어 안전하지 않다).","scoring_points":["고칠 것 두 가지를 바르게 골랐는가","고치는 방법을 썼는가","효율과 안전의 까닭을 나누어 썼는가"]},"explanation":["㉠과 ㉡이에요.","고치는 방법을 써요.","효율과 안전을 이어요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_c#25','sci',6,2,'u3','','g6_2_sci_u3_review_c','unit_review','SC6-2-u3-C24',4,'mc','auto','스마트 홈 기술과 우리의 실천을 함께 쓰는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X42','SC6-2-u3-X31']::text[],false,'{"seq":25,"concept":"SC6-2-u3-C24","difficulty":4,"kind":"mc","stem":"스마트 홈 기술과 우리의 실천을 함께 쓰는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조명은 사람이 없으면 알아서 꺼지게 하고, 우리는 쓰지 않는 기구의 플러그를 뽑는 습관을 이어 간다","correct":true},{"t":"기술이 다 해 주니 실천은 그만둔다","mis":"SC6-2-u3-X42"},{"t":"조명을 늘 켜 두고 기술이 끄기만 기다린다","mis":"SC6-2-u3-X42"},{"t":"플러그는 꽂아 둬도 전기가 안 드니 그대로 둔다","mis":"SC6-2-u3-X31"}],"explanation":["기술이 도와요.","습관도 이어 가요.","함께해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#1','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C1',1,'sa','auto','반딧불반 탐구 일지 ①에서 줄 전구 세트를 도화지에 붙일 때 쓴 준비물은 무엇인가요? 여섯 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u3-C1","difficulty":1,"kind":"sa","stem":"반딧불반 탐구 일지 ①에서 줄 전구 세트를 도화지에 붙일 때 쓴 준비물은 무엇인가요? 여섯 글자로 쓰세요.","answer":["셀로판테이프"],"explanation":["붙이는 데 썼어요.","여섯 글자예요.","셀로판테이프예요."],"asset":{"type":"passage","lines":["우리 반은 줄 전구 세트로 「반딧불 숲」 작품을 만들었다.","먼저 숲 그림을 그리고, 줄 전구를 앞면에 셀로판테이프로 붙였다.","해솔이 작품은 전원을 켜도 꺼져 있었는데, 전지를 넣으니 켜졌다.","감상할 때 반딧불이 자리에 줄 전구를 쓴 점을 서로 칭찬했다."],"title":"① 빛나는 작품 전시회"},"mis":"SC6-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#2','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C2',1,'mc','auto','줄 전구 세트를 만지기 전에 꼭 해야 할 일은 어느 것인가요?',ARRAY['SC6-2-u3-X04','SC6-2-u3-X05']::text[],false,'{"seq":2,"concept":"SC6-2-u3-C2","difficulty":1,"kind":"mc","stem":"줄 전구 세트를 만지기 전에 꼭 해야 할 일은 어느 것인가요?","options":[{"t":"손의 물기를 닦는다","correct":true},{"t":"손에 물을 묻힌다","mis":"SC6-2-u3-X04"},{"t":"물병을 작품 옆에 둔다","mis":"SC6-2-u3-X04"},{"t":"친구 작품의 흠부터 찾는다","mis":"SC6-2-u3-X05"}],"explanation":["물기를 닦아요.","마른 손으로 해요.","안전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#3','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C5',1,'sa','auto','반딧불반 탐구 일지 ②에서 전선이 빠져 불이 켜지지 않은 모둠은 어느 모둠인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC6-2-u3-C5","difficulty":1,"kind":"sa","stem":"반딧불반 탐구 일지 ②에서 전선이 빠져 불이 켜지지 않은 모둠은 어느 모둠인가요? 두 글자로 쓰세요.","answer":["나래"],"explanation":["전선이 빠졌어요.","두 글자예요.","나래 모둠이에요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"},"mis":"SC6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#4','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C8',1,'mc','auto','스위치에서 전선을 이어야 하는 부분은 어느 것인가요?',ARRAY['SC6-2-u3-X10','SC6-2-u3-X13']::text[],false,'{"seq":4,"concept":"SC6-2-u3-C8","difficulty":1,"kind":"mc","stem":"스위치에서 전선을 이어야 하는 부분은 어느 것인가요?","options":[{"t":"금속으로 된 이음 부분","correct":true},{"t":"플라스틱 몸체","mis":"SC6-2-u3-X10"},{"t":"어느 부분이나 같다","mis":"SC6-2-u3-X10"},{"t":"스위치를 감싼 비닐","mis":"SC6-2-u3-X13"}],"explanation":["금속 부분이에요.","전기가 흘러요.","거기에 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#5','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C10',1,'sa','auto','전지 두 개를 직렬연결하면 전지 한 개일 때보다 버저 소리가 어떻게 되나요? 「더 ○○」의 ○○를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u3-C10","difficulty":1,"kind":"sa","stem":"전지 두 개를 직렬연결하면 전지 한 개일 때보다 버저 소리가 어떻게 되나요? 「더 ○○」의 ○○를 두 글자로 쓰세요.","answer":["크게","커요"],"explanation":["버저 소리예요.","전지가 늘었어요.","더 크게 나요."],"mis":"SC6-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#6','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C14',1,'sa','auto','반딧불반 탐구 일지 ④에서 전지 두 개를 직렬연결했을 때 붙은 철 클립은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u3-C14","difficulty":1,"kind":"sa","stem":"반딧불반 탐구 일지 ④에서 전지 두 개를 직렬연결했을 때 붙은 철 클립은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["기록을 봐요.","두 개일 때예요.","7개예요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"},"mis":"SC6-2-u3-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#7','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C16',1,'sa','auto','전기가 흐를 때만 자석이 되어 무거운 철 물체를 들어 옮기는 기계를 「전자석 ○○○」라고 해요. ○○○를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u3-C16","difficulty":1,"kind":"sa","stem":"전기가 흐를 때만 자석이 되어 무거운 철 물체를 들어 옮기는 기계를 「전자석 ○○○」라고 해요. ○○○를 세 글자로 쓰세요.","answer":["기중기"],"explanation":["무거운 철을 옮겨요.","세 글자예요.","기중기예요."],"mis":"SC6-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#8','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C19',1,'sa','auto','에너지 소비 효율 등급은 몇 등급에 가까울수록 효율이 높은가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC6-2-u3-C19","difficulty":1,"kind":"sa","stem":"에너지 소비 효율 등급은 몇 등급에 가까울수록 효율이 높은가요? 숫자로 쓰세요.","answer":["1"],"explanation":["등급 표시를 봐요.","숫자가 작을수록이에요.","1등급이에요."],"mis":"SC6-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#9','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C5',2,'error','auto','반딧불반 탐구 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X06','SC6-2-u3-X07','SC6-2-u3-X09']::text[],false,'{"seq":9,"concept":"SC6-2-u3-C5","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보람 — 「나래 모둠은 전선이 빠져도 (+)극에 이어졌으니 켜졌어야 해.」","correct":true,"mis_target":"SC6-2-u3-X06"},{"t":"은솔 — 「가람 모둠은 끊어진 곳 없이 이었어.」","mis":"SC6-2-u3-X07"},{"t":"하진 — 「라희 모둠은 금속 클립이라 켜졌어.」","mis":"SC6-2-u3-X09"}],"explanation":["(−)극까지 이어야 해요.","나래 모둠은 끊어졌어요.","보람의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["가람 모둠 — 전지 (+)극·전구·스위치·전지 (−)극을 모두 이음 → 켜짐","나래 모둠 — 스위치에서 전지 (−)극으로 가는 전선이 빠짐 → 꺼짐","다온 모둠 — 집게를 전구의 유리 부분에 물림 → 꺼짐","라희 모둠 — 스위치 자리에 금속 클립을 이음 → 켜짐"],"title":"② 전기 회로 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#10','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C10',2,'error','auto','반딧불반 탐구 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X15','SC6-2-u3-X17','SC6-2-u3-X16']::text[],false,'{"seq":10,"concept":"SC6-2-u3-C10","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태건 — 「전지를 하나 더 이으니 전구가 오히려 어두워졌어.」","correct":true,"mis_target":"SC6-2-u3-X15"},{"t":"미소 — 「버저 전선을 바꾸니 소리가 났어.」","mis":"SC6-2-u3-X17"},{"t":"강우 — 「두 개 쪽 바람개비가 더 빨랐어.」","mis":"SC6-2-u3-X16"}],"explanation":["전구는 더 밝았어요.","전지가 늘었어요.","태건의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#11','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C15',2,'error','auto','반딧불반 탐구 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X25','SC6-2-u3-X26','SC6-2-u3-X21']::text[],false,'{"seq":11,"concept":"SC6-2-u3-C15","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「나침반 바늘이 흔들릴 때 바로 극을 적으면 돼.」","correct":true,"mis_target":"SC6-2-u3-X25"},{"t":"로아 — 「스위치는 잴 때만 잠깐 닫았어.」","mis":"SC6-2-u3-X26"},{"t":"지성 — 「전지 방향을 바꾸니 극이 바뀌었어.」","mis":"SC6-2-u3-X21"}],"explanation":["바늘이 멈춰야 해요.","그다음 읽어요.","하율의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["스위치를 닫기 전에는 전자석에 철 클립이 붙지 않았다.","전지 한 개 — 철 클립 3개 · 전지 두 개 직렬연결 — 철 클립 7개","전지 방향을 바꾸니 전자석 끝 나침반 바늘이 반대쪽을 가리켰다.","스위치는 잴 때만 잠깐씩 닫았다."],"title":"④ 전자석 만들어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#12','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C17',2,'error','auto','반딧불반 탐구 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X28','SC6-2-u3-X29']::text[],false,'{"seq":12,"concept":"SC6-2-u3-C17","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세준 — 「스피커의 전자석은 빨래 통을 돌려.」","correct":true,"mis_target":"SC6-2-u3-X28"},{"t":"다인 — 「기중기는 전기를 끊으면 철을 내려놓아.」","mis":"SC6-2-u3-X29"},{"t":"윤슬 — 「선풍기는 전자석으로 바람 세기를 바꿔.」","mis":"SC6-2-u3-X28"}],"explanation":["스피커는 소리예요.","통을 돌리는 건 세탁기예요.","세준의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["선풍기·스피커·세탁기·전자석 기중기를 조사해 학급 게시판에 올렸다.","사진 아래에 사진을 가져온 곳을 적었다.","기중기 영상 — 전기를 끊자 매달려 있던 철 덩어리가 내려앉았다.","친구 글에는 새로 안 점을 고운 말로 댓글로 달았다."],"title":"⑤ 전자석 쓰임 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#13','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C19',2,'error','auto','반딧불반 탐구 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X31','SC6-2-u3-X32','SC6-2-u3-X35']::text[],false,'{"seq":13,"concept":"SC6-2-u3-C19","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수민 — 「㉠ 텔레비전은 전원을 껐으니 전기가 하나도 안 들어.」","correct":true,"mis_target":"SC6-2-u3-X31"},{"t":"도현 — 「㉢ 냉장고는 1등급이라 효율이 높아.」","mis":"SC6-2-u3-X32"},{"t":"아린 — 「㉡ 콘센트는 나누어 꽂아야 해.」","mis":"SC6-2-u3-X35"}],"explanation":["플러그가 꽂혀 있어요.","대기 전력이 들어요.","수민의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["㉠ 거실 텔레비전은 전원만 끄고 플러그를 꽂아 두었다.","㉡ 부엌 콘센트 하나에 전기 주전자·밥솥·전자레인지를 함께 꽂았다.","㉢ 새로 산 냉장고에는 1등급 표시가 붙어 있었다.","㉣ 목욕 뒤 젖은 손으로 머리 말리개를 꽂으려다 멈추었다.","㉤ 안 쓰는 콘센트에 안전 덮개를 꽂았다."],"title":"⑥ 우리 집 전기 점검"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#14','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C21',2,'error','auto','전기를 효율적이고 안전하게 써야 하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X38','SC6-2-u3-X33','SC6-2-u3-X37']::text[],false,'{"seq":14,"concept":"SC6-2-u3-C21","difficulty":2,"kind":"error","stem":"전기를 효율적이고 안전하게 써야 하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「전기는 끝없이 만들 수 있으니 아낄 까닭이 없어.」","correct":true,"mis_target":"SC6-2-u3-X38"},{"t":"채린 — 「아끼면 자원 낭비가 줄고 환경을 지켜.」","mis":"SC6-2-u3-X33"},{"t":"주하 — 「안전하게 써야 화재를 막아.」","mis":"SC6-2-u3-X37"}],"explanation":["전기를 아껴야 해요.","자원과 환경을 지켜요.","예준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#15','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C23',2,'error','auto','반딧불반 탐구 일지 ⑦을 발표하자 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X41','SC6-2-u3-X40']::text[],false,'{"seq":15,"concept":"SC6-2-u3-C23","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ⑦을 발표하자 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정민 — 「목요일에 잊었으면 실천했다고 하면 안 되지.」","correct":true,"mis_target":"SC6-2-u3-X41"},{"t":"하랑 — 「가족과 함께해서 요금이 줄었구나.」","mis":"SC6-2-u3-X41"},{"t":"소이 — 「잊은 까닭까지 적은 점이 좋아.」","mis":"SC6-2-u3-X40"}],"explanation":["깎아내렸어요.","잘한 점을 찾아요.","정민의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["나의 실천 — 방을 나올 때 전등 끄기","월 ○ · 화 ○ · 수 ○ · 목 × · 금 ○ (목요일은 급히 나가다 잊음)","가족 실천 — 쓰지 않는 기구 플러그 뽑기","이번 달 전기 요금이 줄었다고 엄마가 말씀하셨다."],"title":"⑦ 실천 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#16','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C25',2,'error','auto','반딧불반 탐구 일지 ⑧의 토론을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":16,"concept":"SC6-2-u3-C25","difficulty":2,"kind":"error","stem":"반딧불반 탐구 일지 ⑧의 토론을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유찬 — 「근거는 필요 없어. 큰 소리로 말한 쪽이 이겨.」","correct":true,"mis_target":"SC6-2-u3-X44"},{"t":"서하 — 「반대 쪽은 효율을 돕는다는 근거를 들었어.」","mis":"SC6-2-u3-X43"},{"t":"나윤 — 「찬성 쪽은 정전 걱정을 근거로 들었어.」","mis":"SC6-2-u3-X43"}],"explanation":["근거가 필요해요.","근거로 설득해요.","유찬의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["스마트 홈 체험관 — 사람이 없으면 조명이 꺼지고, 날씨에 맞춰 냉난방이 바뀐다.","토론 주제 — 인공지능의 발전 속도를 조절해야 할까?","찬성 — 전기 사용량이 크게 늘어 정전이나 화재가 날 수 있다.","반대 — 전기를 효율적으로 쓰게 도와 사용량 문제를 줄일 수 있다."],"title":"⑧ 스마트 홈 체험과 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#17','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C7',3,'error','auto','전기 부품을 이루는 물질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X13','SC6-2-u3-X10','SC6-2-u3-X09']::text[],false,'{"seq":17,"concept":"SC6-2-u3-C7","difficulty":3,"kind":"error","stem":"전기 부품을 이루는 물질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"선우 — 「전지 칸의 비닐은 전기가 잘 흐르라고 끼워 둔 거야.」","correct":true,"mis_target":"SC6-2-u3-X13"},{"t":"예나 — 「스위치 몸체는 플라스틱, 이음 부분은 금속이야.」","mis":"SC6-2-u3-X10"},{"t":"우진 — 「고무 막대를 이으면 불이 안 켜져.」","mis":"SC6-2-u3-X09"}],"explanation":["비닐은 전기를 막아요.","전지가 닳지 않게 해요.","선우의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#18','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C9',3,'error','auto','전지 두 개를 이은 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X16']::text[],false,'{"seq":18,"concept":"SC6-2-u3-C9","difficulty":3,"kind":"error","stem":"전지 두 개를 이은 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하민 — 「(−)극끼리 맞대었으니 직렬연결이야.」","correct":true,"mis_target":"SC6-2-u3-X14"},{"t":"수호 — 「한 전지 (+)극에 다른 전지 (−)극을 이었어.」","mis":"SC6-2-u3-X14"},{"t":"다솜 — 「직렬로 이으니 바람개비가 빨라졌어.」","mis":"SC6-2-u3-X16"}],"explanation":["같은 극끼리예요.","직렬연결이 아니에요.","하민의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#19','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C15',3,'error','auto','전자석의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X21','SC6-2-u3-X20','SC6-2-u3-X19']::text[],false,'{"seq":19,"concept":"SC6-2-u3-C15","difficulty":3,"kind":"error","stem":"전자석의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태희 — 「전지 방향을 바꿔도 전자석의 극은 그대로야.」","correct":true,"mis_target":"SC6-2-u3-X21"},{"t":"규리 — 「전지를 더 이으면 클립이 더 붙어.」","mis":"SC6-2-u3-X20"},{"t":"현수 — 「스위치를 닫아야 자석이 돼.」","mis":"SC6-2-u3-X19"}],"explanation":["방향을 바꾸면 극도 바뀌어요.","나침반이 반대를 가리켰어요.","태희의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#20','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C16',3,'error','auto','전자석을 쓰는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X27','SC6-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC6-2-u3-C16","difficulty":3,"kind":"error","stem":"전자석을 쓰는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「자석 낚시 놀이도 전자석으로 물고기를 낚아.」","correct":true,"mis_target":"SC6-2-u3-X27"},{"t":"시아 — 「전기 자동차도 전자석으로 바퀴를 돌려.」","mis":"SC6-2-u3-X28"},{"t":"준혁 — 「세탁기는 전자석으로 통을 돌려.」","mis":"SC6-2-u3-X28"}],"explanation":["자석 낚시 놀이는 전기가 없어요.","영구 자석이에요.","은호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#21','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C20',3,'error','auto','전기 안전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X37','SC6-2-u3-X34','SC6-2-u3-X36']::text[],false,'{"seq":21,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"error","stem":"전기 안전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라엘 — 「콘센트 옆에 종이 상자를 쌓아 둬도 괜찮아.」","correct":true,"mis_target":"SC6-2-u3-X37"},{"t":"이든 — 「플러그는 머리 부분을 잡고 뽑아.」","mis":"SC6-2-u3-X34"},{"t":"보미 — 「손을 닦고 플러그를 꽂아.」","mis":"SC6-2-u3-X36"}],"explanation":["타기 쉬운 물건이에요.","치워야 해요.","라엘의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#22','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C22',3,'error','auto','실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X40']::text[],false,'{"seq":22,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"error","stem":"실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「계획은 크게 세우는 게 좋아. 지키든 못 지키든 상관없어.」","correct":true,"mis_target":"SC6-2-u3-X39"},{"t":"하나 — 「방을 나올 때 전등을 끄기로 했어.」","mis":"SC6-2-u3-X40"},{"t":"윤하 — 「저녁마다 점검표에 표시할 거야.」","mis":"SC6-2-u3-X40"}],"explanation":["지킬 수 있어야 해요.","구체적으로 정해요.","준서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#23','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C10',4,'essay','teacher','반딧불반 탐구 일지 ③을 보고, 전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로의 특징을 전구·전동기·버저로 견주어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-2-u3-C10","difficulty":4,"kind":"essay","stem":"반딧불반 탐구 일지 ③을 보고, 전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로의 특징을 전구·전동기·버저로 견주어 쓰세요.","answer_guide":{"answer":"예: 전지 두 개를 직렬연결한 회로가 전지 한 개를 이은 회로보다 전구는 더 밝고, 전동기 바람개비는 더 빨리 돌고, 버저 소리는 더 크다.","scoring_points":["전구를 견주었는가","전동기를 견주었는가","버저를 견주었는가"]},"explanation":["세 부품을 봐요.","두 회로를 견줘요.","직렬 쪽이 더 세요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#24','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C26',4,'mc','auto','「전기를 아끼는 것」과 「전기를 안전하게 쓰는 것」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X45','SC6-2-u3-X38']::text[],false,'{"seq":24,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"mc","stem":"「전기를 아끼는 것」과 「전기를 안전하게 쓰는 것」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둘은 함께 챙겨야 하며, 아끼려다 안전을 놓치거나 안전하다고 낭비해서는 안 된다","correct":true},{"t":"아끼기만 하면 안전은 저절로 지켜진다","mis":"SC6-2-u3-X45"},{"t":"안전만 지키면 아끼지 않아도 된다","mis":"SC6-2-u3-X45"},{"t":"둘 다 어른만 챙기면 된다","mis":"SC6-2-u3-X38"}],"explanation":["둘 다 중요해요.","하나만 챙기면 안 돼요.","함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u3_review_d#25','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C25',4,'mc','auto','토론을 마친 뒤 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":25,"concept":"SC6-2-u3-C25","difficulty":4,"kind":"mc","stem":"토론을 마친 뒤 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 쪽 근거에서 새로 알게 된 점을 정리하고, 내 생각을 다시 다듬는다","correct":true},{"t":"이긴 쪽만 옳다고 정리한다","mis":"SC6-2-u3-X44"},{"t":"상대 쪽 근거는 무시하고 내 주장만 되풀이한다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기와 상관없다고 정리한다","mis":"SC6-2-u3-X43"}],"explanation":["상대 근거도 봐요.","새로 안 점을 정리해요.","내 생각을 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
